	"sourcesContent": [
		"<template>\n    <div class=\"button-loading\">\n        <div class=\"loading-element\">\n            <div class=\"element-inner\"></div>\n        </div>\n        <div class=\"loading-element\">\n            <div class=\"element-inner\"></div>\n        </div>\n        <div class=\"loading-element\">\n            <div class=\"element-inner\"></div>\n        </div>\n    </div>\n</template>\n\n<script>\n    export default {\n        name: 'ButtonLoading'\n    }\n</script>\n\n<style scoped>\n    .button-loading {\n        width: 100%;\n        max-width: 45px;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n    }\n\n    .button-loading .loading-element {\n        width: 10px;\n        height: 10px;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        transform: rotate(45deg);\n        background-color: rgba(255, 255, 255, 0.3);\n    }\n\n    .button-loading .element-inner {\n        width: 10px;\n        height: 10px;\n        background-color: #ff4232;\n        animation: loading_animation 1.5s infinite ease-in-out both;\n        background-color: rgba(255, 255, 255, 0.5);\n    }\n\n    .button-loading .loading-element:nth-child(1) .element-inner {\n        animation-delay: -320ms;\n    }\n\n    .button-loading .loading-element:nth-child(2) .element-inner {\n        animation-delay: -160ms;\n    }\n\n    @keyframes loading_animation {\n        0%, 80%, 100% {\n            transform: scale(0);\n        }\n        40% {\n            transform: scale(1);\n        }\n    }\n</style>\n",
