ngth;\n      }, 5000); // 5 saniyede bir değiş\n    }\n  },\n  computed: {\n    ...mapGetters([\n      'socketGeneral',\n      'isJackpotModalOpen',\n      'isSidebarClosed',\n      'generalSettings',\n      'authToken',\n      'authUser',\n      'generalSidebarMobile'\n    ]),\n    appGetRouteName() {\n      return this.$route.name;\n    },\n    appHasBackground() {\n      return !['ProfileTransactions','ProfileGames','ProfileSettings','UnboxOverview','UnboxBox','BattlesOverview','BattlesCreate','BattlesGame','CashierLimiteds']\n        .includes(this.appGetRouteName);\n    },\n    isAdminRoute() {\n      return this.$route.path.startsWith('/admin');\n    },\n  },\n  watch: {\n    '$route': {\n      handler() {\n        if (this.$refs.mainContainer !== undefined) {\n          this.$nextTick(() => {\n            this.$refs.mainContainer.scrollTo({ top: 0, behavior: 'smooth' });\n          });\n        }\n      }\n    }\n  },\n  created() {\n    this.socketConnectGeneral();\n    if (this.authToken) {\n      this.$store.dispatch(\"authGetUser\");\n    }\n    this.startGifRotation();\n  },\n  beforeUnmount() {\n    clearInterval(this.gifInterval);\n  }\n}\n</script>\n\n<style>\n/* === MAIN CONTENT === */\nbody .app-page main {\n  position: fixed;\n  top: 61px;\n  right: 0;\n  bottom: 0;\n  height: calc(100% - 61px);\n  overflow-x: hidden;\n  overflow-y: auto;\n  scrollbar-width: none;\n  -ms-overflow-style: none;\n  transition: all 0.3s ease;\n  padding: 20px;\n}\n\n/* Sidebar açık */\nbody .app-page main.main-sidebar-open {\n  width: calc(100% - 16.375rem);\n  right: 0;\n}\n\n/* Sidebar kapalı → %95 genişlik */\nbody .app-page main.main-sidebar-closed {\n  width: 95%;\n  right: 0;\n}\n\n/* Chat açıkken (sadece PC) → sağdan 325px daralt */\n@media (min-width: 1176px) {\n  body .app-page main.main-chat-open {\n    width: calc(100% - 16.375rem - 325px);\n    right: 325px;\n  }\n  body .app-page main.main-sidebar-closed.main-chat-open {\n    width: calc(95% - 325px);\n   