nıcıya özel alanlar -->\n  <div v-else class=\"right-auth\">\n    <NavbarUserDropdown />\n\n    <div @click=\"openNotificationModal\" class=\"notification-icon\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">\n        <path fill=\"#7b6cb9\" d=\"M13.714 20.82h-4.4a.245.245 0 0 0-.235.216a3 3 0 0 0 0 .274c0 1.886 2.041 3.065 3.675 2.122a2.45 2.45 0 0 0 1.225-2.122a3 3 0 0 0 0-.274a.245.245 0 0 0-.265-.216m.735-15.68a4.3 4.3 0 0 1 .343-1.695a6.2 6.2 0 0 0-1.813-.618V1.71a1.47 1.47 0 1 0-2.94 0v1.127a6.6 6.6 0 0 0-2.793 1.254a9 9 0 0 0-3.283 7.105v.745c0 2.5-.588 4.963-1.715 7.193a.5.5 0 0 0 .225.657a.5.5 0 0 0 .216.049h17.64a.49.49 0 0 0 .441-.706a16 16 0 0 1-1.715-7.193v-.745a9.4 9.4 0 0 0-.137-1.656h-.059a4.4 4.4 0 0 1-4.41-4.4\"/>\n        <path fill=\"#7b6cb9\" d=\"M15.919 5.14c0 2.263 2.45 3.678 4.41 2.546a2.94 2.94 0 0 0 1.47-2.546c0-2.263-2.45-3.678-4.41-2.546a2.94 2.94 0 0 0-1.47 2.546\"/>\n      </svg>\n    </div>\n\n    <div class=\"chat-icon\" @click=\"handleChatButtonClick\">\n      <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">\n        <path fill=\"#7b6cb9\" d=\"M22 5a3 3 0 1 1-6 0a3 3 0 0 1 6 0\"/>\n        <path fill=\"#7b6cb9\" fill-rule=\"evenodd\" d=\"M6.25 14a.75.75 0 0 1 .75-.75h9a.75.75 0 0 1 0 1.5H7a.75.75 0 0 1-.75-.75\" clip-rule=\"evenodd\"/>\n        <path fill=\"#7b6cb9\" fill-rule=\"evenodd\" d=\"M3.464 20.536C4.93 22 7.286 22 12 22s7.071 0 8.535-1.465C22 19.072 22 16.714 22 12c0-1.399 0-2.59-.038-3.612a4.5 4.5 0 0 1-6.35-6.35C14.59 2 13.399 2 12 2C7.286 2 4.929 2 3.464 3.464C2 4.93 2 7.286 2 12s0 7.071 1.464 8.535M6.25 17.5a.75.75 0 0 1 .75-.75h6a.75.75 0 0 1 0 1.5H7a.75.75 0 0 1-.75-.75\" clip-rule=\"evenodd\"/>\n      </svg>\n    </div>\n  </div>\n\n  <!-- DİL SEÇİMİ: her durumda gözükecek -->\n  <div class=\"language-icon\" @click=\"openLanguageModal\">\n    <img src=\"@/assets/img/sidebar/lang.svg\" alt=\"Language\" />\n  </div>\n</div>\n\n\n   \n\n \n\n     \n      <LanguageModal \n  :show=\"showLanguageModal\" \n  @close=\"showLanguageModal = false\" \n/>\n       \n    </nav>\n</template>\n\n<script>\n\n    import { mapGetters, mapActions } from 'vuex';\n    import IconChatGradient from '@/components/icons/IconChatGradient';\n    import IconNavbarGradient from '@/components/icons/IconNavbarGradient';\n    import IconHome from '@/components/icons/IconHome';\n    import IconUser from '@/components/icons/IconUser';\n    import IconVault from '@/components/icons/IconVault';\n    import IconRakeback from '@/components/icons/IconRakeback';\n    import IconAffiliates from '@/components/icons/IconAffiliates';\n    import IconLeaderboard from '@/components/icons/IconLeaderboard';\n    import IconSignOut from '@/components/icons/IconSignOut';\n    import IconCrash from '@/components/icons/IconCrash';\n    import IconBlackjack from '@/components/icons/IconBlackjack';\n    import IconRoll from '@/components/icons/IconRoll';\n    import IconDuels from '@/components/icons/IconDuels';\n    import AuthButton from '@/components/AuthButton';\n    import NavbarHomeDropdown from '@/components/navbar/NavbarHomeDropdown';\n    import NavbarCashier from '@/components/navbar/NavbarCashier';\n    import NavbarUserDropdown from '@/components/navbar/NavbarUserDropdown';\n    \n    import LanguageModal from \"@/components/modals/LanguageModal.vue\";\n    \n    import { ref } from \"vue\"\nimport { useRouter } from \"vue-router\"\n    import axios from 'axios';\nimport { notification } from 'uikit';\n\n    const activeTab = ref(\"tab1\")\nconst router = useRouter()\nfunction goTo(tab, path) {\n  activeTab.value = tab\n  router.push(path)\n}\n    export default {\n        name: 'Navbar',\n        components: {\n            IconChatGradient,\n            IconNavbarGradient,\n            IconHome,\n            IconUser,\n            IconVault,\n            IconRakeback,\n            IconAffiliates,\n            IconLeaderboard,\n            IconSignOut,\n            IconCrash,\n            IconBlackjack,\n            IconRoll,\n            IconDuels,\n            AuthButton,\n            NavbarHomeDropdown,\n            NavbarCashier,\n            NavbarUserDropdown,\n           LanguageModal,\n          \n        },\n        data() {\n    return {\n       \n      notifications: [],\n      loading: false,\n      errorMessage: '',\n      isRotated: false, // SVG'nin döndüğünü izleyen durum\n      showLanguageDropdown: false,\n      showLanguageModal: false,\n      \n            currentLanguage: this.$i18n.locale,\n           languageOptions: {\n    en: require('@/assets/img/flags/united-states-of-america.svg'),\n    tr: require('@/assets/img/flags/tr.png'),\n    de: require('@/assets/img/flags/germany.svg'),\n    pt: require('@/assets/img/flags/brasil.svg'),\n    fr: require('@/assets/img/flags/france.svg'),\n    it: require('@/assets/img/flags/italy.png'),\n    zh: require('@/assets/img/flags/china.svg'),\n    hi: require('@/assets/img/flags/hint.png'),\n    ru: require('@/assets/img/flags/russia.png'),\n    id: require('@/assets/img/flags/id.webp'),\n    es: require('@/assets/img/flags/spain.svg'),\n}\n\n    };\n  },\n  mounted() {\n  window.addEventListener('resize', this.handleResize);\n},\n        methods: {\n          ...mapActions([\"modalsSetShow\"]),\n  openNotificationModal() {\n    this.modalsSetShow(\"Notifications\");  // Vuex'teki modalsShow = \"Notifications\"\n  },\n          handleResize() {\n    this.$forceUpdate(); // isMobile yeniden hesaplansın\n  },\n          toggleRotation() {\n      this.isRotated = !this.isRotated; // Döndürme durumunu değiştir\n    },\n    toggleSidebar() {\n      // Mevcut toggleSidebar işlevi\n      console.log(\"Sidebar toggled\");\n    },\n          toggleLanguageDropdown() {\n        this.showLanguageDropdown = !this.showLanguageDropdown;\n    },\n    changeLanguage(lang) {\n        this.currentLanguage = lang;\n        this.$i18n.locale = lang;\n        localStorage.setItem('language', lang); // Yeni dili kaydedin\n        this.showLanguageDropdown = false;\n    },\n     openLanguageModal() {\n      this.showLanguageModal = true;\n    },\n     \n    handleChatButtonClick() {\n        // Chat butonuna tıklandığında aynı işlevi uygular\n        this.generalSetSidebarMobile('Chat'); // Sidebar'ı \"Chat\" modu ile açar\n        \n    },\n            toggleNotificationsModal() {\n      this.showNotificationsModal = !this.showNotificationsModal;\n      if (this.showNotificationsModal) {\n        this.fetchNotifications(); // Modal açıldığında bildirimleri getir\n      }\n    },\n    async fetchNotifications() {\n      this.loading = true;\n      this.errorMessage = '';\n      try {\n        const response = await axios.get(`notices/${this.authUser.user._id}`);\n        this.notifications = response.data;\n      } catch (error) {\n        console.error('Error fetching notifications:', error);\n        this.errorMessage = 'Bildirimler yüklenirken bir hata oluştu.';\n      } finally {\n        this.loading = false;\n      }\n    },\n    formatDate(date) {\n      return new Date(date).toLocaleString();\n    },\n            ...mapActions([\n        'notificationShow', \n        'modalsSetShow', \n        'generalSetSidebarMobile', \n        'authLogoutUser',\n        'toggleSidebar' // Sidebar açma/kapama fonksiyonunu Vuex'ten alıyoruz\n    ]),\n            navbarVaultButton() {\n                this.modalsSetShow('Vault');\n                this.generalSetSidebarMobile(null);\n            }\n        },\n        beforeDestroy() {\n  window.removeEventListener('resize', this.handleResize);\n},\n        created() {\n    const savedLanguage = localStorage.getItem('language'); // Kaydedilen dili alın\n    if (savedLanguage) {\n        this.currentLanguage = savedLanguage; // Seçilen dili ayarlayın\n        this.$i18n.locale = savedLanguage; // i18n dili güncelleyin\n    }\n},\n        computed: {\n           currentLanguageIcon() {\n      const lang = this.$i18n.locale; // aktif dil\n      try {\n        return require(`@/assets/img/flags/${lang}.svg`);\n      } catch {\n        return require(\"@/assets/img/flags/en.svg\");\n      }\n    },\n        isMobile() {\n    return window.innerWidth <= 1175;\n  },\n          currentLanguageIcon() {\n            return this.languageOptions[this.currentLanguage];\n        },\n            ...mapGetters([\n                'generalSidebarMobile', \n                'authUser'\n            ])\n        }\n    }\n</script>\n\n<style scoped>\n    nav#navbar {\n        width: 100%;\n        height: 60px;\n        position: fixed;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        top: 0;\n        left: 0;\n        \n        background: var(--navbar-bg);\n   \n        z-index: 50;\n    }\n\n    nav#navbar .navbar-left,\n    nav#navbar .navbar-right  {\n        \n        display: flex;\n        align-items: center;\n        z-index: 1;\n    }\n\n    nav#navbar .navbar-right  {\n        justify-content: flex-end;\n    }\n\n  \n\n    nav#navbar .navbar-left a.link-logo {\n        display: flex;\n        align-items: center;\n        margin-right: 30px;\n    }\n\n    nav#navbar .navbar-left a.link-logo img {\n        height: 41px;\n        width: 100%;\n    }\n\n    nav#navbar .navbar-left a.link-home {\n        width: 50px;\n        height: 50px;\n        position: relative;\n        margin-right: 10px;\n        padding: 1px;\n        z-index: 1;\n    }\n\n    nav#navbar .navbar-left a.link-home::before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        background: linear-gradient(180deg, rgba(0, 133, 255, 0) 0%, #328adb 100%);\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n        z-index: -1;\n    }\n\n    nav#navbar .navbar-left a.link-home::after {\n        content: '';\n        width: calc(100% - 2px);\n        height: calc(100% - 2px);\n        position: absolute;\n        top: 1px;\n        left: 1px;\n        background: #061628;\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n        z-index: -1;\n    }\n\n    nav#navbar .navbar-left a.link-home .link-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        background: linear-gradient(255deg, rgba(59, 126, 183, 0.5) -70%, rgba(20, 80, 129, 0.5) 90%);\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n        transition: background 0.3s ease;\n    } \n\n    nav#navbar .navbar-left a.link-home:hover .link-inner {\n        background: linear-gradient(255deg, #3b7eb7 -70%, #145081 90%);\n    }\n\n    nav#navbar .navbar-left a.link-home .link-inner svg {\n        fill: #6e95b6;\n        transition: fill 0.3s ease;\n    }\n\n    nav#navbar .navbar-left a.link-home:hover .link-inner svg {\n        fill: #ffffff;\n    }\n\n    nav#navbar .navbar-mid button.auth-button {\n        display: none;\n    }\n\n     nav#navbar .navbar-mid {\n        display: none;\n    }\n    nav#navbar .right-auth {\n        display: flex;\n        align-items: center;\n    }\n\n    nav#navbar a.link-rewards {\n         \n        height: 40px;\n        position: relative;\n        display: flex;\n        flex-direction: column;\n        justify-content: center;\n        align-items: flex-end;\n        margin-left: 25px;\n        padding: 0 15px 0 50px;\n        border-radius: 5px;\n        background: var(--button);\n    }\n\n    nav#navbar a.link-rewards img {\n        height: 41px;\n        position: absolute;\n        top: 50%;\n        left: -15px;\n        transform: translate(0, -50%);\n        filter: drop-shadow(0px 0px 4px rgba(7, 211, 143, 0.35));\n    }\n\n    nav#navbar a.link-rewards span {\n    font-family: 'Rubik', sans-serif;\n    font-size: 14px;\n    font-weight: 900;\n    text-transform: uppercase; /* daha güçlü görünüm için */\n    \n    /* Gradient yazı */\n    background: linear-gradient(180deg, \n        #ffffff 0%, \n        #ffffff 35%, \n        #7e7e7e 70%, \n        #18d99d 95%);\n    -webkit-background-clip: text;\n    -webkit-text-fill-color: transparent;\n    background-clip: text;\n\n    /* Stroke + Glow */\n    -webkit-text-stroke: 0.8px rgba(0, 0, 0, 0.5);\n    text-shadow: 0px 2px 6px rgba(0, 0, 0, 0.45),\n                 0px 0px 10px rgba(253, 253, 253, 0.6);\n\n    letter-spacing: 0.5px;\n    display: inline-block;\n}\n\n\n    nav#navbar .navbar-right button.button-toggle {\n        width: 36px;\n        height: 28px;\n        display: none;\n        filter: drop-shadow(0px 1.8px 1.8px rgba(0, 0, 0, 0.10));\n    }\n\n    nav#navbar .navbar-right button.button-toggle .button-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        background: #214059;\n        clip-path: polygon(4px 0, calc(100% - 4px) 0, 100% 25%, 100% 75%, calc(100% - 4px) 100%, 4px 100%, 0 75%, 0 25%);\n    }\n\n    nav#navbar .navbar-right button.button-toggle .button-inner svg {\n        fill: #5b7b95;\n        transition: fill 0.3s ease;\n    }\n\n    nav#navbar .navbar-right button.button-toggle:hover .button-inner svg {\n        fill: #ffffff;\n    }\n\n    nav#navbar .navbar-mobile {\n    width: 60vw;\n    height: 100vh;\n    position: fixed;\n    top: 0;\n    left: 0;\n    transform: translateX(-100%); /* Başlangıçta gizli */\n    padding: 95px 21px 0 21px;\n    overflow-y: scroll;\n    background-color: #021423;\n    z-index: 999; /* En üstte görüntülenmesi için */\n    transition: transform 0.3s ease;\n}\n\n    nav#navbar .navbar-mobile a,\n    nav#navbar .navbar-mobile button {\n     