		"<template>\n  <div\n    class=\"navbar-user-dropdown\"\n    :class=\"[\n      { 'dropdown-open': navbarDropdown === true }, \n      'dropdown-' + navbarGetLevelColor,\n      'dropdown-' + authUser.user.rank\n    ]\"\n  >\n    <button v-on:click=\"navbarSetDropdown(!navbarDropdown)\" class=\"button-toggle\">\n      <div class=\"button-avatar\">\n        \n        <!-- Sadece VIP badge gösteriliyor -->\n        <img\n          v-if=\"vipBadgeImage\"\n          :src=\"vipBadgeImage\"\n          class=\"vip-badge-only\"\n          alt=\"VIP\"\n        />\n      </div>\n      <div class=\"button-info\">\n        <div class=\"info-username\">\n          <span v-html=\"authUser.user.username\"></span>\n          <IconDropdown />\n        </div>\n        <div class=\"info-level\">\n          <div class=\"info-progress-bar-with-label\" v-if=\"nextVipLevel && nextVipLevel.requiredXp\">\n            <div class=\"bar-outer\">\n              <div\n                class=\"bar-inner\"\n                :style=\"{ width: vipProgress + '%' }\"\n              ></div>\n            </div>\n         \n          </div>\n        </div>\n      </div>\n    </button>\n\n    <div\n      class=\"dropdown-menu\"\n      v-bind:class=\"{ 'menu-admin': authUser.user.rank === 'admin' }\"\n    >\n      <div class=\"menu-inner\">\n        <div class=\"dropdown-user-info\" v-if=\"vipLevel\">\n          <div class=\"vip-avatar-box\">\n             <img \n          v-if=\"authUser?.user?.avatar\" \n          :src=\"authUser.user.avatar\" \n          alt=\"Avatar\" \n          class=\"avatar-image\"\n        />\n            <img\n              v-if=\"vipBadgeImage\"\n              :src=\"vipBadgeImage\"\n              class=\"vip-badge\"\n              alt=\"VIP\"\n            />\n          </div>\n          <div class=\"vip-level-label\">\n            <span>{{ vipLevel.levelName }}</span>\n            <img\n              v-if=\"vipBadgeImage\"\n              :src=\"vipBadgeImage\"\n              class=\"vip-badge-small\"\n            />\n          </div>\n          <div class=\"vip-progress-wrap\">\n            <div class=\"vip-progress-labels\">\n              <span>VIP {{ vipLevel.level }}</span>\n              <span v-if=\"nextVipLevel\">VIP {{ nextVipLevel.level }}</span>\n            </div>\n            <div class=\"vip-progress-bar\">\n              <div class=\"bar-fill\" :style=\"{ width: vipProgress + '%' }\">\n                <span class=\"bar-percent\">{{ vipProgress }}%</span>\n              </div>\n            </div>\n            \n          </div>\n        </div>\n\n        <router-link v-on:click.native=\"navbarSetDropdown(false)\" to=\"/profile\">\n          <IconUser />\n          {{ $t('navbar.7') }}\n        </router-link>\n        <button v-on:click=\"navbarVaultButton()\">\n          <IconVault />\n          {{ $t('navbar.8') }}\n        </button>\n        <router-link v-on:click.native=\"navbarSetDropdown(false)\" to=\"/rewards\">\n          <IconRakeback />\n          {{ $t('navbar.9') }}\n        </router-link>\n        <router-link v-on:click.native=\"navbarSetDropdown(false)\" to=\"/affiliates\">\n          <IconAffiliates />\n          {{ $t('navbar.10') }}\n        </router-link>\n        <router-link v-on:click.native=\"navbarSetDropdown(false)\" to=\"/leaderboard\">\n          <IconLeaderboard />\n          {{ $t('navbar.11') }}\n        </router-link>\n        <router-link\n          v-if=\"authUser.user.rank === 'admin'\"\n          v-on:click.native=\"navbarSetDropdown(false)\"\n          to=\"/admin\"\n        >\n          <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 448 512\">\n            <path\n              d=\"M144 144v48H304V144c0-44.2-35.8-80-80-80s-80 35.8-80 80zM80 192V144C80 64.5 144.5 0 224 0s144 64.5 144 144v48h16c35.3 0 64 28.7 64 64V448c0 35.3-28.7 64-64 64H64c-35.3 0-64-28.7-64-64V256c0-35.3 28.7-64 64-64H80z\"\n            />\n          </svg>\n          ADMIN\n        </router-link>\n        <button v-on:click=\"navbarLogoutButton()\">\n          <IconSignOut />\n          {{ $t('navbar.12') }}\n        </button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\nimport { mapGetters, mapActions } from 'vuex';\nimport IconDropdown from '@/components/icons/IconDropdown';\nimport IconUser from '@/components/icons/IconUser';\nimport IconVault from '@/components/icons/IconVault';\nimport IconRakeback from '@/components/icons/IconRakeback';\nimport IconAffiliates from '@/components/icons/IconAffiliates';\nimport IconLeaderboard from '@/components/icons/IconLeaderboard';\nimport IconSignOut from '@/components/icons/IconSignOut';\n\nexport default {\n  name: 'NavbarUserDropdown',\n  components: {\n    IconDropdown,\n    IconUser,\n    IconVault,\n    IconRakeback,\n    IconAffiliates,\n    IconLeaderboard,\n    IconSignOut\n  },\n  data() {\n    return {\n      navbarDropdown: false\n    }\n  },\n  methods: {\n    ...mapActions('vip', ['fetchUserVip']),\n    ...mapActions([\n      'modalsSetShow', \n      'authLogoutUser'\n    ]),\n    navbarSetDropdown(value) {\n      this.navbarDropdown = value;\n    },\n    navbarVaultButton() {\n      this.modalsSetShow('Vault');\n      this.navbarSetDropdown(false);\n    },\n    navbarLogoutButton() {\n      this.navbarSetDropdown(false);\n      this.authLogoutUser();\n    }\n  },\n  computed: {\n    ...mapGetters(['authUser']),\n    ...mapGetters('vip', [\n      'vipLevel',\n      'userXp',\n      'nextVipLevel',\n      'vipProgress',\n      'vipDisplayXp',\n      'vipNextXp'\n    ]),\n\n    vipBadgeImage() {\n      return this.vipLevel?.vipBadgeImage\n        ? process.env.VUE_APP_BACKEND_URL + this.vipLevel.vipBadgeImage\n        : null;\n    },\n\n    navbarGetLevel() {\n      let level = Math.floor(Math.pow(this.authUser.user.xp, 1 / 3));\n      return level >= 100 ? 100 : level;\n    },\n    navbarGetLevelColor() {\n      let color = '';\n      if(this.navbarGetLevel >= 2 && this.navbarGetLevel < 26) { color = 'blue'; }\n      else if(this.navbarGetLevel >= 26 && this.navbarGetLevel < 51) { color = 'green'; }\n      else if(this.navbarGetLevel >= 51 && this.navbarGetLevel < 76) { color = 'orange'; }\n      else if(this.navbarGetLevel >= 76 && this.navbarGetLevel < 100) { color = 'red'; }\n      else if(this.navbarGetLevel >= 100) { color = 'purple'; }\n      return color;\n    }\n  },\n  created() {\n    this.fetchUserVip();\n\n    document.addEventListener('click', (event) => {\n      if(!this.$el.contains(event.target) && this.navbarDropdown === true) {\n        this.navbarSetDropdown(false);\n      }\n    });\n  }\n}\n</script>\n\n\n<style scoped>\n    .navbar-user-dropdown {\n        position: relative;\n    }\n\n    .navbar-user-dropdown button.button-toggle {\n        display: flex;\n    align-items: center;\n    background: var(--background1);\n    border-radius: 12px;\n    padding-left: 10px; \n    padding-right: 10px;\n    padding-top: 2px;\n    padding-bottom: 2px;\n    height: 40px;\n    position: relative;\n    z-index: 1;\n    }\n\n\n\n    .navbar-user-dropdown .button-avatar {\n        width: 35px;\n        height: 35px;\n        display: flex;\n        justify-content: center;\n        align-items: flex-end;\n        margin-right: 10px;\n        border-radius: 50%;\n        \n        overflow: hidden;\n    }\n\n   \n\n    .navbar-user-dropdown .button-avatar .avatar-image {\n        width: 100%;\n        height: 100%;\n    }\n\n    .navbar-user-dropdown .button-info {\n\n    }\n\n    .navbar-user-dropdown .info-username {\n        display: flex;\n        align-items: center;\n        font-size: 14px;\n        font-weight: 700;\n        color: #ffffff;\n    }\n\n    .navbar-user-dropdown .info-username span {\n       \n        max-width: 80px;\n        white-space: nowrap;\n        overflow: hidden;\n        text-overflow: ellipsis;\n    }\n\n    .vip-badge-on-avatar {\n  position: absolute;\n  bottom: -4px;\n      left: 25px;\n  width: 20px;\n  height: 20px;\n 