		"<template>\r\n  <transition name=\"fade\">\r\n    <div v-if=\"show\" class=\"language-overlay\">\r\n      <div class=\"language-wrapper\">\r\n        <!-- Header -->\r\n        <div class=\"language-header\">\r\n          <h2 class=\"language-title\">{{ $t(\"sidebar.language\") }}</h2>\r\n          <button class=\"close-btn\" @click=\"close\" aria-label=\"Close modal\">\r\n            ✕\r\n          </button>\r\n        </div>\r\n\r\n        <!-- Body -->\r\n        <div class=\"language-grid\">\r\n          <div\r\n            v-for=\"lang in languages\"\r\n            :key=\"lang.code\"\r\n            class=\"language-card\"\r\n            :class=\"{ active: currentLang === lang.code }\"\r\n            @click=\"selectLanguage(lang.code)\"\r\n          >\r\n            <img :src=\"lang.flag\" :alt=\"`${lang.name} flag`\" class=\"flag-icon\" />\r\n            <span class=\"language-name\">{{ lang.name }}</span>\r\n            <div v-if=\"currentLang === lang.code\" class=\"check-badge\">✓</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </transition>\r\n</template>\r\n\r\n<script>\r\nimport i18n from \"@/locales/i18n\";\r\n\r\nexport default {\r\n  name: \"LanguageModal\",\r\n  props: {\r\n    show: { type: Boolean, default: false }\r\n  },\r\n  data() {\r\n    return {\r\n      languages: [\r\n        { code: \"en\", name: \"English\", flag: require(\"@/assets/img/flags/en.svg\") },\r\n        { code: \"tr\", name: \"Türkçe\", flag: require(\"@/assets/img/flags/tr.svg\") },\r\n        { code: \"de\", name: \"Deutsch\", flag: require(\"@/assets/img/flags/de.svg\") },\r\n        { code: \"pt\", name: \"Português\", flag: require(\"@/assets/img/flags/pt.svg\") },\r\n        { code: \"fr\", name: \"Français\", flag: require(\"@/assets/img/flags/fr.svg\") },\r\n        { code: \"it\", name: \"Italiano\", flag: require(\"@/assets/img/flags/it.svg\") },\r\n        { code: \"zh\", name: \"中文\", flag: require(\"@/assets/img/flags/china.svg\") },\r\n        { code: \"hi\", name: \"हिन्दी\", flag: require(\"@/assets/img/flags/hint.png\") },\r\n        { code: \"ru\", name: \"Русский\", flag: require(\"@/assets/img/flags/ru.svg\") },\r\n        { code: \"id\", name: \"Bahasa Indonesia\", flag: require(\"@/assets/img/flags/id.svg\") },\r\n        { code: \"es\", name: \"Español\", flag: require(\"@/assets/img/flags/es.svg\") },\r\n        { code: \"fil\", name: \"Filipino\", flag: require(\"@/assets/img/flags/ph.svg\") }\r\n      ]\r\n    };\r\n  },\r\n  computed: {\r\n    currentLang() {\r\n      return i18n.global.locale.value;\r\n    }\r\n  },\r\n  methods: {\r\n    close() {\r\n      this.$emit(\"close\");\r\n    },\r\n    selectLanguage(code) {\r\n      i18n.global.locale.value = code;\r\n      localStorage.setItem(\"language\", code);\r\n      this.close();\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n/* Fade transition */\r\n.fade-enter-active,\r\n.fade-leave-active {\r\n  transition: opacity 0.3s ease;\r\n}\r\n.fade-enter-from,\r\n.fade-leave-to {\r\n  opacity: 0;\r\n}\r\n\r\n/* Fullscreen overlay */\r\n.language-overlay {\r\n  position: fixed;\r\n  inset: 0;\r\n  background: radial-gradient(circle at top, rgba(40, 40, 70, 0.95), rgba(15, 15, 30, 0.98));\r\n  backdrop-filter: blur(10px);\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: flex-start;\r\n  padding: 60px 20px;\r\n  z-index: 20000;\r\n  overflow-y: auto;\r\n}\r\n\r\n/* Wrapper */\r\n.language-wrapper {\r\n  width: 100%;\r\n  max-width: 1000px;\r\n  color: #fff;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 40px;\r\n  animation: fadeInUp 0.4s ease;\r\n}\r\n\r\n/* Header */\r\n.language-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n}\r\n.language-title {\r\n  font-size: 28px;\r\n  font-weight: 800;\r\n  background: linear-gradient(90deg, #ffde59, #ffa033);\r\n  -webkit-background-clip: text;\r\n  -webkit-text-fill-color: transparent;\r\n}\r\n.close-btn {\r\n  background: rgba(255, 255, 255, 0.1);\r\n  border: none;\r\n  color: #fff;\r\n  font-size: 22px;\r\n  padding: 8px 14px;\r\n  border-radius: 50%;\r\n  cursor: pointer;\r\n  transition: all 0.25s ease;\r\n}\r\n.close-btn:hover {\r\n  background: rgba(255, 255, 255, 0.25);\r\n  transform: rotate(90deg);\r\n}\r\n\r\n/* Grid */\r\n.language-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));\r\n  gap: 24px;\r\n}\r\n\r\n/* Card */\r\n.language-card {\r\n  background: rgba(255, 255, 255, 0.05);\r\n  border-radius: 16px;\r\n  padding: 20px 16px;\r\n  text-align: center;\r\n  cursor: pointer;\r\n  transition: all 0.3s ease;\r\n  position: relative;\r\n  border: 1px solid transparent;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  gap: 12px;\r\n}\r\n.language-card:hover {\r\n  transform: translateY(-6px) scale(1.03);\r\n  background: rgba(255, 255, 255, 0.08);\r\n  box-shadow: 0 10px 24px rgba(0, 0, 0, 0.3);\r\n}\r\n.language-card.active {\r\n  border: 2px solid #ffde59;\r\n  background: rgba(255, 222, 89, 0.12);\r\n  box-shadow: 0 0 18px rgba(255, 222, 89, 0.6);\r\n}\r\n\r\n/* Check badge */\r\n.check-badge {\r\n  position: absolute;\r\n  top: 10px;\r\n  right: 12px;\r\n  font-size: 18px;\r\n  font-weight: bold;\r\n  color: #ffde59;\r\n}\r\n\r\n/* Flag */\r\n.flag-icon {\r\n  width: 48px;\r\n  height: 34px;\r\n  border-radius: 6px;\r\n  object-fit: cover;\r\n  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);\r\n}\r\n\r\n/* Text */\r\n.language-name {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n  letter-spacing: 0.4px;\r\n}\r\n\r\n/* Animation */\r\n@keyframes fadeInUp {\r\n  from {\r\n    opacity: 0;\r\n    transform: translateY(25px);\r\n  }\r\n  to {\r\n    opacity: 1;\r\n    transform: translateY(0);\r\n  }\r\n}\r\n</style>\r\n",
		"import { createI18n } from 'vue-i18n'\r\n\r\n// Çeviri dosyalarını içeri aktarın\r\nimport en from './en.json'\r\nimport tr from './tr.json'\r\nimport de from './de.json'\r\nimport pt from './pt.json'\r\nimport fr from './fr.json'\r\nimport it from './it.json'\r\nimport zh from './zh.json'\r\nimport hi from './hi.json'\r\nimport ru from './ru.json'\r\nimport id from './id.json'\r\nimport es from './es.json'\r\nimport fil from './fil.json' // Filipince çeviri\r\n\r\nconst messages = {\r\n  en,\r\n  tr,\r\n  de,\r\n  pt,\r\n  fr,\r\n  it,\r\n  zh,\r\n  hi,\r\n  ru,\r\n  id,\r\n  es,\r\n  fil,\r\n}\r\n\r\n// Kullanıcının IP'sine göre dil belirleme\r\nasync function detectLanguage() {\r\n  try {\r\n    const res = await fetch(\"https://ipapi.co/json/\") // alternatif: ipinfo.io\r\n    const data = await res.json()\r\n    const countryCode = data.country_code // Örn: \"TR\", \"DE\", \"PH\"\r\n\r\n    // Ülke → Dil kodu eşleştirme\r\n    const map = {\r\n      IN: 'hi',   // Hindistan\r\n      DE: 'de',   // Almanya\r\n      ES: 'es',   // İspanya\r\n      FR: 'fr',   // Fransa\r\n      ID: 'id',   // Endonezya\r\n      IT: 'it',   // İtalya\r\n      PT: 'pt', \r\n      BR: 'pt',   \r\n      RU: 'ru',   // Rusya\r\n      TR: 'tr',   // Türkiye\r\n      CN: 'zh',   // Çin\r\n      HK: 'zh',\r\n      MO: 'zh',\r\n  TW: 'zh',\r\n      PH: 'fil',  // Filipinler ✅\r\n    }\r\n\r\n    return map[countryCode] || 'en' // eşleşme yoksa İngilizce\r\n  } catch (e) {\r\n    return 'en'\r\n  }\r\n}\r\n\r\nconst savedLanguage = localStorage.getItem('language')\r\n\r\n// i18n oluşturma\r\nconst i18n = createI18n({\r\n  legacy: false,\r\n  locale: savedLanguage || 'en', // başlangıçta en\r\n  fallbackLocale: 'en',\r\n  messages,\r\n  globalInjection: true,\r\n})\r\n\r\n// IP'den dili algıla ve ayarla\r\ndetectLanguage().then(lang => {\r\n  i18n.global.locale.value = savedLanguage || lang\r\n  localStorage.setItem('language', i18n.global.locale.value)\r\n})\r\n\r\nexport default i18n\r\n",
