n    .rain-join .user-avatar.avatar-green {\n        border: 2px solid #b8e92d;\n    }\n\n    .rain-join .user-avatar.avatar-orange {\n        border: 2px solid #fca311;\n    }\n\n    .rain-join .user-avatar.avatar-red {\n        border: 2px solid #ff4e4e;\n    }\n\n    .rain-join .user-avatar.avatar-purple {\n        border: 2px solid #6953f1;\n    }\n\n    .rain-join .user-avatar.avatar-partner {\n        border: 2px solid #eca822;\n    }\n\n    .rain-join .user-avatar.avatar-mod {\n        border: 2px solid #ffb703;\n    }\n\n    .rain-join .user-avatar.avatar-admin {\n        border: 2px solid #01e0a3;\n    }\n\n    .rain-join .user-avatar .avatar-image {\n        width: 18px;\n        height: 18px;\n    }\n\n    .rain-join .user-text {\n        display: flex;\n        align-items: center;\n        font-size: 14px;\n        font-weight: 800;\n        color: #ffffff;\n    }\n\n    .rain-join .user-text span {\n        margin-left: 4px;\n    }\n\n    .rain-join .text-username {\n        max-width: 65px;\n        margin-right: 4px;\n        white-space: nowrap;\n        overflow: hidden;\n        text-overflow: ellipsis;\n    }\n\n    .rain-join .type-site {\n        width: calc(100% - 20px);\n        position: relative;\n        padding: 4px 0;\n    }\n\n    .rain-join .site-avatar {\n        width: 34px;\n        height: 34px;\n        position: absolute;\n        top: 50%;\n        left: 0;\n        transform: translate(0, -50%);\n        padding: 1px;\n        z-index: 1;\n    }\n\n    .rain-join .site-avatar::before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        border-radius: 50%;\n        background: linear-gradient(180deg, rgba(0, 255, 194, 0) 0%, #01e0a3 100%);\n        z-index: -1;\n    }\n\n    .rain-join .avatar-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: flex-end;\n      