		"<template>\n  <footer id=\"footer\">\n    <div class=\"footer-top\">\n      <!-- Logo & Info -->\n      <div class=\"top-info\">\n        <img src=\"@/assets/img/logo_small.png\" />\n        <div class=\"info-text\">\n          {{ $t('footer.1') }}\n          <span class=\"gradient-green\">{{ $t('footer.2') }}</span>\n        </div>\n      </div>\n\n      <!-- Links -->\n      <div class=\"top-links\">\n        <!-- Oyunlar -->\n        <div class=\"links-section\">\n          <div class=\"section-title\">{{ $t('footer.3') }}</div>\n          <router-link to=\"/battles\"><IconBattles /><span class=\"gradient-orange\">Battles</span></router-link>\n          <router-link to=\"/crash\"><IconCrash /><span class=\"gradient-yellow\">Crash</span></router-link>\n          <router-link to=\"/roll\"><IconRoll /><span class=\"gradient-green\">Roll</span></router-link>\n          <router-link to=\"/duels\"><IconDuels /><span class=\"gradient-red\">Dice Duels</span></router-link>\n        </div>\n\n        <!-- Kurallar -->\n        <div class=\"links-section\">\n          <div class=\"section-title\">{{ $t('footer.4') }}</div>\n          <button @click=\"modalsSetShow('Terms')\">{{ $t('footer.5') }}</button>\n          <button @click=\"modalsSetShow('Faq')\">{{ $t('footer.6') }}</button>\n          <button @click=\"modalsSetShow('Privacy')\">{{ $t('footer.7') }}</button>\n        </div>\n\n        <!-- Bilgiler -->\n        <div class=\"links-section\">\n          <div class=\"section-title\">{{ $t('footer.8') }}</div>\n          <router-link to=\"/affiliates\">{{ $t('footer.9') }}</router-link>\n          <router-link to=\"/leaderboard\">{{ $t('footer.10') }}</router-link>\n          <button @click=\"modalsSetShow('Fair')\">{{ $t('footer.12') }}</button>\n        </div>\n\n        <!-- Sosyal Medya -->\n        <div class=\"links-section\">\n          <div class=\"section-title\">{{ $t('footer.13') }}</div>\n\n          <!-- her ikon koşullu render ediliyor -->\n          <