		"<template>\n  <div class=\"modals\">\n    <!-- Overlay -->\n    <transition name=\"fade\">\n      <div class=\"modals-overlay\" v-show=\"modalsShow !== null\"></div>\n    </transition>\n\n    <!-- Desktop için slide-fade, mobil için slide-up -->\n    <transition :name=\"isMobile ? 'slide-up' : 'slide-fade'\" mode=\"out-in\">\n      <div\n        class=\"modals-holder\"\n        v-if=\"modalsShow !== null\"\n        @click=\"modalsCloseButton\"\n        :class=\"{ 'is-mobile': isMobile }\"\n      >\n        <div class=\"holder-body\">\n          <div class=\"body-modal\" :class=\"{ 'bottom-sheet': isMobile }\">\n            <!-- Close button (bazı modallar hariç) -->\n            <button\n              v-if=\"['DuelsGame', 'BattlesSelect', 'Box'].includes(modalsShow) !== true\"\n              @click=\"modalsSetShow(null)\"\n              class=\"button-close\"\n            >\n              <div class=\"button-inner\">\n                <IconClose />\n              </div>\n            </button>\n\n            <!-- Dinamik modal -->\n            <component :is=\"'Modal' + modalsShow\" />\n          </div>\n        </div>\n      </div>\n    </transition>\n  </div>\n</template>\n\n<script>\nimport { mapGetters, mapActions } from \"vuex\";\nimport IconClose from \"@/components/icons/IconClose\";\n\n/* Tüm modal importlarını koruyorum */\nimport ModalCaptcha from \"@/components/modals/ModalCaptcha\";\nimport ModalLogin from \"@/components/modals/ModalLogin\";\nimport ModalLink from \"@/components/modals/ModalLink\";\nimport ModalLinkRoblox from \"@/components/modals/ModalLinkRoblox\";\nimport ModalReset from \"@/components/modals/ModalReset\";\nimport ModalClaim from \"@/components/modals/ModalClaim\";\nimport ModalChatRules from \"@/components/modals/ModalChatRules\";\nimport ModalChatUser from \"@/components/modals/ModalChatUser\";\nimport ModalRemove from \"@/components/modals/ModalRemove\";\nimport ModalMute from \"@/components/modals/ModalMute\";\nimport ModalBan from \"@/components/modals/ModalBan\";\nimport ModalCashier from \"@/components/modals/ModalCashier\";\nimport ModalRobux from \"@/components/modals/ModalRobux\";\nimport ModalCredit from \"@/components/modals/ModalCredit\";\nimport ModalPapara from \"@/components/modals/ModalPapara\";\nimport ModalPayfix from \"@/components/modals/ModalPayfix\";\nimport ModalPix from \"@/components/modals/ModalPix\";\nimport ModalCrypto from \"@/components/modals/ModalCrypto\";\nimport ModalGift from \"@/components/modals/ModalGift\";\nimport ModalProceed from \"@/components/modals/ModalProceed\";\nimport ModalTwoStep from \"@/components/modals/ModalTwoStep\";\nimport ModalVault from \"@/components/modals/ModalVault\";\nimport ModalTip from \"@/components/modals/ModalTip\";\nimport ModalFair from \"@/components/modals/ModalFair\";\nimport ModalFairSeed from \"@/components/modals/ModalFairSeed\";\nimport ModalFairGame from \"@/components/modals/ModalFairGame\";\nimport ModalFaq from \"@/components/modals/ModalFaq\";\nimport ModalTerms from \"@/components/modals/ModalTerms\";\nimport ModalPrivacy from \"@/components/modals/ModalPrivacy\";\nimport ModalBlackjackRules from \"@/components/modals/ModalBlackjackRules\";\nimport ModalDuelsGame from \"@/components/modals/ModalDuelsGame\";\nimport ModalBattlesModes from \"@/components/modals/ModalBattlesModes\";\nimport ModalBattlesSelect from \"@/components/modals/ModalBattlesSelect\";\nimport ModalBox from \"@/components/modals/ModalBox\";\nimport ModalAdminConfirm from \"@/components/modals/ModalAdminConfirm\";\nimport ModalAdminUser from \"@/components/modals/ModalAdminUser\";\nimport ModalAdminAffiliate from \"@/components/modals/ModalAdminAffiliate\";\nimport ModalAdminCrypto from \"@/components/modals/ModalAdminCrypto\";\nimport ModalSpin from \"@/components/modals/ModalSpin\";\nimport ModalLisance from \"@/components/modals/ModalLisance\";\nimport ModalNotifications from \"@/components/modals/ModalNotifications\";\nimport ModalSocialComplete from \"@/components/modals/ModalSocialComplete\";\n\nexport default {\n  components: {\n    IconClose,\n    ModalSpin,\n    ModalCaptcha,\n    ModalLogin,\n    ModalLink,\n    ModalLinkRoblox,\n    ModalReset,\n    ModalClaim,\n    ModalChatRules,\n    ModalChatUser,\n    ModalRemove,\n    ModalMute,\n    ModalBan,\n    ModalVault,\n    ModalCashier,\n    ModalRobux,\n    ModalCredit,\n    ModalPayfix,\n    ModalPapara,\n    ModalPix,\n    ModalLisance,\n    ModalCrypto,\n    ModalGift,\n    ModalProceed,\n    ModalTwoStep,\n    ModalTip,\n    ModalFair,\n    ModalFairSeed,\n    ModalFairGame,\n    ModalFaq,\n    ModalTerms,\n    ModalPrivacy,\n    ModalBlackjackRules,\n    ModalDuelsGame,\n    ModalBattlesModes,\n    ModalBattlesSelect,\n    ModalBox,\n    ModalAdminConfirm,\n    ModalAdminUser,\n    ModalAdminAffiliate,\n    ModalAdminCrypto,\n    ModalNotifications,\n    ModalSocialComplete,\n  },\n  data() {\n    return {\n      isMobile: false,\n    };\n  },\n  mounted() {\n    this.checkMobile();\n    window.addEventListener(\"resize\", this.checkMobile);\n  },\n  beforeUnmount() {\n    window.removeEventListener(\"resize\", this.checkMobile);\n  },\n  methods: {\n    ...mapActions([\"modalsSetShow\"]),\n    modalsCloseButton(e) {\n      if (\n        e.target.className === \"modals-holder\" ||\n        e.target.className === \"holder-body\"\n      ) {\n        this.modalsSetShow(null);\n      }\n    },\n    checkMobile() {\n      this.isMobile = window.innerWidth <= 768;\n    },\n  },\n  computed: {\n    ...mapGetters([\"modalsShow\"]),\n  },\n};\n</script>\n\n<style scoped>\n/* === Overlay === */\n.modals .modals-overlay {\n  width: 100%;\n  height: 100%;\n  position: fixed;\n  top: 0;\n  left: 0;\n  background-color: rgba(2, 2, 14, 0.85);\n  user-select: none;\n  z-index: 101;\n}\n\n/* === Holder === */\n.modals .modals-holder {\n  width: 100%;\n  height: 100%;\n  position: fixed;\n  top: 0;\n  left: 0;\n  z-index: 102;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  overflow-y: auto;\n  -ms-overflow-style: none;\n  scrollbar-width: none;\n}\n.modals .modals-holder::-webkit-scrollbar {\n  display: none;\n}\n\n/* === Modal Desktop === */\n.body-modal {\n  position: relative;\n  border-radius: 15px;\n  background: var(--background);\n  box-shadow: 0px 4px 15px rgba(0, 0, 0, 0.25);\n  \n  width: 100%;\n  margin: auto;\n  overflow: hidden;\n}\n\n/* === Modal Bottom Sheet (Mobil) === */\n.body-modal.bottom-sheet {\n  width: 100%;\n  max-width: 100%;\n  border-radius: 20px 20px 0 0;\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  right: 0;\n  margin: 0;\n}\n\n/* === Close Button === */\n.modals .body-modal button.button-close {\n  width: 40px;\n  height: 40px;\n  position: absolute;\n  top: 15px;\n  right: 15px;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  cursor: pointer;\n  z-index: 5;\n}\n.modals .body-modal button.button-close .button-inner {\n  width: 100%;\n  height: 100%;\n  border-radius: 8px;\n  \n  display: flex;\n  justify-content: center;\n  align-items: center;\n  transition: background 0.3s ease;\n}\n.modals .body-modal button.button-close .button-inner svg {\n  width: 35px;\n  height: 35px;\n  fill: #75adc2;\n  transition: fill 0.3s ease;\n}\n.modals .body-modal button.button-close:hover .button-inner {\n  background: rgba(12, 51, 81, 0.9);\n}\n.modals .body-modal button.button-close:hover .button-inner svg {\n  fill: #ffffff;\n}\n\n/* === Animations === */\n.fade-enter-active,\n.fade-leave-active {\n  transition: opacity 0.3s ease;\n}\n.fade-enter-from,\n.fade-leave-to {\n  opacity: 0;\n}\n\n/* Desktop modal animation */\n.slide-fade-enter-active,\n.slide-fade-leave-active {\n  transition: all 0.3s ease;\n}\n.slide-fade-enter-from,\n.slide-fade-leave-to {\n  transform: translateY(50px);\n  opacity: 0;\n}\n\n/* Bottom sheet animation */\n.slide-up-enter-active,\n.slide-up-leave-active {\n  transition: transform 0.3s ease, opacity 0.3s ease;\n}\n.slide-up-enter-from,\n.slide-up-leave-to {\n  transform: translateY(100%);\n  opacity: 0;\n}\n</style>\n",
		"<template>\n    <div class=\"modal-captcha\">\n        <div class=\"captcha-title\">\n            <span class=\"gradient-green\">{{ $t('modal.24') }}</span>\n        </div>\n        <div class=\"captcha-content\">\n            <HCaptcha \n                ref=\"modalCaptcha\" \n                v-bind:sitekey=\"modalCaptchaKey\" \n                @verify=\"modalOnVerify\" \n                @expired=\"modalOnExpire\"\n                @challengeExpired=\"modalOnExpire\"\n            />\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    \nimport HCaptcha from '@hcaptcha/vue3-hcaptcha'\n    export default {\n        name: 'ModalTip',\n        components: {\n            HCaptcha\n        },\n        data() {\n            return {\n                modalCaptchaKey: process.env.VUE_APP_HCAPTCHA_KEY\n            }\n        },\n        methods: {\n            ...mapActions([\n                'modalsSetShow', \n                'authSendCredentialsLogin',\n                'authSendCredentialsRegister',\n                'authSendCredentialsRequest',\n                'authSendCredentialsReset',\n                'affiliatesSendClaimCodeSocket', \n                'generalSendPromoClaimSocket', \n                'cashierSendGiftRedeemSocket', \n                'generalSendRainJoinSocket'\n            ]),\n            modalOnVerify(token, eKey) {\n                const data = { ...this.modalsData.data, captcha: token };\n\n                if(this.modalsData.typeCaptcha === 'credentialsLogin') {\n                    this.authSendCredentialsLogin(data);\n                } else if(this.modalsData.typeCaptcha === 'credentialsRegister') {\n                    this.authSendCredentialsRegister(data);\n                } else if(this.modalsData.typeCaptcha === 'credentialsRequest') {\n                    this.authSendCredentialsRequest(data);\n                } else if(this.modalsData.typeCaptcha === 'credentialsReset') {\n                    this.authSendCredentialsReset(data);\n                } else if(this.modalsData.typeCaptcha === 'affiliatesClaim') {\n                    this.affiliatesSendClaimCodeSocket(data);\n                } else if(this.modalsData.typeCaptcha === 'promoClaim') {\n                    this.generalSendPromoClaimSocket(data);\n                } else if(this.modalsData.typeCaptcha === 'giftRedeem') {\n                    this.cashierSendGiftRedeemSocket(data);\n                } else if(this.modalsData.typeCaptcha === 'rainJoin') {\n                    this.generalSendRainJoinSocket(data);\n                }\n\n                this.modalsSetShow(null);\n            },\n            modalOnExpire() {\n                this.modalsSetShow(null);\n            }\n        },\n        computed: {\n            ...mapGetters([ \n                'modalsData'\n            ])\n        },\n        mounted() {\n            this.$refs.modalCaptcha.reset();\n        }\n    }\n</script>\n\n<style scoped>\n.modal-captcha {\n    width: 773px;\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 35px 0 48px 0;\n    border-radius: 15px;\n    background: var(--background);\n}\n\n.modal-captcha .captcha-title {\n    text-align: center;\n    font-size: 32px;\n    font-weight: 900;\n}\n\n.modal-captcha .captcha-content {\n    width: 303px;\n    height: 76px;\n    margin-top: 35px;\n    border-radius: 4px;\n    background-color: #1a4f63;\n}\n\n/* Tablet */\n@media only screen and (max-width: 793px) {\n    .modal-captcha {\n        width: calc(100vw - 20px);\n        padding: 85px 20px 48px 20px;\n    }\n}\n\n/* Mobil (bottom sheet) */\n@media only screen and (max-width: 500px) {\n    .modal-captcha {\n        width: 100vw;                  /* tam genişlik */\n        max-width: 100%;\n        border-radius: 20px 20px 0 0;  /* sadece üst köşeler yuvarlak */\n        padding: 85px 15px 48px 15px;  /* kenarlarda eşit boşluk */\n    }\n}\n</style>\n\n",
