		"<template>\n    <div class=\"modal-login\">\n        <div class=\"login-sidebar\">\n            <img src=\"@/assets/img/logo_small.png\" />\n            <div class=\"sidebar-text\">\n                <span class=\"gradient-green\">{{ $t('modal.82') }}</span>\n            </div>\n            <img v-if=\"['login', 'register', 'roblox login'].includes(modalTab) === true\"  />\n        </div>\n        <div class=\"login-content\">\n            <div class=\"content-title\">\n                <span class=\"gradient-green\">{{ modalTab === 'forgot' ? 'RESET PASSWORD' : modalTab.toUpperCase() }}</span>\n            </div>\n            <div v-if=\"['login', 'register', 'roblox login', 'roblox cookie'].includes(modalTab) === true\" class=\"content-auth\">\n                <LoginRoblox v-if=\"['roblox login', 'roblox cookie'].includes(modalTab) === true\" v-bind:tab=\"modalTab\" />\n                <LoginCredentials v-else v-bind:tab=\"modalTab\" />\n\n               \n\n             \n              \n                \n            </div>\n            <LoginForgot v-else />\n        </div>\n    </div>\n</template>\n\n\n<script>\n    import { mapActions } from 'vuex';\n    import LoginCredentials from '@/components/login/LoginCredentials';\n    import LoginRoblox from '@/components/login/LoginRoblox';\n    import LoginForgot from '@/components/login/LoginForgot';\n\n    export default {\n        name: 'ModalLogin',\n        components: {\n            LoginCredentials,\n            LoginRoblox,\n            LoginForgot\n        },  \n        data() {\n            return {\n                modalTab: 'login'\n            }\n        },\n        methods: {\n            ...mapActions([\n                'modalsSetShow'\n            ]),\n            modalSetTab(tab) {\n                this.modalTab = tab;\n            },\n            modalTermsButton() {\n                this.modalsSetShow(null);\n                setTimeout(() => { this.modalsSetShow('Terms'); }, 300);\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .modal-login {\n        width: 1010px;\n        border-radius: 15px;\n        background: var(--background) ;\n    }\n\n    .modal-login .login-sidebar {\n        width: 237px;\n        height: 100%;\n        position: absolute;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        top: 0;\n        left: 0;\n        border-radius: 15px 0 0 15px;\n        background: var(--background2);\n    }\n\n    .modal-login .login-sidebar img:nth-of-type(1) {\n        width: 143px;\n        margin-top: 45px;\n    }\n\n    .modal-login .login-sidebar img:nth-of-type(2) {\n        position: absolute;\n        bottom: -45px;\n    }\n\n    .modal-login .sidebar-text {\n        width: 100%;\n        position: relative;\n        margin-top: 42px;\n        padding: 15px 30px;\n        text-align: center;\n        background: linear-gradient(255deg, rgba(0, 255, 194, 0.05) 0%, rgba(0, 170, 109, 0.05) 100%);\n    }\n\n    .modal-login .sidebar-text::before {\n        content: '';\n        width: 100%;\n        height: 1px;\n        position: absolute;\n        top: 0;\n        left: 0;\n        background: var(--button1);\n    }\n\n    .modal-login .sidebar-text::after {\n        content: '';\n        width: 100%;\n        height: 1px;\n        position: absolute;\n        bottom: 0;\n        left: 0;\n        background: var(--button1);\n    }\n\n    .modal-login .sidebar-text span {\n        font-family: 'Rubik';\n        line-height: 28px;\n        font-size: 18px;\n        font-weight: 900;\n        text-shadow: 0px 0px 50px rgba(0, 255, 194, 0.25);\n    }\n\n    .modal-login .login-content {\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 35px 110px 48px 347px;\n    }\n\n    .modal-login .content-title {\n        text-align: center;\n        font-size: 32px;\n        font-weight: 900;\n    }\n\n    .modal-login .content-auth {\n        width: 100%;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        \n    }\n\n    .modal-login .auth-seperator {\n        width: 530px;\n        position: relative;\n        margin-top: 35px;\n        text-align: center;\n        font-size: 18px;\n        font-weight: 700;\n        color: #5e768e;\n    }\n\n    .modal-login .auth-seperator:before,\n    .modal-login .auth-seperator:after {\n        content: '';\n        width: calc(50% - 110px);\n        height: 1px;\n        position: absolute;\n        top: 50%;\n        transform: translate(0, -50%);\n        background: #18486d;\n        opacity: 0.5;\n    }\n\n    .modal-login .auth-seperator:before {\n        left: 0;\n    }\n\n    .modal-login .auth-seperator:after {\n        right: 0;\n    }\n\n    .modal-login button.button-credentials,\n    .modal-login button.button-roblox {\n        width: 100%; \n        height: 54px;\n        margin-top: 35px;\n    }\n\n    .modal-login button.button-credentials .button-inner,\n    .modal-login button.button-roblox .button-inner {\n        width: 100%; \n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        font-size: 18px;\n        font-weight: 600;\n        color: #ffffff;\n        background: #1a4f63;\n        clip-path: polygon(11px 0, calc(100% - 11px) 0, 100% 25%, 100% 75%, calc(100% - 11px) 100%, 11px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-login button.button-roblox .button-inner {\n        background: #4178ca;\n    }\n\n    .modal-login button.button-roblox .button-inner svg {\n        margin-right: 14px;\n        fill: #ffffff;\n    }\n\n    @media only screen and (max-width: 1030px) {\n\n        .modal-login {\n            width: calc(100vw - 20px);\n        }\n\n    }\n\n    @media only screen and (max-width: 950px) {\n\n        .modal-login .login-sidebar {\n            display: none;\n        }\n\n        .modal-login .login-content {\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            padding: 15px 15px 48px 15px;\n        }\n\n    }\n\n    @media only screen and (max-width: 560px) {\n\n        .modal-login .auth-seperator {\n            width: 100%;\n        }\n\n    }\n\n    .modal-login .button-auth {\n    width: 100%;\n    height: 54px;\n    margin-top: 20px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    background-color: #1a4f63;\n    border-radius: 8px;\n    transition: background-color 0.3s ease;\n}\n\n.modal-login .button-auth:hover {\n    background-color: #0d3b4d;\n}\n\n.modal-login .button-auth .button-inner {\n    display: flex;\n    align-items: center;\n    font-size: 18px;\n    font-weight: 600;\n    color: #ffffff;\n}\n\n.modal-login .button-auth svg {\n    width: 24px;\n    height: 24px;\n    margin-right: 10px;\n}\n\n.modal-login .telegram-auth {\n    background-color: #0088cc;\n}\n\n.modal-login .google-auth {\n    background-color: #db4437;\n}\n\n.modal-login .yandex-auth {\n    background-color: #ffcc00;\n}\n\n</style>\n",
		"<template>\n  <div class=\"login-credentials\" :class=\"{ mobile: isMobile }\">\n    <!-- LOGIN -->\n    <div v-if=\"tab === 'login'\">\n      <!-- Kullanıcı Adı -->\n      <div class=\"credentials-element\">\n        <label class=\"element-title\">{{ $t('login.username') }}</label>\n        <div class=\"input-container\">\n          <i class=\"icon fas fa-user\"></i>\n          <input\n            v-model=\"loginUsername\"\n            type=\"text\"\n            :placeholder=\"$t('register.usernamePlaceholder')\"\n            class=\"input-field\"\n          />\n        </div>\n      </div>\n\n      <!-- Şifre -->\n      <div class=\"credentials-element\">\n        <label class=\"element-title\">{{ $t('login.password') }}</label>\n        <div class=\"input-container\">\n          <i class=\"icon fas fa-lock\"></i>\n          <input\n            v-model=\"loginPassword\"\n            type=\"password\"\n            :placeholder=\"$t('register.passwordPlaceholder')\"\n            class=\"input-field\"\n          />\n          <button @click=\"$parent.modalSetTab('forgot')\" class=\"forgot-link\">\n            {{ $t('login.forgot') }}\n          </button>\n        </div>\n      </div>\n    </div>\n\n    <!-- REGISTER -->\n    <div v-if=\"tab === 'register'\">\n      <!-- Name + Username -->\n      <div class=\"credentials-row\">\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.name') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-user\"></i>\n            <input\n              v-model=\"loginNameSurname\"\n              type=\"text\"\n              :placeholder=\"$t('register.namePlaceholder')\"\n              class=\"input-field\"\n            />\n          </div>\n        </div>\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.username') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-at\"></i>\n            <input\n              v-model=\"loginUsername\"\n              type=\"text\"\n              :placeholder=\"$t('register.usernamePlaceholder')\"\n              class=\"input-field\"\n            />\n          </div>\n        </div>\n      </div>\n\n      <!-- Phone + Email -->\n      <div class=\"credentials-row\">\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.phone') }}</label>\n          <div class=\"phone-input\">\n            <!-- Country Code -->\n          <CustomDropdown\n  v-model=\"selectedCountryCode\"\n  :options=\"countryCodes.map(c => ({\n    value: c.dial_code,\n    label: `${c.dial_code} `\n  }))\"\n/>\n\n\n            <!-- Phone Number -->\n            <input\n              v-model=\"loginPhone\"\n              type=\"tel\"\n              inputmode=\"numeric\"\n              pattern=\"[0-9]*\"\n              :placeholder=\"$t('register.phonePlaceholder')\"\n              class=\"phone-number\"\n            />\n          </div>\n        </div>\n\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.mail') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-envelope\"></i>\n            <input\n              v-model=\"loginEmail\"\n              type=\"text\"\n              :placeholder=\"$t('register.mailPlaceholder')\"\n              class=\"input-field\"\n            />\n          </div>\n        </div>\n      </div>\n\n      <!-- CPF (sadece Brezilya IP'lerinde görünür) -->\n<div v-if=\"showCPFField\" class=\"credentials-element\">\n  <label class=\"element-title\">CPF</label>\n  <div class=\"input-container\">\n    <i class=\"icon fas fa-id-card\"></i>\n    <input\n      v-model=\"loginIdNumber\"\n      type=\"text\"\n      inputmode=\"numeric\"\n      maxlength=\"11\"\n      minlength=\"11\"\n      pattern=\"[0-9]*\"\n      placeholder=\"00000000000\"\n      class=\"input-field\"\n      @input=\"onCPFInput\"\n    />\n  </div>\n  <small v-if=\"cpfError\" class=\"error-text\">{{ cpfError }}</small>\n</div>\n\n      <!-- Birthday -->\n      <div class=\"credentials-row\">\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.birthday') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-calendar\"></i>\n            <input v-model=\"loginBirthday\" type=\"date\" class=\"input-field\" />\n          </div>\n        </div>\n      </div>\n\n      <!-- Passwords -->\n      <div class=\"credentials-row\">\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.password') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-lock\"></i>\n            <input\n              v-model=\"loginPassword\"\n              type=\"password\"\n              :placeholder=\"$t('register.passwordPlaceholder')\"\n              class=\"input-field\"\n              @focus=\"showPasswordRules = true\"\n              @blur=\"hidePasswordRules\"\n            />\n          </div>\n          <ul v-if=\"showPasswordRules\" class=\"password-rules\">\n            <li :class=\"{ valid: passwordRules.minLength }\">{{ $t('passwordRules.minLength') }}</li>\n            <li :class=\"{ valid: passwordRules.uppercase }\">{{ $t('passwordRules.uppercase') }}</li>\n            <li :class=\"{ valid: passwordRules.lowercase }\">{{ $t('passwordRules.lowercase') }}</li>\n            <li :class=\"{ valid: passwordRules.number }\">{{ $t('passwordRules.number') }}</li>\n            <li :class=\"{ valid: passwordRules.special }\">{{ $t('passwordRules.special') }}</li>\n          </ul>\n        </div>\n\n        <div class=\"credentials-element\">\n          <label class=\"element-title\">{{ $t('register.passwordag') }}</label>\n          <div class=\"input-container\">\n            <i class=\"icon fas fa-lock\"></i>\n            <input\n              v-model=\"loginPasswordConfirm\"\n              type=\"password\"\n              :placeholder=\"$t('register.passwordagPlaceholder')\"\n              class=\"input-field\"\n            />\n          </div>\n        </div>\n      </div>\n\n      <!-- Currency -->\n      <div class=\"credentials-element\">\n        <label class=\"element-title\"> {{ $t('register.Currency') }}</label>\n        <div class=\"input-container\">\n          \n          <CustomDropdown\n  v-model=\"selectedCurrency\"\n  :options=\"fiatCurrencies.map(c => ({\n    value: c.code,  // 🔑 sadece code seçiliyor\n    label: c.label\n  }))\"\n/>\n        </div>\n      </div>\n      <!-- Affiliate Code -->\n<div class=\"credentials-element\">\n  <label class=\"element-title\">{{ $t('register.affiliate') }}</label>\n  <div class=\"input-container\">\n    <i class=\"icon fas fa-gift\"></i>\n    <input\n      v-model=\"loginAffiliateCode\"\n      type=\"text\"\n      :placeholder=\"$t('register.affiliatePlaceholder')\"\n      class=\"input-field\"\n    />\n  </div>\n</div>\n    </div>\n\n    \n\n    <!-- Buttons -->\n    <div class=\"credentials-buttons\">\n      <button\n        @click=\"$parent.modalSetTab(tab === 'login' ? 'register' : 'login')\"\n        class=\"toggle-btn\"\n        :class=\"{ active: tab === 'register' }\"\n      >\n        {{ tab === 'login' ? $t('buttons.register') : $t('buttons.login') }}\n      </button>\n      <button\n        @click=\"loginActionButton\"\n        class=\"action-btn\"\n        :disabled=\"authSendLoginLoading === true\"\n      >\n        <span v-if=\"authSendLoginLoading\" class=\"btn-loading\">\n          <i class=\"fas fa-spinner fa-spin\"></i>\n        </span>\n        <span v-else>{{ $t(`buttons.${tab}`) }}</span>\n      </button>\n    </div>\n\n<!-- Google ile giriş -->\n<div id=\"googleBtn\" style=\"margin-top: 10px; display: none;\"></div>\n\n\n\n    <!-- Terms -->\n    <div v-if=\"tab === 'register'\" class=\"terms\">\n      {{ $t('register.credent') }}\n      <button @click=\"loginTermsButton()\" class=\"terms-link\">\n        {{ $t('register.terms') }}\n      </button>.\n    </div>\n  </div>\n</template>\n\n<script>\nimport { mapGetters, mapActions } from \"vuex\";\nimport countryCodes from \"@/assets/data/countryCodes.json\";\nimport CustomDropdown from \"@/components/CustomDropdown.vue\";\nimport axios from \"axios\";\n\nexport default {\n  name: \"LoginCredentials\",\n  components: { CustomDropdown },\n  props: [\"tab\"],\n  data() {\n    return {\n      isMobile: window.innerWidth <= 768,\n      loginMethod: \"username\",\n      loginUsername: null,\n      loginEmail: null,\n      loginPhone: null,\n      loginNameSurname: null,\n      loginBirthday: null,\n      loginIdNumber: null,\n      showCPFField: false,\n      cpfError: null,\n      loginPassword: null,\n      loginPasswordConfirm: null,\n      selectedCountryCode: \"+1\",\n      selectedCurrency: \"USD\",\n      showPasswordRules: false,\n      loginAffiliateCode: null,\n      countryCodes,\n      fiatCurrencies: [\n        { code: \"USD\", label: \"USD - US Dollar\" },\n        { code: \"GBP\", label: \"GBP - British Pound\" },\n        { code: \"CAD\", label: \"CAD - Canadian Dollar\" },\n        { code: \"AUD\", label: \"AUD - Australian Dollar\" },\n        { code: \"EUR\", label: \"EUR - Euro\" },\n        { code: \"TRY\", label: \"TRY - Turkish Lira\" },\n        { code: \"BRL\", label: \"BRL - Brazilian Real\" },\n        { code: \"MXN\", label: \"MXN - Mexican Peso\" },\n        { code: \"INR\", label: \"INR - Indian Rupee\" },\n        { code: \"JPY\", label: \"JPY - Japanese Yen\" },\n        { code: \"KRW\", label: \"KRW - South Korean Won\" },\n        { code: \"PHP\", label: \"PHP - Philippine Peso\" },\n        { code: \"ZAR\", label: \"ZAR - South African Rand\" },\n        { code: \"RUB\", label: \"RUB - Russian Ruble\" },\n        { code: \"SEK\", label: \"SEK - Swedish Krona\" },\n        { code: \"NOK\", label: \"NOK - Norwegian Krone\" },\n        { code: \"DKK\", label: \"DKK - Danish Krone\" },\n        { code: \"SGD\", label: \"SGD - Singapore Dollar\" },\n        { code: \"MYR\", label: \"MYR - Malaysian Ringgit\" },\n        { code: \"THB\", label: \"THB - Thai Baht\" },\n        { code: \"VND\", label: \"VND - Vietnamese Dong\" },\n        { code: \"ARS\", label: \"ARS - Argentine Peso\" },\n        { code: \"COP\", label: \"COP - Colombian Peso\" },\n        { code: \"CLP\", label: \"CLP - Chilean Peso\" },\n        { code: \"CNY\", label: \"CNY - Chinese Yuan\" }\n      ]\n    };\n  },\n  mounted() {\n    this.detectCountryData();\n\n      // ✅ URL'den affiliate code yakala\n  const urlParams = new URLSearchParams(window.location.search);\n  const affiliate = urlParams.get(\"a\");\n  if (affiliate) {\n    this.loginAffiliateCode = affiliate;\n  }\n\n    // ✅ Backend’den clientId çek (gerekirse ayarlardan)\n    fetch(\"/settings\")\n      .then(res => res.json())\n      .then(data => {\n        if (data.googleClientId) {\n          google.accounts.id.initialize({\n            client_id: data.googleClientId,\n            callback: this.handleGoogleResponse\n          });\n\n          google.accounts.id.renderButton(\n            document.getElementById(\"googleBtn\"),\n            { theme: \"outline\", size: \"large\" }\n          );\n        }\n      });\n  },\n  methods: {\n    ...mapActions([\n      \"modalsSetShow\",\n      \"modalsSetData\",\n      \"notificationShow\",\n      \"authSendCredentialsLogin\",\n      \"authSendCredentialsRegister\"\n    ]),\n\n     onCPFInput() {\n    // Yalnızca rakamları kabul et\n    this.loginIdNumber = this.loginIdNumber.replace(/\\D/g, \"\");\n    if (this.loginIdNumber.length > 11) {\n      this.loginIdNumber = this.loginIdNumber.slice(0, 11);\n    }\n\n    // Hata mesajı kontrolü\n    if (this.loginIdNumber && this.loginIdNumber.length !== 11) {\n      this.cpfError = \"CPF numarası 11 haneli olmalıdır\";\n    } else {\n      this.cpfError = null;\n    }\n  },\n\nasync handleGoogleResponse(response) {\n  console.log(\"Google Response:\", response);\n\n  try {\n    const idToken = response.credential;\n    console.log(\"ID Token:\", idToken);\n\n    const res = await axios.post(\"/auth/social/google\", {\n      token: idToken\n    });\n\n    if (res.data.extraInfoRequired) {\n      this.modalsSetData({\n        type: \"socialComplete\",\n        data: { userId: res.data.userId }\n      });\n      this.modalsSetShow(\"SocialComplete\");\n    } else {\n      // ✅ store mantığıyla aynı\n      localStorage.setItem(\"token\", res.data.token);\n      axios.defaults.headers.common[\"x-auth-token\"] = res.data.token;\n\n      this.$store.commit(\"auth_set_token\", res.data.token);\n      this.$store.commit(\"auth_set_user\", res.data.user);\n\n      this.$store.dispatch(\"socketConnectGeneral\");\n      this.$store.dispatch(\"socketConnectCashier\");\n\n      if (res.data.user.rank === \"admin\" || res.data.user.rank === \"mod\") {\n        this.$store.dispatch(\"socketConnectAdmin\");\n      }\n\n      this.notificationShow({ type: \"success\", message: \"Giriş başarılı\" });\n      this.$store.dispatch(\"modalsSetShow\", null);\n    }\n  } catch (err) {\n    console.error(\"Google login error:\", err);\n    this.notificationShow({\n      type: \"error\",\n      message: \"Google ile giriş başarısız\"\n    });\n  }\n}\n\n,\n\n\n    loginActionButton() {\n      let loginData = {};\n\n      if (this.tab === \"login\") {\n        loginData = { username: this.loginUsername, password: this.loginPassword };\n        this.modalsSetData({ typeCaptcha: \"credentialsLogin\", data: loginData });\n      } else {\n        if (this.loginPassword !== this.loginPasswordConfirm) {\n          this.notificationShow({ type: \"error\", message: this.$t(\"errors.passwordMismatch\") });\n          return;\n        }\n\n        // Telefon numarasını +90 yerine 90 şeklinde gönder\nconst fullPhoneNumber = `${this.selectedCountryCode.replace(\"+\", \"\")}${this.loginPhone}`;\n\n\n        this.modalsSetData({\n          typeCaptcha: \"credentialsRegister\",\n          data: {\n            name: this.loginNameSurname,\n            username: this.loginUsername,\n            email: this.loginEmail,\n            phone: fullPhoneNumber,\n            birthday: this.loginBirthday,\n            idNumber: this.loginIdNumber,\n            password: this.loginPassword,\n            fiatCurrency: this.selectedCurrency,\n             affiliate: this.loginAffiliateCode\n          }\n        });\n      }\n\n      setTimeout(() => {\n        this.modalsSetShow(\"Captcha\");\n      }, 200);\n    },\n\n    loginTermsButton() {\n      this.modalsSetShow(null);\n      setTimeout(() => {\n        this.modalsSetShow(\"Terms\");\n      }, 300);\n    },\n\n    hidePasswordRules() {\n      setTimeout(() => (this.showPasswordRules = false), 200);\n    },\n\nasync detectCountryData() {\n  try {\n    const res = await fetch(\"https://ipapi.co/json/\");\n    if (res.ok) {\n      const data = await res.json();\n\n      // 🌍 Brezilya kontrolü\n      if (data.country_code === \"BR\") {\n        this.showCPFField = true;\n      } else {\n        this.showCPFField = false;\n      }\n\n     if (data.country_calling_code) {\n        this.selectedCountryCode = data.country_calling_code; // UI'da +90 olarak görünecek\n      }\n      \n      // 🌍 Para birimi\n      const countryToCurrency = {\n        US: \"USD\",\n        GB: \"GBP\",\n        CA: \"CAD\",\n        AU: \"AUD\",\n        EU: \"EUR\",\n        TR: \"TRY\",\n        BR: \"BRL\",\n        MX: \"MXN\",\n        IN: \"INR\",\n        JP: \"JPY\",\n        KR: \"KRW\",\n        PH: \"PHP\",\n        ZA: \"ZAR\",\n        RU: \"RUB\",\n        SE: \"SEK\",\n        NO: \"NOK\",\n        DK: \"DKK\",\n        SG: \"SGD\",\n        MY: \"MYR\",\n        TH: \"THB\",\n        VN: \"VND\",\n        AR: \"ARS\",\n        CO: \"COP\",\n        CL: \"CLP\",\n        CN: \"CNY\",\n        HK: \"CNY\",\n        TW: \"CNY\",\n        MO: \"CNY\"\n      };\n\n      let detectedCurrency = data.currency || null;\n      if (!detectedCurrency || !this.fiatCurrencies.find(c => c.code === detectedCurrency)) {\n        detectedCurrency = countryToCurrency[data.country_code] || \"USD\";\n      }\n\n      const match = this.fiatCurrencies.find(c => c.code === detectedCurrency);\n      this.selectedCurrency = match ? match.code : \"USD\";\n    }\n  } catch (e) {\n    this.selectedCountryCode = \"1\";\n    this.selectedCurrency = \"USD\";\n  }\n},\n\n\n  },\n  computed: {\n    passwordRules() {\n      const pass = this.loginPassword || \"\";\n      return {\n        minLength: pass.length >= 8,\n        uppercase: /[A-Z]/.test(pass),\n        lowercase: /[a-z]/.test(pass),\n        number: /[0-9]/.test(pass),\n        special: /[!@#$%^&*(),.?\":{}|<>]/.test(pass)\n      };\n    },\n    ...mapGetters([\"authSendLoginLoading\"])\n  }\n};\n</script>\n\n\n\n\n\n\n\n<style scoped>\n/* Genel */\n.login-credentials {\n  width: 100%;\n  max-width: 520px;\n  margin: 0 auto;\n      font-family: \"Rubik\", sans-serif;\n    font-size: 14px;\n    font-variant-numeric: lining-nums tabular-nums;\n    font-weight: 600;\n  padding-bottom: 50px;\n}\n\n.login-credentials.mobile {\n  position: fixed;\n  bottom: 0;\n  left: 0;\n  width: 100%;\n  background: var(--background);\n  border-radius: 20px 20px 0 0;\n  padding: 25px 20px;\n  z-index: 9999;\n  max-height: 90%;\n  overflow-y: auto;\n  animation: slideUp 0.3s ease;\n  box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.5);\n}\n\n@keyframes slideUp {\n  from { transform: translateY(100%); }\n  to { transform: translateY(0); }\n}\n\n/* Input Container */\n.input-container {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n\n.icon {\n  position: absolute;\n  left: 15px;\n  color: #7b6cb9;\n  z-index: 2;\n  font-size: 14px;\n  transition: color 0.2s ease;\n}\n\n.input-container:focus-within .icon {\n  color: var(--background4);\n}\n\n/* Elemanlar */\n.credentials-element {\n  \n  width: 100%;\n}\n\n.credentials-row {\n  display: flex;\n  gap: 15px;\n  margin-bottom: 15px;\n}\n\n.element-title {\n  font-size: 13px;\n  font-weight: 600;\n  color: #94a3b8;\n  margin-bottom: 8px;\n  display: block;\n}\n\n/* Standart input */\n.input-field {\n  width: 100%;\n  height: 50px;\n  padding: 0 14px 0 40px;\n  font-size: 14px;\n  color: #f1f5f9;\n      background: var(--background2);\n    border: 2px solid var(--bar-outer);\n  border-radius: 12px;\n  outline: none;\n  transition: all 0.3s ease;\n  font-weight: 500;\n}\n\n.input-field:focus {\n  border-color: var(--background4);\n  box-shadow: 0 0 0 3px rgba(142, 1, 224, 0.1);\n}\n\n.input-field::placeholder {\n  color: #7b6cb9;\n}\n\n/* === PHONE INPUT === */\n.phone-input {\n  display: flex;\n  align-items: center;\n  width: 100%;\n  height: 50px;\n  background: var(--background2);\n  border: 2px solid var(--bar-outer);\n  border-radius: 12px;\n  overflow: hidden;\n}\n\n.phone-input:focus {\n\n   border-color: var(--background4);\n  box-shadow: 0 0 0 3px rgba(142, 1, 224, 0.1);\n}\n\n/* Country Select */\n.country-select {\n  flex: 0 0 50px;   /* sabit genişlik */\n  min-width: 0;     /* default min-width devre dışı */\n  box-sizing: border-box;\n  height: 100%;\n  border: none;\n  outline: none;\n  background: transparent;\n  color: #f1f5f9;\n  font-size: 14px;\n  font-weight: 500;\n  text-align: center;\n  cursor: pointer;\n  appearance: none;\n  border-right: 2px solid #191939;\n  \n}\n\n.country-select option {\n  background: #0f172a;  /* dark background */\n  color: #f1f5f9;       /* light text */\n  padding: 8px 12px;\n}\n\n\n/* Phone Number */\n.phone-number {\n  flex: 1;\n  height: 100%;\n  border: none;\n  outline: none;\n  background: transparent;\n  color: #f1f5f9;\n  padding: 0 14px;\n  font-size: 14px;\n  font-weight: 500;\n}\n\n.phone-number::placeholder {\n  color: #7b6cb9;\n}\n\n/* Mobil */\n@media (max-width: 480px) {\n  .credentials-row {\n    flex-direction: column;\n    gap: 15px;\n  }\n    \n}\n\n/* Şifre alanı */\n.forgot-link {\n  position: absolute;\n  right: 15px;\n  top: 50%;\n  transform: translateY(-50%);\n  font-size: 12px;\n  color: #000;\n  border: none;\n  background: none;\n  cursor: pointer;\n  font-weight: 600;\n  transition: color 0.2s ease;\n  z-index: 2;\n}\n \n/* Butonlar */\n.credentials-buttons {\n  display: flex;\n  justify-content: space-between;\n  margin-top: 25px;\n  gap: 12px;\n}\n\n.toggle-btn,\n.action-btn {\n  flex: 1;\n  height: 50px;\n  border-radius: 12px;\n  font-weight: 700;\n  cursor: pointer;\n  border: none;\n  font-size: 14px;\n  transition: all 0.3s ease;\n}\n\n.toggle-btn {\n  background: var(--background2);\n  color: #fff;\n  \n}\n\n \n \n\n.action-btn {\n      background: var(--buttonyellow);\n    box-shadow: rgb(197, 106, 24) 0px -3px 0px 0px inset, rgb(255, 234, 47) 0px 2px 0px 0px inset;\n    color: #fff;\n    text-shadow: -1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px -1px 0 var(--roo-btn-text-stroke-color, #C56A18), -1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18), 1px 1px 0 var(--roo-btn-text-stroke-color, #C56A18);\n    border-radius: 12px;\n  font-weight: 700;\n}\n\n \n.action-btn:disabled {\n  opacity: 0.6;\n  cursor: not-allowed;\n  transform: none;\n}\n\n.btn-loading {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n/* Terms */\n.terms {\n  margin-top: 20px;\n  font-size: 12px;\n  color: #7b6cb9;\n  text-align: center;\n  line-height: 1.5;\n}\n\n.terms-link {\n  color: #01e0a3;\n  background: none;\n  border: none;\n  font-weight: 600;\n  cursor: pointer;\n  transition: color 0.2s ease;\n}\n\n.terms-link:hover {\n  color: #00c891;\n  text-decoration: underline;\n}\n\n.password-rules {\n  margin-top: 8px;\n  font-size: 12px;\n  list-style: none;\n  padding: 0;\n  color: #7b6cb9; /* default gri */\n}\n\n.password-rules li {\n  margin-bottom: 4px;\n  transition: color 0.3s ease;\n}\n\n.password-rules li.valid {\n  color: green; /* mor */\n  font-weight: 600;\n}\n\n.styled-select {\n  width: 100%;\n  height: 50px;\n  padding: 0 14px;\n  font-size: 14px;\n  font-weight: 500;\n  color: #f1f5f9;\n  background: var(--background1);\n  border: 2px solid var(--bar-outer);\n  border-radius: 10px;\n  outline: none;\n  cursor: pointer;\n  appearance: none;\n}\n\n.styled-select:focus {\n  border-color: var(--background4);\n  box-shadow: 0 0 0 3px rgba(142, 1, 224, 0.1);\n}\n\n.styled-select option {\n  background: #0f172a;\n  color: #f1f5f9;\n  padding: 10px;\n}\n\n.input-container .custom-dropdown {\n  flex: 1;\n  \n}\n\n.google-btn {\n  background: #fff;\n  border: 1px solid #ddd;\n  color: #444;\n  padding: 10px 20px;\n  border-radius: 5px;\n  font-weight: 500;\n  cursor: pointer;\n  width: 100%;\n  margin-top: 10px;\n}\n.google-btn i {\n  margin-right: 8px;\n  color: #DB4437;\n}\n\n\n.error-text {\n  color: #e74c3c;\n  font-size: 12px;\n  margin-top: 4px;\n}\n\n.input-field:invalid {\n  border-color: #e74c3c;\n}\n\n</style>\n",
		"<template>\r\n  <div class=\"custom-dropdown\" @click=\"toggleDropdown\" ref=\"dropdown\">\r\n    <!-- Seçilen değer -->\r\n    <div class=\"dropdown-selected\">\r\n      {{ selectedLabel }}\r\n       \r\n    </div>\r\n\r\n    <!-- Menü -->\r\n    <ul v-if=\"isOpen\" class=\"dropdown-menu\">\r\n      <li\r\n        v-for=\"option in options\"\r\n        :key=\"option.value\"\r\n        @click.stop=\"selectOption(option)\"\r\n        class=\"dropdown-item\"\r\n      >\r\n        {{ option.label }}\r\n      </li>\r\n    </ul>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nexport default {\r\n  name: \"CustomDropdown\",\r\n  props: {\r\n    modelValue: { type: String, default: \"\" },\r\n    options: { type: Array, required: true } // [{ value: \"USD\", label: \"USD - US Dollar\" }]\r\n  },\r\n  data() {\r\n    return { isOpen: false };\r\n  },\r\n  computed: {\r\n    selectedLabel() {\r\n      const found = this.options.find(o => o.value === this.modelValue);\r\n      return found ? found.label : this.options[0]?.label || \"\";\r\n    }\r\n  },\r\n  methods: {\r\n    toggleDropdown() {\r\n      this.isOpen = !this.isOpen;\r\n    },\r\n    selectOption(option) {\r\n      this.$emit(\"update:modelValue\", option.value);\r\n      this.isOpen = false;\r\n    },\r\n    handleClickOutside(e) {\r\n      if (!this.$refs.dropdown.contains(e.target)) {\r\n        this.isOpen = false;\r\n      }\r\n    }\r\n  },\r\n  mounted() {\r\n    document.addEventListener(\"click\", this.handleClickOutside);\r\n  },\r\n  beforeUnmount() {\r\n    document.removeEventListener(\"click\", this.handleClickOutside);\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.custom-dropdown {\r\n  position: relative;\r\n  width: 100%;\r\n  cursor: pointer;\r\n  user-select: none;\r\n      font-family: \"Rubik\", sans-serif;\r\n    font-size: 14px;\r\n    font-variant-numeric: lining-nums tabular-nums;\r\n    font-weight: 600;\r\n}\r\n\r\n.dropdown-selected {\r\n  height: 50px;\r\n  display: flex;\r\n 