		"<template>\n    <div class=\"modal-credit\">\n        <button v-on:click=\"modalBackButton()\" class=\"button-back\">\n            <div class=\"button-inner\">{{ $t('modal.60') }}</div>\n        </button>\n        <div class=\"credit-title\">\n            <span class=\"gradient-green\">{{ $t('modal.61') }}</span>\n        </div>\n\n        <div class=\"credit-button\">\n    <button v-on:click=\"modalDepositNowButton\" class=\"button-deposit\">\n        <div class=\"button-inner\">{{ $t('modal.62') }}</div>\n    </button>\n</div>\n\n        \n        <div class=\"credit-info\">\n            {{ $t('modal.63') }}\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import ButtonLoading from '@/components/ButtonLoading';\n\n    export default {\n        name: 'ModalCredit',\n        components: {\n            ButtonLoading\n        },\n        data() {\n            return {\n                modalAmount: 0\n            }\n        },\n        methods: {\n            async modalDepositNowButton() {\n            try {\n                // Kullanıcı ID'sini alın (Örnek olarak `modalsData` kullanılıyor)\n                const userId = this.authUser?.user?._id;\n\n                // Bank Transfer API'sine istek gönder\n                const response = await fetch(`https://api.guotai9189.com/deposit/banktransfer?userId=${userId}`);\n                const result = await response.json();\n\n                if (response.status === 200 && result.redirectUrl) {\n                    // Yeni sekmede URL'yi aç\n                    window.open(result.redirectUrl, '_blank');\n                } else {\n                    // Hata mesajını göster\n                    this.notificationShow({\n                        type: 'error',\n                        message: result.error || 'An error occurred while processing your request.',\n                    });\n                }\n            } catch (error) {\n                console.error(error);\n                this.notificationShow({\n                    type: 'error',\n                    message: 'An error occurred. Please try again later.',\n                });\n            }\n        },\n            ...mapActions([\n                'notificationShow', \n                'modalsSetShow',\n                'cashierSendCreditDepositSocket'\n            ]),\n            modalValidateInput() {\n                this.modalAmount = Number(this.modalAmount.replace(',', '').replace('.', '').replace(/[^\\d.]/g, ''));\n            },\n            modalBackButton() {\n                this.modalsSetShow(null);\n                setTimeout(() => { this.modalsSetShow('Cashier'); }, 200);\n            },\n            modalAmountButton(amount) {\n                this.modalAmount = amount;\n            },\n            modalDepositButton() {\n            // Girilen miktarı gönderiyoruz\n            const data = { amount: this.modalAmount }; // Doğrudan modalAmount'u gönder\n            this.cashierSendCreditDepositSocket(data);\n        }\n        },\n        computed: {\n            ...mapGetters([\n                'socketSendLoading', \n                'modalsData',\n                'authUser'\n            ]),\n            modalGetAmountFiat() {\n            // Matematik işlemleri kaldırıldı. Direkt girilen miktar gösterilir.\n            if (this.modalAmount === null || isNaN(this.modalAmount) || this.modalAmount <= 0) {\n                return 0;\n            }\n            return this.modalAmount;\n        }\n        }\n    }\n</script>\n\n<style scoped>\n    .modal-credit {\n        width: 900px;\n        position: relative;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 35px 30px 50px 30px;\n        border-radius: 15px;\n        background: var(--background) \n    }\n\n    .modal-credit button.button-back {\n        height: 33px;\n        position: absolute;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        top: 15px;\n        left: 20px;\n        filter: drop-shadow(0px 4px 10px rgba(0, 0, 0, 0.1));\n        z-index: 1;\n    }\n\n    .modal-credit button.button-back .button-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        padding: 0 12px;\n        font-size: 14px;\n        font-weight: 800;\n        color: #75adc2;\n        background-color: #1a4f63;\n        clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 25%, 100% 75%, calc(100% - 6px) 100%, 6px 100%, 0 75%, 0 25%);\n        transition: color 0.3s ease;\n    }\n\n    .modal-credit button.button-back:hover .button-inner {\n        color: #ffffff;\n    }\n\n    .modal-credit .credit-title {\n        text-align: center;\n        text-transform: uppercase;\n        font-size: 32px;\n        font-weight: 900;\n    }\n\n    .modal-credit .credit-amount {\n        width: 100%;\n        margin-top: 35px;\n        padding-top: 25px;\n        border-top: 1px dashed #335361;\n    }\n\n    .modal-credit .amount-buttons {\n        width: 100%;\n        display: flex;\n        flex-wrap: wrap;\n    }\n\n    .modal-credit .amount-buttons button {\n        width: calc(14.2% - 13.71px);\n        height: 44px;\n        position: relative;\n        margin-right: 16px;\n        padding: 1px;\n        z-index: 1;\n    }\n\n    .modal-credit .amount-buttons button:last-child {\n        margin-right: 0;\n    }\n\n    .modal-credit .amount-buttons button:before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        border-radius: 5px;\n        background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, #174e64 100%);\n        z-index: -1;\n    }\n\n    .modal-credit .amount-buttons button.button-active:before {\n        background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, #01e0a3 100%);\n    }\n\n    .modal-credit .amount-buttons button .button-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        border-radius: 5px;\n        font-size: 16px;\n        font-weight: 800;\n        color: #ffffff;\n        background: linear-gradient(225deg, rgba(0, 255, 194, 0.01) 0%, rgba(0, 170, 109, 0.01) 100%), #10253c;\n        box-shadow: 0px 5px 50px 0px rgba(0, 0, 0, 0.25) inset;\n    }\n\n    .modal-credit .amount-buttons button.button-active .button-inner {\n        background: linear-gradient(225deg, rgba(0, 255, 194, 0.01) 0%, rgba(0, 170, 109, 0.01) 100%), \n                    radial-gradient(80% 80% at 50% 50%, rgba(0, 255, 194, 0.35) 0%, rgba(0, 0, 0, 0) 100%), #10253c;\n    } \n\n    .modal-credit .amount-buttons button .button-inner img {\n        width: 21px;\n        height: 21px;\n        margin-right: 8px;\n    }\n\n    .modal-credit .amount-input {\n        width: 100%;\n        height: 65px;\n        position: relative;\n        margin-top: 25px;\n        padding: 1px;\n        z-index: 1;\n    }\n\n    .modal-credit .amount-input:before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        background: linear-gradient(180deg, #04131f 0%, #223a4e 100%);\n        clip-path: polygon(13px 0, calc(100% - 13px) 0, 100% 25%, 100% 75%, calc(100% - 13px) 100%, 13px 100%, 0 75%, 0 25%);\n        z-index: -1;\n    }\n\n    .modal-credit .amount-input input {\n        width: 100%;\n        height: 100%;\n        padding: 0 15px 0 216px;\n        font-size: 18px;\n        font-weight: 700;\n        color: #49687d;\n        background: #072435;\n        clip-path: polygon(13px 0, calc(100% - 13px) 0, 100% 25%, 100% 75%, calc(100% - 13px) 100%, 13px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-credit .input-info {\n        width: 180px;\n        height: 37px;\n        position: absolute;\n        top: 50%;\n        left: 15px;\n        padding: 1px;\n        transform: translate(0, -50%);\n        z-index: 1;\n    }\n\n    .modal-credit .input-info:before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        background: #10374e;\n        z-index: -1;\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-credit .input-info:after {\n        content: '';\n        width: calc(100% - 2px);\n        height: calc(100% - 2px);\n        position: absolute;\n        top: 1px;\n        left: 1px;\n        background: #072435;\n        z-index: -1;\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-credit .info-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        font-size: 14px;\n        font-weight: 700;\n        color: #49687d;\n        background: rgba(12, 49, 71, 0.4);\n        clip-path: polygon(8px 0, calc(100% - 8px) 0, 100% 25%, 100% 75%, calc(100% - 8px) 100%, 8px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-credit .info-inner img {\n        width: 15px;\n        height: 15px;\n        margin-right: 8px;\n    }\n\n    .modal-credit .credit-button {\n        width: 100%;\n        display: flex;\n        justify-content: center;\n        margin-top: 35px;\n        padding-top: 35px;\n        border-top: 1px dashed #335361;\n    }\n\n    .modal-credit .credit-button button.button-deposit {\n        min-width: 165px;\n        height: 48px;\n    }\n\n    .modal-credit .credit-button button.button-deposit .button-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        background: var(--button1);\n        clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 25%, 100% 75%, calc(100% - 6px) 100%, 6px 100%, 0 75%, 0 25%);\n    }\n\n    .modal-credit .credit-button button.button-deposit .button-loading.fade-leave-active {\n        transition: opacity 0.5s;\n    }\n\n    .modal-credit .credit-button button.button-deposit .button-loading.fade-leave-to {\n        opacity: 0;\n    }\n\n    .modal-credit .credit-button button.button-deposit .inner-content {\n        padding: 0 24px;\n        font-size: 16px;\n        font-weight: 800;\n        color: #ffffff;\n    }\n\n    .modal-credit .credit-button button.button-deposit .inner-content.fade-enter-active {\n        transition: opacity 0.5s;\n    }\n\n    .modal-credit .credit-button button.button-deposit .inner-content.fade-enter-from {\n        opacity: 0;\n    }\n\n    .modal-credit .credit-info {\n        width: 100%;\n        margin-top: 35px;\n        text-align: center;\n        font-size: 14px;\n        font-weight: 600;\n        color: #db7d48;\n    }\n\n    @media only screen and (max-width: 920px) {\n\n        .modal-credit {\n            width: calc(100vw - 20px);\n            padding: 65px 10px 50px 10px;\n        }\n\n    }\n\n    @media only screen and (max-width: 775px) {\n\n        .modal-credit .credit-amount {\n            padding-top: 19px;\n        }\n\n        .modal-credit .amount-buttons button {\n            width: calc(33.33% - 8px);\n            margin-top: 6px;\n            margin-right: 12px;\n        }\n\n        .modal-credit .amount-buttons button:first-child {\n            display: none;\n        }\n\n        .modal-credit .amount-buttons button:nth-child(4),\n        .modal-credit .amount-buttons button:last-child {\n            margin-right: 0;\n        }\n\n    }\n</style>",
		"import { render } from \"./ModalCredit.vue?vue&type=template&id=4acec4fe&scoped=true\"\nimport script from \"./ModalCredit.vue?vue&type=script&lang=js\"\nexport * from \"./ModalCredit.vue?vue&type=script&lang=js\"\n\nimport \"./ModalCredit.vue?vue&type=style&index=0&id=4acec4fe&scoped=true&lang=css\"\n\nimport exportComponent from \"../../../node_modules/vue-loader/dist/exportHelper.js\"\nconst __exports__ = /*#__PURE__*/exportComponent(script, [['render',render],['__scopeId',\"data-v-4acec4fe\"]])\n\nexport default __exports__",
		"<template>\r\n  <div class=\"modal-credit\">\r\n    <button @click=\"modalBackButton\" class=\"button-back\">\r\n      <div class=\"button-inner\">{{ $t('modal.90') }}</div>\r\n    </button>\r\n\r\n    <div class=\"credit-title\">\r\n      <span class=\"gradient-green\">PAGAMENTO PIX</span>\r\n    </div>\r\n\r\n    <!-- 1️⃣ Miktar Girişi -->\r\n    <div v-if=\"!pixData\" class=\"credit-step\">\r\n      <div class=\"credit-amount-input\">\r\n        <label>quantia</label>\r\n        <input\r\n          v-model=\"modalAmount\"\r\n          type=\"number\"\r\n          min=\"1\"\r\n          placeholder=\"10-9999\"\r\n          class=\"input-field\"\r\n        />\r\n      </div>\r\n\r\n      <div class=\"credit-button\">\r\n        <button\r\n          @click=\"createPixPayment\"\r\n          class=\"button-deposit\"\r\n          :disabled=\"loading || !modalAmount\"\r\n        >\r\n          <div class=\"button-inner\">\r\n            <span v-if=\"loading\"><i class=\"fas fa-spinner fa-spin\"></i></span>\r\n            <span v-else>pagar</span>\r\n          </div>\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 2️⃣ QR Görüntüleme -->\r\n    <div v-else class=\"credit-step qr-section\">\r\n      \r\n\r\n      <!-- QR base64 -->\r\n      <div class=\"qr-image\" v-if=\"pixData.pixQR\">\r\n        <img :src=\"pixData.pixQR\" alt=\"Pix QR Code\" />\r\n\r\n      </div>\r\n\r\n      <!-- Kod alanı -->\r\n      <div class=\"pix-code-container\">\r\n        <label>Cópia</label>\r\n        <div class=\"pix-code-box\">\r\n          <input type=\"text\" readonly :value=\"pixData.pixCode\" ref=\"pixInput\" />\r\n          <button @click=\"copyPixCode\" class=\"copy-btn\">\r\n            <i class=\"fas fa-copy\"></i>\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"credit-button\">\r\n        <button @click=\"resetPix\" class=\"button-deposit\">\r\n          <div class=\"button-inner\">Nova Transação</div>\r\n\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"credit-info\" v-if=\"!pixData\">\r\n      {{ $t('modal.93') || 'Assim que o pagamento for concluído, seu saldo será adicionado automaticamente.' }}\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters, mapActions } from 'vuex'\r\nimport axios from 'axios'\r\n\r\nexport default {\r\n  name: 'ModalCredit',\r\n  data() {\r\n    return {\r\n      modalAmount: null,\r\n      loading: false,\r\n      pixData: null // { pixCode, pixQR, providerId }\r\n    }\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser'])\r\n  },\r\n  methods: {\r\n    ...mapActions(['notificationShow', 'modalsSetShow']),\r\n\r\n    async createPixPayment() {\r\n      if (!this.modalAmount || this.modalAmount <= 0) {\r\n        this.notificationShow({ type: 'error', message: 'Lütfen geçerli bir miktar giriniz.' })\r\n        return\r\n      }\r\n\r\n      this.loading = true\r\n\r\n      try {\r\n        const res = await axios.post('/payment/pix/create', {\r\n          userId: this.authUser.user._id,\r\n          amount: parseFloat(this.modalAmount)\r\n        })\r\n\r\n        if (res.data.success) {\r\n          this.pixData = {\r\n            pixCode: res.data.pixCode,\r\n            pixQR: res.data.pixQR,\r\n            providerId: res.data.providerId\r\n          }\r\n\r\n          this.notificationShow({ type: 'success', message: 'Pix kodu başarıyla oluşturuldu.' })\r\n        } else {\r\n          this.notificationShow({ type: 'error', message: res.data.error || 'Pix oluşturma başarısız.' })\r\n        }\r\n      } catch (err) {\r\n        console.error(err)\r\n        this.notificationShow({\r\n          type: 'error',\r\n          message: err.response?.data?.error || 'Pix oluşturma hatası.'\r\n        })\r\n      } finally {\r\n        this.loading = false\r\n      }\r\n    },\r\n\r\n    copyPixCode() {\r\n      const input = this.$refs.pixInput\r\n      input.select()\r\n      document.execCommand('copy')\r\n      this.notificationShow({ type: 'success', message: 'PIX kodu kopyalandı!' })\r\n    },\r\n\r\n    resetPix() {\r\n      this.pixData = null\r\n      this.modalAmount = null\r\n    },\r\n\r\n    modalBackButton() {\r\n      this.modalsSetShow(null)\r\n      setTimeout(() => {\r\n        this.modalsSetShow('Cashier')\r\n      }, 200)\r\n    }\r\n  }\r\n}\r\n</script>\r\n\r\n<style scoped>\r\n.modal-credit {\r\n  width: 900px;\r\n  position: relative;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  padding: 35px 30px 50px 30px;\r\n  border-radius: 15px;\r\n  background: var(--background)\r\n    linear-gradient(255deg, #07263d 0%, #07243a 100%);\r\n}\r\n\r\n.button-back {\r\n  height: 33px;\r\n  position: absolute;\r\n  top: 15px;\r\n  left: 20px;\r\n  z-index: 1;\r\n}\r\n\r\n.button-back .button-inner {\r\n  padding: 0 12px;\r\n  font-size: 14px;\r\n  font-weight: 800;\r\n  color: #75adc2;\r\n  background-color: #1a4f63;\r\n  clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 25%, 100% 75%, calc(100% - 6px) 100%, 6px 100%, 0 75%, 0 25%);\r\n  transition: color 0.3s ease;\r\n}\r\n.button-back:hover .button-inner {\r\n  color: #fff;\r\n}\r\n\r\n.credit-title {\r\n  text-align: center;\r\n  text-transform: uppercase;\r\n  font-size: 32px;\r\n  font-weight: 900;\r\n  margin-bottom: 30px;\r\n}\r\n\r\n.credit-step {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.credit-amount-input {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.credit-amount-input label {\r\n  color: #9bc7d4;\r\n  font-weight: 700;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.credit-amount-input input {\r\n  width: 60%;\r\n  height: 50px;\r\n  border: none;\r\n  outline: none;\r\n  border-radius: 10px;\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  color: #0f2539;\r\n  padding: 0 15px;\r\n  text-align: center;\r\n  background-color: #ffffff;\r\n}\