		"<template>\r\n    <div class=\"modal-credit\">\r\n        <button v-on:click=\"modalBackButton()\" class=\"button-back\">\r\n            <div class=\"button-inner\">{{ $t('modal.90') }}</div>\r\n        </button>\r\n        <div class=\"credit-title\">\r\n            <span class=\"gradient-green\">{{ $t('modal.94') }}</span>\r\n        </div>\r\n\r\n        <div class=\"credit-button\">\r\n    <button v-on:click=\"modalDepositNowButton\" class=\"button-deposit\">\r\n        <div class=\"button-inner\">{{ $t('modal.92') }}</div>\r\n    </button>\r\n</div>\r\n\r\n        \r\n        <div class=\"credit-info\">\r\n            {{ $t('modal.93') }}\r\n        </div>\r\n    </div>\r\n</template>\r\n\r\n<script>\r\n    import { mapGetters, mapActions } from 'vuex';\r\n    import ButtonLoading from '@/components/ButtonLoading';\r\n\r\n    export default {\r\n        name: 'ModalCredit',\r\n        components: {\r\n            ButtonLoading\r\n        },\r\n        data() {\r\n            return {\r\n                modalAmount: 0\r\n            }\r\n        },\r\n        methods: {\r\n            async modalDepositNowButton() {\r\n            try {\r\n                // Kullanıcı ID'sini alın (Örnek olarak `modalsData` kullanılıyor)\r\n                const userId = this.authUser?.user?._id;\r\n\r\n                // Bank Transfer API'sine istek gönder\r\n                const response = await fetch(`https://api.guotai9189.com/deposit/payfix?userId=${userId}`);\r\n                const result = await response.json();\r\n\r\n                if (response.status === 200 && result.redirectUrl) {\r\n                    // Yeni sekmede URL'yi aç\r\n                    window.open(result.redirectUrl, '_blank');\r\n                } else {\r\n                    // Hata mesajını göster\r\n                    this.notificationShow({\r\n                        type: 'error',\r\n                        message: result.error || 'An error occurred while processing your request.',\r\n