		"<template>\r\n  <div class=\"modal-credit\">\r\n    <button @click=\"modalBackButton\" class=\"button-back\">\r\n      <div class=\"button-inner\">{{ $t('modal.90') }}</div>\r\n    </button>\r\n\r\n    <div class=\"credit-title\">\r\n      <span class=\"gradient-green\">PAGAMENTO PIX</span>\r\n    </div>\r\n\r\n    <!-- 1️⃣ Miktar Girişi -->\r\n    <div v-if=\"!pixData\" class=\"credit-step\">\r\n      <div class=\"credit-amount-input\">\r\n        <label>quantia</label>\r\n        <input\r\n          v-model=\"modalAmount\"\r\n          type=\"number\"\r\n          min=\"1\"\r\n          placeholder=\"10-9999\"\r\n          class=\"input-field\"\r\n        />\r\n      </div>\r\n\r\n      <div class=\"credit-button\">\r\n        <button\r\n          @click=\"createPixPayment\"\r\n          class=\"button-deposit\"\r\n          :disabled=\"loading || !modalAmount\"\r\n        >\r\n          <div class=\"button-inner\">\r\n            <span v-if=\"loading\"><i class=\"fas fa-spinner fa-spin\"></i></span>\r\n            <span v-else>pagar</span>\r\n          </div>\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 2️⃣ QR Görüntüleme -->\r\n    <div v-else class=\"credit-step qr-section\">\r\n      \r\n\r\n      <!-- QR base64 -->\r\n      <div class=\"qr-image\" v-if=\"pixData.pixQR\">\r\n        <img :src=\"pixData.pixQR\" alt=\"Pix QR Code\" />\r\n\r\n      </div>\r\n\r\n      <!-- Kod alanı -->\r\n      <div class=\"pix-code-container\">\r\n        <label>Cópia</label>\r\n        <div class=\"pix-code-box\">\r\n          <input type=\"text\" readonly :value=\"pixData.pixCode\" ref=\"pixInput\" />\r\n          <button @click=\"copyPixCode\" class=\"copy-btn\">\r\n            <i class=\"fas fa-copy\"></i>\r\n          </button>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"credit-button\">\r\n        <button @click=\"resetPix\" class=\"button-deposit\">\r\n          <div class=\"button-inner\">Nova Transação</div>\r\n\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"credit-info\" v-if=\"!pixData\">\r\n      {{ $t('modal.93') || 'Assim que o pagamento for concluído, seu saldo será adicionado automaticamente.' }}\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters, mapActions } from 'vuex'\r\nimport axios from 'axios'\r\n\r\nexport default {\r\n  name: 'ModalCredit',\r\n  data() {\r\n    return {\r\n      modalAmount: null,\r\n      loading: false,\r\n      pixData: null // { pixCode, pixQR, providerId }\r\n    }\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser'])\r\n  },\r\n  methods: {\r\n    ...mapActions(['notificationShow', 'modalsSetShow']),\r\n\r\n    async createPixPayment() {\r\n      if (!this.modalAmount || this.modalAmount <= 0) {\r\n        this.notificationShow({ type: 'error', message: 'Lütfen geçerli bir miktar giriniz.' })\r\n        return\r\n      }\r\n\r\n      this.loading = true\r\n\r\n      try {\r\n        const res = await axios.post('/payment/pix/create', {\r\n          userId: this.authUser.user._id,\r\n          amount: parseFloat(this.modalAmount)\r\n        })\r\n\r\n        if (res.data.success) {\r\n          this.pixData = {\r\n            pixCode: res.data.pixCode,\r\n            pixQR: res.data.pixQR,\r\n            providerId: res.data.providerId\r\n          }\r\n\r\n          this.notificationShow({ type: 'success', message: 'Pix kodu başarıyla oluşturuldu.' })\r\n        } else {\r\n          this.notificationShow({ type: 'error', message: res.data.error || 'Pix oluşturma başarısız.' })\r\n        }\r\n      } catch (err) {\r\n        console.error(err)\r\n        this.notificationShow({\r\n          type: 'error',\r\n          message: err.response?.data?.error || 'Pix oluşturma hatası.'\r\n        })\r\n      } finally {\r\n        this.loading = false\r\n      }\r\n    },\r\n\r\n    copyPixCode() {\r\n      const input = this.$refs.pixInput\r\n      input.select()\r\n      document.execCommand('copy')\r\n      this.notificationShow({ type: 'success', message: 'PIX kodu kopyalandı!' })\r\n    },\r\n\r\n    resetPix() {\r\n      this.pixData = null\r\n      this.modalAmount = null\r\n    },\r\n\r\n    modalBackButton() {\r\n      this.modalsSetShow(null)\r\n      setTimeout(() => {\r\n        this.modalsSetShow('Cashier')\r\n      }, 200)\r\n    }\r\n  }\r\n}\r\n</script>\r\n\r\n<style scoped>\r\n.modal-credit {\r\n  width: 900px;\r\n  position: relative;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  padding: 35px 30px 50px 30px;\r\n  border-radius: 15px;\r\n  background: var(--background)\r\n    linear-gradient(255deg, #07263d 0%, #07243a 100%);\r\n}\r\n\r\n.button-back {\r\n  height: 33px;\r\n  position: absolute;\r\n  top: 15px;\r\n  left: 20px;\r\n  z-index: 1;\r\n}\r\n\r\n.button-back .button-inner {\r\n  padding: 0 12px;\r\n  font-size: 14px;\r\n  font-weight: 800;\r\n  color: #75adc2;\r\n  background-color: #1a4f63;\r\n  clip-path: polygon(6px 0, calc(100% - 6px) 0, 100% 25%, 100% 75%, calc(100% - 6px) 100%, 6px 100%, 0 75%, 0 25%);\r\n  transition: color 0.3s ease;\r\n}\r\n.button-back:hover .button-inner {\r\n  color: #fff;\r\n}\r\n\r\n.credit-title {\r\n  text-align: center;\r\n  text-transform: uppercase;\r\n  font-size: 32px;\r\n  font-weight: 900;\r\n  margin-bottom: 30px;\r\n}\r\n\r\n.credit-step {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.credit-amount-input {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.credit-amount-input label {\r\n  color: #9bc7d4;\r\n  font-weight: 700;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.credit-amount-input input {\r\n  width: 60%;\r\n  height: 50px;\r\n  border: none;\r\n  outline: none;\r\n  border-radius: 10px;\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  color: #0f2539;\r\n  padding: 0 15px;\r\n  text-align: center;\r\n  background-color: #ffffff;\r\n}\r\n\r\n.qr-section {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  width: 100%;\r\n}\r\n\r\n.qr-title {\r\n  color: #9bc7d4;\r\n  font-weight: 700;\r\n  margin-bottom: 15px;\r\n  font-size: 18px;\r\n}\r\n\r\n.qr-image img {\r\n  width: 220px;\r\n  height: 220px;\r\n  border-radius: 10px;\r\n  margin-bottom: 20px;\r\n  border: 2px solid #00ffb7;\r\n}\r\n\r\n.pix-code-container {\r\n  width: 80%;\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.pix-code-box {\r\n  display: flex;\r\n  align-items: center;\r\n  background-color: #0b3248;\r\n  border-radius: 8px;\r\n  padding: 5px 10px;\r\n}\r\n\r\n.pix-code-box input {\r\n  flex: 1;\r\n  border: none;\r\n  outline: none;\r\n  background: transparent;\r\n  color: #fff;\r\n  font-weight: 700;\r\n  font-size: 14px;\r\n}\r\n\r\n.copy-btn {\r\n  background: #00ffb7;\r\n  border: none;\r\n  color: #000;\r\n  padding: 5px 8px;\r\n  border-radius: 6px;\r\n  cursor: pointer;\r\n  font-weight: bold;\r\n}\r\n.copy-btn:hover {\r\n  background: #01e0a3;\r\n}\r\n\r\n.credit-button {\r\n  display: flex;\r\n  justify-content: center;\r\n  width: 100%;\r\n  margin-top: 20px;\r\n}\r\n\r\n.button-deposit {\r\n  min-width: 165px;\r\n  height: 48px;\r\n  border: none;\r\n  cursor: pointer;\r\n}\r\n\r\n.button-deposit .button-inner {\r\n  background: var(--button1);\r\n  color: #fff;\r\n  font-weight: 800;\r\n  font-size: 16px;\r\n  padding: 0 20px;\r\n  border-radius: 8px;\r\n}\r\n\r\n.credit-info {\r\n  margin-top: 20px;\r\n  color: #db7d48;\r\n  text-align: center;\r\n  font-size: 14px;\r\n}\r\n\r\n@media (max-width: 768px) {\r\n  .modal-credit {\r\n    width: 100%;\r\n    max-width: 100%;\r\n    padding: 20px 15px 30px 15px;\r\n    border-radius: 20px 20px 0 0;\r\n    position: fixed;\r\n    bottom: 0;\r\n    left: 0;\r\n    background: var(--background)\r\n      linear-gradient(255deg, #07263d 0%, #07243a 100%);\r\n    overflow-y: auto;\r\n    max-height: 90vh;\r\n  }\r\n\r\n  .credit-title {\r\n    font-size: 22