		"<template>\n    <div class=\"modal-two-step\">\n        <div class=\"step-title\">\n            <span class=\"gradient-green\">{{ $t('modal.221') }}</span>\n        </div>\n        <div class=\"step-info\">{{ $t('modal.222') }}</div>\n        <div class=\"step-input\">\n            <div class=\"input-title\">{{ $t('modal.223') }}</div>\n            <div class=\"input-container\">\n                <input v-model=\"modalCode\" type=\"text\" />\n            </div>\n        </div>\n        <div class=\"step-buttons\">\n            <button v-on:click=\"modalVerifyButton()\" class=\"button-verify\" v-bind:disabled=\"socketSendLoading !== null\">\n                <div class=\"button-inner\">\n                    <transition name=\"fade\" mode=\"out-in\">\n                        <ButtonLoading v-if=\"socketSendLoading === 'LimitedVerify'\" key=\"loading\" />\n                        <div v-else class=\"inner-content\" key=\"content\">{{ $t('modal.224') }}</div>\n                    </transition>\n                </div>\n            </button>\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import ButtonLoading from '@/components/ButtonLoading';\n\n    export default {\n        name: 'ModalTip',\n        components: {\n            ButtonLoading\n        },\n        data() {\n            return {\n                modalCode: null\n            }\n        },\n        methods: {\n            ...mapActions([\n                'notificationShow', \n                'cashierSendLimitedEnableSocket'\n            ]),\n            modalVerifyButton() {\n                if(this.modalCode === null || this.modalCode.trim() === '') {\n                    this.notificationShow({ type: 'error', message: 'Your entered 2fa code is invalid.' });\n                    return;\n                }\n\n                const data = { challengeId: this.modalsData.challengeId, twoStepId: this.modalsData.twoStepId, twoStepCode: this.modalCode.