		"<template>\n  <div class=\"modal-vault\">\n    <div class=\"vault-header\">\n      <div class=\"header-icon\">\n        <div class=\"icon-inner\">\n          <img src=\"@/assets/img/rewards/BVbTuIq3.avif\" alt=\"vault\" />\n        </div>\n      </div>\n      <div class=\"header-title\">\n      Rivo  <span>{{ activeWallet?.coinType }}</span> {{ $t('modal.225') }}\n      </div>\n    </div>\n\n    <div class=\"vault-stats\">\n      <div class=\"stats-balance\">\n        <div class=\"balance-title\">{{ $t('modal.226') }}</div>\n        <div class=\"balance-inner\">\n          <img src=\"@/assets/img/rivocoin.png\" alt=\"coin\" />\n          <AmountNumber :amount=\"activeWalletBalance\" />\n        </div>\n      </div>\n      <div class=\"stats-vaulted\">\n        <div class=\"vaulted-title\">{{ $t('modal.227') }}</div>\n        <div class=\"vaulted-inner\">\n          <img src=\"@/assets/img/rivocoin.png\" alt=\"coin\" />\n          <AmountNumber :amount=\"activeVaultBalance\" />\n        </div>\n      </div>\n    </div>\n\n    <div class=\"vault-amount\">\n      <img src=\"@/assets/img/rivocoin.png\" alt=\"coin\" />\n      <input v-model=\"modalAmount\" @input=\"modalValidateInput\" type=\"text\" placeholder=\"Enter transfer amount...\" />\n    </div>\n\n    <button @click=\"modalDepositButton()\" class=\"button-deposit\" :disabled=\"socketSendLoading !== null\">\n      <div class=\"button-inner\">{{ $t('modal.228') }}</div>\n    </button>\n    <button\n  @click=\"modalWithdrawButton()\"\n  class=\"button-withdraw\"\n  :disabled=\"socketSendLoading !== null || (activeVaultEntry?.expireAt && new Date(activeVaultEntry.expireAt).getTime() > Date.now())\"\n>\n  <div class=\"button-inner\">{{ $t('modal.229') }}</div>\n</button>\n\n\n\n    <div class=\"vault-footer\">\n      <div v-if=\"modalCountdownText === null\" class=\"footer-unlocked\">\n        <div class=\"unlocked-title\">{{ $t('modal.230') }}</div>\n        <div class=\"unlocked-content\">\n          <select v-model=\"modalTime\">\n            <option value=\"10\">{{ $t('modal.231') }} + %0.03</option>\n            <option value=\"30\">{{ $t('modal.232') }} + %0.09</option>\n            <option value=\"60\">{{ $t('modal.233') }} + %0.18</option>\n            <option value=\"360\">{{ $t('modal.234') }} + %1.10</option>\n            <option value=\"720\">{{ $t('modal.235') }} + %2.5</option>\n            <option value=\"1440\">{{ $t('modal.236') }} + %6</option>\n          </select>\n          <button @click=\"modalLockButton()\" class=\"button-lock\" :disabled=\"socketSendLoading !== null\">\n            <svg width=\"20\" height=\"20\" viewBox=\"0 0 20 20\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n              <path d=\"M4.23077 8.51212C4.23077 -1.45159 15.3077 -1.55635 15.3077 8.51212M4.23077 8.51212H1V19H19V8.51212H15.3077M4.23077 8.51212H15.3077\" stroke-width=\"2\"/>\n            </svg>\n          </button>\n        </div>\n      </div>\n      <div v-else class=\"footer-locked\">\n        <div class=\"locked-title\">\n          <svg width=\"15\" height=\"15\" viewBox=\"0 0 15 15\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n            <path d=\"M3.33333 6.42542C3.33333 -0.770594 11.3333 -0.846256 11.3333 6.42542M3.33333 6.42542H1V14H14V6.42542H11.3333M3.33333 6.42542H11.3333\" stroke-width=\"2\"/>\n          </svg>\n          {{ $t('modal.237') }}\n        </div>\n        <div class=\"locked-time\">\n          <span>{{ modalCountdownText }}</span> {{ $t('modal.238') }}\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script>\nimport { mapGetters, mapActions } from 'vuex';\nimport AmountNumber from '@/components/AmountNumber';\n\nexport default {\n  name: 'ModalVault',\n  components: { AmountNumber },\n  data() {\n    return {\n      modalAmount: null,\n      modalTime: '10',\n      modalCountdownText: null,\n      modalCountdownRepeater: null,\n      vaultRates: {\n        10: 0.0003,\n        30: 0.0009,\n        60: 0.0018,\n        360: 0.011,\n        720: 0.025,\n        1440: 0.06,\n      },\n    };\n  },\n  computed: {\n    ...mapGetters(['socketSendLoading', 'generalTimeDiff', 'modalsData', 'authUser']),\n\n    activeWallet() {\n      const user = this.authUser.user;\n      if (!user?.currency) return null;\n      const { coinType, type, chain } = user.currency;\n      return user.wallets.find(w => w.coinType === coinType && w.type === type && w.chain === chain) || { balance: 0 };\n    },\n    activeWalletBalance() {\n      return this.activeWallet?.balance || 0;\n    },\n    activeVaultEntry() {\n      const user = this.authUser.user;\n      if (!user?.vault?.balances) return null;\n      const { coinType, type, chain } = user.currency || {};\n      return user.vault.balances.find(v => v.coinType === coinType && v.type === type && v.chain === chain) || null;\n    },\n    activeVaultBalance() {\n      return this.activeVaultEntry?.amount || 0;\n    }\n  },\n  methods: {\n    ...mapActions([\n      'notificationShow',\n      'generalSendVaultDepositSocket',\n      'generalSendVaultWithdrawSocket',\n      'generalSendVaultLockSocket'\n    ]),\n    modalValidateInput() {\n      this.modalAmount = this.modalAmount.replace(',', '.').replace(/[^\\d.]/g, '');\n      this.modalAmount = this.modalAmount.indexOf('.') >= 0\n        ? this.modalAmount.substr(0, this.modalAmount.indexOf('.')) + '.' + this.modalAmount.substr((this.modalAmount.indexOf('.') + 1), 2).replace('.', '')\n        : this.modalAmount;\n    },\n    modalStartCountdown() {\n      if (!this.activeVaultEntry?.expireAt) {\n        this.modalCountdownText = null;\n        return;\n      }\n      const timeExpire = new Date(this.activeVaultEntry.expireAt).getTime();\n      const timeLeft = (timeExpire - (new Date().getTime() + this.generalTimeDiff)) / 1000;\n\n      let h = Math.floor(timeLeft / 3600);\n      let m = Math.floor((timeLeft % 3600) / 60);\n      let s = Math.floor(timeLeft % 60);\n\n      m = m < 10 ? '0' + m : m;\n      s = s < 10 ? '0' + s : s;\n\n      if (timeLeft <= 0) {\n        this.modalCountdownText = null;\n      } else {\n        this.modalCountdownText = `${h}:${m}:${s}`;\n        this.modalCountdownRepeater = requestAnimationFrame(this.modalStartCountdown);\n      }\n    },\n    modalDepositButton() {\n      const amount = parseFloat(this.modalAmount);\n      if (isNaN(amount) || amount <= 0) {\n        this.notificationShow({ type: 'error', message: 'Invalid deposit amount.' });\n        return;\n      }\n      const { coinType, chain, type } = this.authUser.user.currency;\n      this.generalSendVaultDepositSocket({ amount: Math.floor(amount), coinType, chain, type });\n    },\n    modalWithdrawButton() {\n      const amount = parseFloat(this.modalAmount);\n      if (isNaN(amount) || amount <= 0) {\n        this.notificationShow({ type: 'error', message: 'Invalid withdraw amount.' });\n        return;\n      }\n      if (this.activeVaultEntry?.expireAt && this.activeVaultEntry.expireAt > new Date().getTime()) {\n        this.notificationShow({ type: 'error', message: 'You cannot withdraw while vault is locked.' });\n        return;\n      }\n      const { coinType, chain, type } = this.authUser.user.currency;\n      this.generalSendVaultWithdrawSocket({ amount: Math.floor(amount), coinType, chain, type });\n    },\n    modalLockButton() {\n      const amount = parseFloat(this.activeVaultBalance);\n      const rate = this.vaultRates[this.modalTime];\n      if (isNaN(amount) || amount <= 0) {\n        this.notificationShow({ type: 'error', message: 'No amount available in vault to lock.' });\n        return;\n      }\n      const { coinType, chain, type } = this.authUser.user.currency;\n      this.generalSendVaultLockSocket({\n        time: Math.floor(1000 * 60 * Number(this.modalTime)),\n        rate,\n        coinType,\n        chain,\n        type\n      });\n    }\n  },\n  watch: {\n    activeVaultEntry: {\n      deep: true,\n      handler() {\n        if (this.activeVaultEntry?.expireAt) {\n          this.modalStartCountdown();\n        }\n      }\n    }\n  },\n  created() {\n    if (this.activeVaultEntry?.expireAt) {\n      this.modalStartCountdown();\n    }\n  },\n  beforeDestroy() {\n    cancelAnimationFrame(this.modalCountdownRepeater);\n  }\n};\n</script>\n\n\n\n\n<style scoped>\n.modal-vault {\n    width: 600px;\n    position: relative;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    padding: 35px 30px 30px 30px;\n    border-radius: 15px;\n    background: var(--background);\n}\n\n/* header */\n.modal-vault .vault-header {\n    width: 100%;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n}\n.modal-vault .header-icon {\n    width: 88px;\n    height: 88px;\n    padding: 1px;\n}\n.modal-vault .icon-inner {\n    width: 100%;\n    height: 100%;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}\n.modal-vault .icon-inner img {\n    width: 200px;\n    height: 200px;\n}\n.modal-vault .header-title {\n    margin-top: 12px;\n    text-align: center;\n    font-size: 32px;\n    font-weight: 900;\n    color: #ffffff;\n}\n.modal-vault .header-title span {\n    color: #ffce00;\n}\n\n/* vault stats */\n.modal-vault .vault-stats {\n    width: 100%;\n    position: relative;\n    display: flex;\n    justify-content: center;\n    margin-top: 20px;\n}\n.modal-vault .vault-stats:before,\n.modal-vault .vault-stats:after {\n    content: '';\n    width: calc(50% - 180px);\n    height: 1px;\n    position: absolute;\n    top: 50%;\n    transform: translate(0, -50%);\n}\n.modal-vault .vault-stats:before {\n    left: 0;\n    background: linear-gradient(270deg, #c68701 0%, rgba(217, 217, 217, 0) 100%);\n}\n.modal-vault .vault-stats:after {\n    right: 0;\n    background: linear-gradient(90deg, #c68701 0%, rgba(217, 217, 217, 0) 100%);\n}\n.modal-vault .stats-balance,\n.modal-vault .stats-vaulted {\n    width: 160px;\n    height: 50px;\n    position: relati