-inner {\n    width: 100%;\n    height: 100%;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    font-size: 15px;\n    font-weight: 800;\n    color: #ffffff;\n}\n.modal-vault button.button-deposit .button-inner {\n    background: rgb(44, 40, 82);\n    color: #fff;\n    box-shadow: rgb(35, 32, 66) 0px -3px 0px 0px inset, \n                rgb(89, 81, 142) 0px 2px 0px 0px inset;\n    text-shadow: rgb(25, 25, 57) 0px 1px 0px;\n    border: 4px solid var(--roo-btn-outline-color, #090C1D);\n    border-radius: 12px;\n}\n.modal-vault button.button-withdraw .button-inner {\n    border-radius: 12px;\n    background: var(--buttonyellow);\n    box-shadow: var(--buttonyellowbox);\n    color: #fff;\n    text-shadow: -1px -1px 0 #C56A18, 1px -1px 0 #C56A18,\n                 -1px 1px 0 #C56A18, 1px 1px 0 #C56A18;\n}\n\n/* footer */\n.modal-vault .vault-footer {\n    width: 100%;\n    margin-top: 30px;\n    padding-top: 25px;\n    border-top: 1px solid #173d5a;\n}\n.modal-vault .footer-unlocked {\n    width: 100%;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n}\n.modal-vault .unlocked-title {\n    font-size: 14px;\n    font-weight: 800;\n    color: #bbbfcf;\n}\n.modal-vault .unlocked-content {\n    width: 100%;\n    display: flex;\n    margin: 12px;\n}\n.modal-vault .unlocked-content select {\n    width: calc(100% - 62px);\n    height: 56px;\n    padding: 0 15px;\n    border-radius: 12px;\n    font-size: 14px;\n    font-weight: 400;\n    color: #bbbfcf;\n    background: var(--background2);\n    -webkit-appearance: none;\n    -moz-appearance: none;\n}\n.modal-vault button.button-lock {\n    width: 56px;\n    height: 56px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    margin-left: 6px;\n    border-radius: 12px;\n    background: rgba(234, 65, 65, 0.25);\n    border: 1px solid rgba(234, 65, 65, 0.5);\n}\n.modal-vault button.button-lock svg { stroke: #ea4141; }\n.modal-vault .footer-locked {\n