 } from 'vuex';\n    import LoadingAnimation from '@/components/LoadingAnimation';\n    import AdminUserTransactionsElement from '@/components/admin/user/AdminUserTransactionsElement';\n\n    export default {\n        name: 'AdminUserTransactions',\n        components: {\n            LoadingAnimation,\n            AdminUserTransactionsElement\n        },\n        methods: {\n            ...mapActions([\n                'adminSetUserTransactionListPage', \n                'adminGetUserTransactionListSocket'\n            ]),\n            adminSetPage(page) {\n                if(this.adminUserTransactionList.page === page) { return; }\n                if(page < 1 || page > Math.ceil(this.adminUserTransactionList.count / 14)) { return; }\n\n                this.adminSetUserTransactionListPage(page);\n\n                const data = { userId: this.modalsData.user._id, page: this.adminUserTransactionList.page };\n                this.adminGetUserTransactionListSocket(data);\n            }\n        },\n        computed: {\n            ...mapGetters([ \n                'modalsData', \n                'adminUserTransactionList'\n            ])\n        },\n        created() {\n            if(this.adminUserTransactionList.loading === false) {\n                const data = { userId: this.modalsData.user._id, page: this.adminUserTransactionList.page };\n                this.adminGetUserTransactionListSocket(data);\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .admin-user-transactions {\n        width: 100%;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n    }\n\n    .admin-user-transactions .transactions-head {\n        width: 100%;\n        display: flex;\n        align-items: center;\n        padding: 0 30px 20px 20px;\n        border-bottom: 1px solid rgba(24, 72, 109, 0.5);\n    }\n\n    .admin-user-transactions .head-date {\n        width: 30%;\n        font-size: 14px;\n        font-weight: 700;\n        color: 