		"<template>\r\n  <div class=\"modal-content\">\r\n    <!-- Başlık -->\r\n    <h2 class=\"modal-title\">{{ $t('notifications.title') }}</h2>\r\n\r\n    <!-- Tablar -->\r\n    <div class=\"tabs\">\r\n      <button \r\n        :class=\"{ active: activeTab === 'system' }\" \r\n        @click=\"activeTab = 'system'\">\r\n        {{ $t('notifications.systemTab') }}\r\n      </button>\r\n      <button \r\n        :class=\"{ active: activeTab === 'personal' }\" \r\n        @click=\"activeTab = 'personal'\">\r\n        {{ $t('notifications.personalTab') }}\r\n      </button>\r\n    </div>\r\n\r\n    <!-- Loading -->\r\n    <p v-if=\"loading\" class=\"loading-message\">{{ $t('notifications.loading') }}</p>\r\n\r\n    <!-- Error -->\r\n    <p v-if=\"errorMessage\" class=\"error-message\">{{ errorMessage }}</p>\r\n\r\n    <!-- Bildirim Listesi -->\r\n    <ul v-if=\"!loading && paginatedNotifications.length\" class=\"notification-list\">\r\n      <li v-for=\"notification in paginatedNotifications\" \r\n          :key=\"notification._id\" \r\n          class=\"notification-item\">\r\n\r\n        <!-- 🔹 Resim -->\r\n        <img v-if=\"notification.image\" \r\n             :src=\"getImageUrl(notification.image)\" \r\n             class=\"notification-image\" />\r\n\r\n        <div class=\"notification-body\">\r\n          <h3 class=\"notification-title\">{{ notification.title }}</h3>\r\n\r\n          <p class=\"notification-message\">\r\n            <span v-if=\"expandedIds.includes(notification._id)\">\r\n              {{ notification.message }}\r\n            </span>\r\n            <span v-else>\r\n              {{ truncateText(notification.message, 120) }}\r\n              <button \r\n                v-if=\"notification.message.length > 120\" \r\n                class=\"show-more\" \r\n                @click=\"toggleExpand(notification._id)\">\r\n                {{ $t('notifications.showMore') }}\r\n              </button>\r\n            </span>\r\n          </p>\r\n\r\n          <span class=\"notification-date\">{{ formatDate(notification.createdAt) }}</span>\r\n        </div>\r\n      </li>\r\n    </ul>\r\n\r\n    <!-- Bildirim Yok -->\r\n    <p v-else-if=\"!loading && !paginatedNotifications.length\" class=\"no-notifications\">\r\n      {{ $t('notifications.noNotifications') }}\r\n    </p>\r\n\r\n    <!-- Sayfalandırma -->\r\n    <div v-if=\"!loading && totalPages > 1\" class=\"pagination\">\r\n      <button :disabled=\"currentPage === 1\" @click=\"currentPage--\">\r\n        {{ $t('notifications.prev') }}\r\n      </button>\r\n      <span>{{ currentPage }} / {{ totalPages }}</span>\r\n      <button :disabled=\"currentPage === totalPages\" @click=\"currentPage++\">\r\n        {{ $t('notifications.next') }}\r\n      </button>\r\n    </div>\r\n\r\n    <!-- Hepsini okundu işaretle -->\r\n    <div v-if=\"!loading && paginatedNotifications.length\" class=\"mark-read\">\r\n      <button @click=\"markAllAsRead\">{{ $t('notifications.markAllRead') }}</button>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"axios\";\r\nimport { mapGetters } from \"vuex\";\r\n\r\nexport default {\r\n  name: \"ModalNotifications\",\r\n  data() {\r\n    return {\r\n      notifications: [],\r\n      loading: false,\r\n      errorMessage: \"\",\r\n      activeTab: \"system\",\r\n      expandedIds: [],\r\n      currentPage: 1,\r\n      perPage: 5\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters([\"authUser\"]),\r\n    filteredNotifications() {\r\n      if (this.activeTab === \"system\") {\r\n        return this.notifications.filter(n => !n.recipientId);\r\n      } else {\r\n        return this.notifications.filter(\r\n          n => n.recipientId === this.authUser?.user?._id\r\n        );\r\n      }\r\n    },\r\n    totalPages() {\r\n      return Math.ceil(this.filteredNotifications.length / this.perPage);\r\n    },\r\n    paginatedNotifications() {\r\n      const start = (this.currentPage - 1) * this.perPage;\r\n      return this.filteredNotifications.slice(start, start + this.perPage);\r\n    }\r\n  },\r\n  methods: {\r\n    async fetchNotifications() {\r\n      this.loading = true;\r\n      this.errorMessage = \"\";\r\n      try {\r\n        const res = await axios.get(`/notices/${this.authUser.user._id}`);\r\n        this.notifications = res.data;\r\n      } catch (err) {\r\n        console.error(err);\r\n        this.errorMessage = this.$t(\"notifications.error\");\r\n      } finally {\r\n        this.loading = false;\r\n      }\r\n    },\r\n    getImageUrl(path) {\r\n      if (!path) return \"\";\r\n      const base = process.env.VUE_APP_BACKEND_URL;\r\n      if (path.startsWith(\"http\")) return path;\r\n      return `${base}${path}`;\r\n    },\r\n    formatDate(date) {\r\n      return new Date(date).toLocaleString();\r\n    },\r\n    truncateText(text, length) {\r\n      return text.length > length ? text.substring(0, length) + \"...\" : text;\r\n    },\r\n    toggleExpand(id) {\r\n      if (this.expandedIds.includes(id)) {\r\n        this.expandedIds = this.expandedIds.filter(x => x !== id);\r\n      } else {\r\n        this.expandedIds.push(id);\r\n      }\r\n    },\r\n    markAllAsRead() {\r\n      this.notifications = this.notifications.map(n => ({\r\n        ...n,\r\n        read: true\r\n      }));\r\n    }\r\n  },\r\n  mounted() {\r\n    if (this.authUser?.user?._id) {\r\n      this.fetchNotifications();\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.modal-content {\r\n  width: 600px;\r\n  border-radius: 15px;\r\n  background: var(--background1);\r\n  padding: 30px;\r\n  max-height: 80vh;\r\n  overflow-y: auto;\r\n  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.25);\r\n  position: relative;\r\n}\r\n\r\n/* Başlık */\r\n.modal-title {\r\n  text-align: center;\r\n  font-size: 24px;\r\n  font-weight: 900;\r\n  margin-bottom: 20px;\r\n  color: #fff;\r\n}\r\n\r\n/* Tabs */\r\n.tabs {\r\n  display: flex;\r\n  justify-content: center;\r\n  margin-bottom: 20px;\r\n}\r\n.tabs button {\r\n  flex: 1;\r\n  padding: 10px;\r\n  margin: 0 5px;\r\n  border-radius: 8px;\r\n  background: var(--background2);\r\n  font-size: 16px;\r\n  font-weight: 700;\r\n  cursor: pointer;\r\n  color: #fff;\r\n  transition: 0.3s;\r\n}\r\n.tabs button.active {\r\n  background: var(--buttonyellow);\r\n  box-shadow: var(--buttonyellowbox);\r\n  color: #fff;\r\n}\r\n\r\n.notification-list {\r\n  list-style: none;   /* 🔥 Noktaları kaldırır */\r\n  padding: 0;\r\n  margin: 0;\r\n}\r\n\r\n\r\n/* Notification items */\r\n.notification-item {\r\n  background: var(--background2);\r\n  border-radius: 12px;\r\n  padding: 15px;\r\n  margin-bottom: 15px;\r\n}\r\n.notification-image {\r\n  width: 100%;\r\n  border-radius: 10px;\r\n  margin-bottom: 10px;\r\n}\r\n.notification-title {\r\n  font-size: 18px;\r\n  font-weight: 800;\r\n  margin-bottom: 6px;\r\n  color: #fff;\r\n}\r\n.notification-message {\r\n  font-size: 12px;\r\n  color: #fff;\r\n  margin-bottom: 8px;\r\n  line-height: 1.4;\r\n  word-wrap: break-word;\r\n  white-space: normal;\r\n  font-weight: bold;\r\n}\r\n.notification-date {\r\n  font-size: 12px;\r\n  color: #aaa;\r\n}\r\n\r\n/* Button */\r\n.mark-read {\r\n  margin-top: 20px;\r\n  text-align: center;\r\n}\r\n.mark-read button {\r\n  width: 100%;\r\n  height: 50px;\r\n  background: var(--buttonyellow);\r\n  box-shadow: var(--buttonyellowbox);\r\n  border-radius: 8px;\r\n  font-weight: 700;\r\n  color: #fff;\r\n  cursor: pointer;\r\n}\r\n\r\n/* ✅ Responsive breakpoints */\r\n@media only screen and (max-width: 1030px) {\r\n  .modal-content {\r\n    width: calc(100vw - 40px);\r\n  }\r\n}\r\n\r\n \r\n\r\n@media only screen and (max-width: 560px) {\r\n  .modal-title {\r\n    font-size: 18px;\r\n    margin-bottom: 15px;\r\n  }\r\n  .tabs button {\r\n    font-size: 13px;\r\n    padding: 8px;\r\n  }\r\n  .notification-title {\r\n    font-size: 16px;\r\n  }\r\n  .notification-message {\r\n    font-size: 13px;\r\n  }\r\n}\r\n\r\n.show-more {\r\n     min-width: 40px;\r\n    padding: 8px 12px;\r\n    border: none;\r\n    border-radius: 8px;\r\n    background: var(--background4);\r\n    color: #fff;\r\n    font-size: 14px;\r\n    font-weight: 600;\r\n    cursor: pointer;\r\n    transition: all 0.3s \r\nease;\r\n}\r\n.pagination {\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  gap: 10px;\r\n  margin-top: 20px;\r\n}\r\n\r\n.pagination button {\r\n  min-width: 40px;\r\n  padding: 8px 12px;\r\n  border: none;\r\n  border-radius: 8px;\r\n  background: var(--background2);\r\n  color: #fff;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  cursor: pointer;\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.pagination button:hover:not(:disabled) {\r\n  background: var(--buttonyellow);\r\n  color: #fff;\r\n  box-shadow: var(--buttonyellowbox);\r\n}\r\n\r\n.pagination button:disabled {\r\n  opacity: 0.5;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.pagination span {\r\n  font-size: 14px;\r\n  font-weight: 700;\r\n  color: #fff;\r\n}\r\n\r\n</style>\r\n",
