		"<template>\r\n  <div class=\"modal-social-complete\">\r\n    <SocialComplete :data=\"modalsData\" />\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters } from \"vuex\";\r\nimport SocialComplete from \"@/components/SocialComplete.vue\";\r\n\r\nexport default {\r\n  name: \"ModalSocialComplete\",\r\n  components: { SocialComplete },\r\n  computed: {\r\n    ...mapGetters([\"modalsData\"])\r\n  }\r\n};\r\n</script>\r\n",
		"<template>\r\n  <div class=\"social-complete-modal\">\r\n    <h2>Eksik Bilgileri Tamamla</h2>\r\n    <p>Google hesabınızla giriş yaptınız. Devam edebilmek için aşağıdaki bilgileri doldurmanız gerekiyor.</p>\r\n\r\n    <!-- Telefon -->\r\n    <div class=\"form-group\">\r\n      <label>Telefon Numarası</label>\r\n      <div class=\"phone-input\">\r\n        <select v-model=\"selectedCountryCode\">\r\n          <option v-for=\"c in countryCodes\" :key=\"c.dial_code\" :value=\"c.dial_code\">\r\n            {{ c.dial_code }} ({{ c.code }})\r\n          </option>\r\n        </select>\r\n        <input\r\n          type=\"tel\"\r\n          v-model=\"phone\"\r\n          placeholder=\"Telefon numarası\"\r\n        />\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Para Birimi -->\r\n    <div class=\"form-group\">\r\n      <label>Para Birimi</label>\r\n      <select v-model=\"fiatCurrency\">\r\n        <option v-for=\"c in fiatCurrencies\" :key=\"c.code\" :value=\"c.code\">\r\n          {{ c.label }}\r\n        </option>\r\n      </select>\r\n    </div>\r\n\r\n    <!-- Buton -->\r\n    <div class=\"actions\">\r\n      <button @click=\"submitInfo\" :disabled=\"loading\">\r\n        <span v-if=\"loading\"><i class=\"fas fa-spinner fa-spin\"></i> Kaydediliyor...</span>\r\n        <span v-else>Tamamla</span>\r\n      </button>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport countryCodes from \"@/assets/data/countryCodes.json\";\r\n\r\nexport default {\r\n  name: \"SocialComplete\",\r\n  props: [\"userId\"], \r\n  data() {\r\n    return {\r\n      phone: \"\",\r\n      selectedCountryCode: \"+90\",\r\n      fiatCurrency: \"TRY\",\r\n      loading: false,\r\n      countryCodes,\r\n      fiatCurrencies: [\r\n        { code: \"USD\", label: \"USD - US Dollar\" },\r\n        { code: \"EUR\", label: \"EUR - Euro\" },\r\n        { code: \"TRY\", label: \"TRY - Turkish Lira\" },\r\n        { code: \"GBP\", label: \"GBP - British Pound\" },\r\n        { code: \"CAD\", label: \"CAD - Canadian Dollar\" },\r\n        { code: \"AUD\", label: \"AUD - Australian Dollar\" }\r\n      ]\r\n    };\r\n  },\r\n  methods: {\r\n    async submitInfo() {\r\n      if (!this.phone) {\r\n        this.$emit(\"notify\", { type: \"error\", message: \"Telefon numarası gerekli\" });\r\n        return;\r\n      }\r\n\r\n      this.loading = true;\r\n      try {\r\n        const fullPhone = `${this.selectedCountryCode}${this.phone}`;\r\n        const res = await this.$axios.post(\"/auth/social/complete\", {\r\n          userId: this.userId,\r\n          phone: fullPhone,\r\n          fiatCurrency: this.fiatCurrency\r\n        });\r\n\r\n        if (res.data.success) {\r\n          // ✅ Token kaydet\r\n          localStorage.setItem(\"token\", res.data.token);\r\n          this.$axios.defaults.headers.common[\"x-auth-token\"] = res.data.token;\r\n\r\n          // ✅ Vuex'e user + token yaz\r\n          this.$store.commit(\"auth_set_token\", res.data.token);\r\n          this.$store.commit(\"auth_set_user\", res.data.user);\r\n\r\n          this.$store.dispatch(\"socketConnectGeneral\");\r\n          this.$store.dispatch(\"socketConnectCashier\");\r\n          if (res.data.user.rank === \"admin\" || res.data.user.rank === \"mod\") {\r\n            this.$store.dispatch(\"socketConnectAdmin\");\r\n          }\r\n\r\n          this.$emit(\"notify\", { type: \"success\", message: \"Giriş tamamlandı\" });\r\n          this.$store.dispatch(\"modalsSetShow\", null); // modal kapat\r\n        } else {\r\n          this.$emit(\"notify\", { type: \"error\", message: res.data.message || \"Bir hata oluştu\" });\r\n        }\r\n      } catch (err) {\r\n        console.error(\"SocialComplete error:\", err);\r\n        this.$emit(\"notify\", { type: \"error\", message: \"Sunucu hatası\" });\r\n      } finally {\r\n        this.loading = false;\r\n      }\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n\r\n<style scoped>\r\n.social-complete-modal {\r\n  padding: 20px;\r\n  background: #1e1e2f;\r\n  border-radius: 12px;\r\n  color: white;\r\n  max-width: 400px;\r\n}\r\n\r\n.form-group {\r\n  margin-bottom: 15px;\r\n}\r\n\r\n.phone-input {\r\n  display: flex;\r\n}\r\n\r\n.phone-input select {\r\n  margin-right: 8px;\r\n}\r\n</style>\r\n",
