		"<template>\r\n  <aside \r\n    :class=\"['sidebar', { 'sidebar-closed': isSidebarClosed, 'mobile-hidden': isMobile && !isSidebarOpen, 'mobile-horizontal': isMobile && isSidebarClosed }]\"\r\n    :style=\"{ transform: isSidebarClosed && isMobile ? 'translateX(-300px)' : 'translateX(0)' }\"\r\n  >\r\n    <div class=\"sidebar-scrollable\"> \r\n      <!-- Sidebar User Info -->\r\n      <div class=\"sidebar-user-info\" v-if=\"authUser?.user && vipLevel && vipLevel.requiredXp\">\r\n        <img :src=\"authUser.user.avatar\" alt=\"Avatar\" class=\"user-avatar\" />\r\n        <div class=\"user-info-text\">\r\n          <div class=\"username\">\r\n            {{ authUser.user.username }}\r\n            <img v-if=\"vipBadgeImage\" :src=\"vipBadgeImage\" class=\"vip-badge-on-avatar\" alt=\"VIP\"/>\r\n          </div>\r\n          <div class=\"balance-box\">\r\n            <img :src=\"activeWalletIcon\" class=\"wallet-icon\" alt=\"wallet\" />\r\n            <AmountNumber :amount=\"activeWallet.balance\" :symbol=\"getCurrencySymbol(selectedFiat)\" />\r\n          </div>\r\n          <div class=\"vip-progress\">\r\n            <div class=\"vip-progress-bar\">\r\n              <div class=\"vip-progress-fill\" :style=\"{ width: vipProgress + '%' }\"></div>\r\n            </div>\r\n            <div class=\"vip-progress-text\">\r\n  {{ vipProgress }}%  \r\n</div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Coin Card -->\r\n      <div class=\"coin-card\">\r\n        <div class=\"button-grid\">\r\n          <div class=\"grid-item\" @click=\"navigateTo('/vip')\">\r\n            <img src=\"@/assets/img/sidebar/1.png\" alt=\"VIP\" />\r\n            <span>{{ $t('sidebar.bonusvip') }}</span>\r\n          </div>\r\n          <div class=\"grid-item\" @click=\"navigateTo('/coupon')\">\r\n            <img src=\"@/assets/img/sidebar/2.png\" alt=\"Coupon\" />\r\n            <span>{{ $t('sidebar.bonusraffle') }}</span>\r\n          </div>\r\n          <div class=\"grid-item\" @click=\"navigateTo('/slot')\">\r\n            <img src=\"@/assets/img/sidebar/3.png\" alt=\"Slot\" />\r\n            <span>{{ $t('sidebar.slots') }}</span>\r\n          </div>\r\n          <div class=\"grid-item\" @click=\"navigateTo('/treasure')\">\r\n            <img src=\"@/assets/img/sidebar/4.png\" alt=\"Treasure\" />\r\n            <span>{{ $t('sidebar.rewards') }}</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"coin-center\">\r\n          <img src=\"@/assets/img/sidebar/coin.png\" alt=\"Coin\" />\r\n        </div>\r\n      </div>\r\n\r\n      <ModalJackpot v-if=\"showModal\" :showModal=\"showModal\" @close=\"closeModal\" />\r\n\r\n      <!-- Sidebar Ana Butonlar -->\r\n      <ul class=\"sidebar-buttons\">\r\n        <li v-for=\"(category, index) in categories\" :key=\"index\">\r\n          <div\r\n            :class=\"['button-item', { open: activeCategory === category.name }]\"\r\n            @click=\"toggleCategory(category.name)\"\r\n            @mouseenter=\"showSidebarTooltip(category.name, $event)\"\r\n            @mouseleave=\"hideSidebarTooltip\"\r\n          >\r\n            <img :src=\"category.icon\" :alt=\"category.name\" class=\"button-icon\" />\r\n            <span class=\"button-text\">{{ category.name }}</span>\r\n            <span class=\"dropdown-icon\" :class=\"{ 'open': activeCategory === category.name }\">\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\">\r\n                <path fill=\"#7b6cb9\" d=\"M3.464 20.536C2 19.07 2 16.714 2 12s0-7.071 1.464-8.536C4.93 2 7.286 2 12 2s7.071 0 8.535 1.464C22 4.93 22 7.286 22 12s0 7.071-1.465 8.535C19.072 22 16.714 22 12 22s-7.071 0-8.536-1.465\" opacity=\"0.3\"/>\r\n                <path fill=\"#7b6cb9\" d=\"M14.47 11.97a.75.75 0 1 1 1.06 1.06l-3 3a.75.75 0 0 1-1.06 0l-3-3a.75.75 0 1 1 1.06-1.06L12 14.44z\"/>\r\n                <path fill=\"#7b6cb9\" d=\"M14.47 7.97a.75.75 0 1 1 1.06 1.06l-3 3a.75.75 0 0 1-1.06 0l-3-3a.75.75 0 1 1 1.06-1.06L12 10.44z\"/>\r\n              </svg>\r\n            </span>\r\n          </div>\r\n\r\n          <!-- Alt Kategoriler -->\r\n          <transition name=\"slide-fade\">\r\n            <ul v-if=\"activeCategory === category.name\" class=\"sub-menu\">\r\n              <li \r\n                v-for=\"(subItem, subIndex) in category.subCategories\" \r\n                :key=\"subIndex\" \r\n                class=\"sub-item\" \r\n                @click=\"navigateTo(subItem.link)\"\r\n                @mouseenter=\"showSidebarTooltip(subItem.name, $event)\"\r\n                @mouseleave=\"hideSidebarTooltip\"\r\n              >\r\n                <img :src=\"subItem.icon\" :alt=\"subItem.name\" class=\"sub-item-icon\" />\r\n                <span class=\"sub-item-text\">{{ subItem.name }}</span>\r\n              </li>\r\n            </ul>\r\n          </transition>\r\n        </li>\r\n      </ul>\r\n\r\n      <!-- Extra Buttons -->\r\n      <div class=\"extra-buttons\">\r\n        <div \r\n          v-for=\"(button, index) in extraButtons\" \r\n          :key=\"index\" \r\n          class=\"button-item\" \r\n          @click=\"navigateTo(button.link)\"\r\n          @mouseenter=\"showSidebarTooltip(button.name, $event)\"\r\n          @mouseleave=\"hideSidebarTooltip\"\r\n        >\r\n          <img :src=\"button.icon\" :alt=\"button.name\" class=\"button-icon\" />\r\n          <span class=\"button-text\">{{ button.name }}</span>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Last Buttons -->\r\n      <div class=\"extra-buttons\">\r\n        <div \r\n          v-for=\"(button, index) in lastButtons\" \r\n          :key=\"index\" \r\n          class=\"button-item\" \r\n          @click=\"navigateTo(button.link)\"\r\n          @mouseenter=\"showSidebarTooltip(button.name, $event)\"\r\n          @mouseleave=\"hideSidebarTooltip\"\r\n        >\r\n          <img :src=\"button.icon\" :alt=\"button.name\" class=\"button-icon\" />\r\n          <span class=\"button-text\">{{ button.name }}</span>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Footer -->\r\n    <div class=\"sidebar-footer\">\r\n      <div class=\"footer-buttons\">\r\n        <div class=\"footer-btn\" @click=\"openLanguage\" @mouseenter=\"showSidebarTooltip($t('sidebar.language'), $event)\" @mouseleave=\"hideSidebarTooltip\">\r\n          <img src=\"@/assets/img/sidebar/lang.svg\" alt=\"Language\" />\r\n          <span>{{ $t('sidebar.language') }}</span>\r\n        </div>\r\n        <div class=\"footer-btn\" @click=\"openSupport\" @mouseenter=\"showSidebarTooltip($t('sidebar.support'), $event)\" @mouseleave=\"hideSidebarTooltip\">\r\n          <img src=\"@/assets/img/sidebar/support.svg\" alt=\"Support\" />\r\n          <span>{{ $t('sidebar.support') }}</span>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"footer-banner\">\r\n        <div class=\"banner-text\">\r\n          <h4>{{ $t('sidebar.footertitle') }}</h4>\r\n          <p>{{ $t('sidebar.footersubtitle') }}</p>\r\n          <button class=\"download-btn\">{{ $t('sidebar.download') }}</button>\r\n        </div>\r\n        <div class=\"banner-img\">\r\n          <img src=\"@/assets/img/app.png\" alt=\"App\" />\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </aside>\r\n\r\n  <!-- Tooltip Balonu -->\r\n  <div \r\n    v-if=\"isSidebarClosed && tooltip.visible\" \r\n    class=\"sidebar-tooltip\" \r\n    :style=\"{ top: tooltip.top + 'px', left: tooltip.left + 'px' }\"\r\n  >\r\n    {{ tooltip.text }}\r\n  </div>\r\n\r\n  <LanguageModal :show=\"showLanguageModal\" @close=\"showLanguageModal = false\"/>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters, mapActions } from 'vuex';\r\nimport ModalJackpot from '@/components/modals/ModalJackpot.vue';\r\nimport AmountNumber from '@/components/AmountNumber';\r\nimport LanguageModal from '@/components/modals/LanguageModal.vue';\r\n\r\nexport default {\r\n  data() {\r\n    return {\r\n      showModal: false, // Modal görünürlüğünü kontrol ederiz\r\n      showTooltip: false,\r\n      tooltipText: \"\",\r\n      tooltip: {\r\n      visible: false,\r\n      text: '',\r\n      top: 0,\r\n      left: 0\r\n    },\r\n      showLanguageModal: false,\r\n      selectedFiat: null,\r\n      tooltipPosition: { top: 0, left: 0 },\r\n      activeCategory: '', // Hangi kategori açık ise onu takip ediyoruz\r\n      isMobile: false, // Mobil cihaz olup olmadığını kontrol ederiz\r\n      isSidebarOpen: false, // Sidebar'ın mobilde açık olup olmadığını kontrol ederiz\r\n      activeMode: 'casino', // Casino / Sports Switch için\r\n      isDarkMode: false, // Dark / Light Mode için\r\n      activeCategory: '', // Açık olan kategoriyi takip eder\r\ncategories: [\r\n  {\r\n    name: this.$t('sidebar.casino'),\r\n    icon: require('@/assets/img/sidebar/svg/1/casino1.svg'),\r\n    subCategories: [\r\n      { name: this.$t('sidebar.favorites'), icon: require('@/assets/img/sidebar/svg/liked.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.recent'), icon: require('@/assets/img/sidebar/svg/recent.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.rivoOriginals'), icon: require('@/assets/img/sidebar/svg/rivo.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.topPicks'), icon: require('@/assets/img/sidebar/svg/toppick.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.slots'), icon: require('@/assets/img/sidebar/svg/slot.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.liveCasino'), icon: require('@/assets/img/sidebar/svg/live.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.hotGames'), icon: require('@/assets/img/sidebar/svg/hot.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.featureBuyin'), icon: require('@/assets/img/sidebar/svg/featured.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.newReleases'), icon: require('@/assets/img/sidebar/svg/newrea.svg'), link: '/live-casino' }\r\n    ]\r\n  },\r\n  {\r\n    name: this.$t('sidebar.sports'),\r\n    icon: require('@/assets/img/sidebar/svg/1/sport1.svg'),\r\n    subCategories: [\r\n      { name: this.$t('sidebar.favorites'), icon: require('@/assets/img/sidebar/svg/liked.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.soccer'), icon: require('@/assets/img/sidebar/svg/soccer.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.tennis'), icon: require('@/assets/img/sidebar/svg/tenis.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.basketball'), icon: require('@/assets/img/sidebar/svg/basketball.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.cricket'), icon: require('@/assets/img/sidebar/svg/criket.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.fifa'), icon: require('@/assets/img/sidebar/svg/fifa.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.americanFootball'), icon: require('@/assets/img/sidebar/svg/americanf.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.iceHockey'), icon: require('@/assets/img/sidebar/svg/hockey.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.handball'), icon: require('@/assets/img/sidebar/svg/handball.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.racing'), icon: require('@/assets/img/sidebar/svg/racing.svg'), link: '/live-casino' }\r\n    ]\r\n  },\r\n  {\r\n    name: this.$t('sidebar.cryptoTrading'),\r\n    icon: require('@/assets/img/sidebar/svg/1/crypto.svg'),\r\n    subCategories: [\r\n      { name: this.$t('sidebar.highLowSpread'), icon: require('@/assets/img/sidebar/svg/highlow.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.upDown'), icon: require('@/assets/img/sidebar/svg/updown.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.futures'), icon: require('@/assets/img/sidebar/svg/futures.svg'), link: '/slot' },\r\n      { name: this.$t('sidebar.stockMarket'), icon: require('@/assets/img/sidebar/svg/stock.svg'), link: '/live-casino' },\r\n      { name: this.$t('sidebar.forex'), icon: require('@/assets/img/sidebar/svg/forex.svg'), link: '/slot' }\r\n    ]\r\n  },\r\n  {\r\n    name: this.$t('sidebar.promotions'),\r\n    icon: require('@/assets/img/sidebar/svg/1/promo.svg'),\r\n    subCategories: [\r\n      { name: this.$t('sidebar.dailyContest'), icon: require('@/assets/img/sidebar/svg/contest.svg'), link: '/leaderboard' },\r\n      { name: this.$t('sidebar.weeklyRaffle'), icon: require('@/assets/img/sidebar/svg/weeklycontest.svg'), link: '/leaderboard' },\r\n      { name: this.$t('sidebar.referEarn'), icon: require('@/assets/img/sidebar/svg/refer.svg'), link: '/leaderboard' },\r\n      { name: this.$t('sidebar.rivoVault'), icon: require('@/assets/img/sidebar/svg/vault.svg'), link: '/leaderboard' },\r\n      { name: this.$t('sidebar.dailyCheckin'), icon: require('@/assets/img/sidebar/svg/dailycheck.svg'), link: '/leaderboard' }\r\n    ]\r\n  }\r\n],\r\nextraButtons: [\r\n  { name: this.$t('sidebar.vipClub'), icon: require('@/assets/img/sidebar/svg/1/vip.svg'), link: '/vip' },\r\n  { name: this.$t('sidebar.bonus'), icon: require('@/assets/img/sidebar/svg/1/bonus.svg'), link: '/rewards' },\r\n  { name: this.$t('sidebar.affiliate'), icon: require('@/assets/img/sidebar/svg/1/team.svg'), link: '/affiliates' },\r\n  { name: this.$t('sidebar.leaderBoard'), icon: require('@/assets/img/sidebar/svg/1/leader.svg'), link: '/leaderboard' }\r\n],\r\n\r\n\r\n      lastButtons: [\r\n        \r\n       \r\n        \r\n      ]\r\n      \r\n      \r\n    };\r\n  },\r\n  components: {\r\n    ModalJackpot,\r\n     AmountNumber,\r\n     LanguageModal\r\n  },\r\ncomputed: {\r\n  ...mapGetters(['authUser', 'isSidebarClosed']),\r\n  \r\n  // 🔹 Önce VIP getter’ları alıyoruz\r\n  ...mapGetters('vip', [\r\n    'vipLevel',\r\n    'userXp',\r\n    'vipProgress',\r\n    'vipDisplayXp',\r\n    'vipNextXp'\r\n  ]),\r\n\r\n  // 🔹 Sonra formatlı değer\r\n  formattedVipXp() {\r\n    if (!this.vipDisplayXp || isNaN(this.vipDisplayXp)) return '0.00';\r\n    return Number(this.vipDisplayXp).toFixed(2);\r\n  },\r\n\r\n  activeWallet() {\r\n    const user = this.authUser.user;\r\n    if (!user || !user.currency) return { balance: 0 };\r\n\r\n    const { coinType, type, chain } = user.currency;\r\n    return (\r\n      user.wallets.find(\r\n        w =>\r\n          w.coinType === coinType &&\r\n          w.type === type &&\r\n          w.chain === chain\r\n      ) || { balance: 0 }\r\n    );\r\n  },\r\n\r\n  activeWalletIcon() {\r\n    if (!this.activeWallet.coinType) return require('@/assets/img/rivocoin.png');\r\n    return require(`@/assets/img/coins/${this.activeWallet.coinType}.svg`);\r\n  },\r\n\r\n  vipBadgeImage() {\r\n    return this.vipLevel?.vipBadgeImage\r\n      ? process.env.VUE_APP_BACKEND_URL + this.vipLevel.vipBadgeImage\r\n      : null;\r\n  }\r\n},\r\n\r\n\r\n  watch: {\r\n    // Eğer Vuex'teki sidebar durumu mobilde otomatik açılmaya neden oluyorsa,\r\n    // bu watch ile Vuex durumunu gözlemleyip kontrol edebiliriz\r\n    isSidebarClosed(newVal) {\r\n      if (this.isMobile) {\r\n        this.isSidebarOpen = !newVal;\r\n      }\r\n    }\r\n  },\r\n  mounted() {\r\n     this.selectedFiat = this.authUser.user?.currency?.fiatCurrency || 'USD';\r\n  this.checkIfMobile(); \r\n  window.addEventListener('resize', this.checkIfMobile); \r\n\r\n  if (this.isMobile) {\r\n    // Mobilde sidebar'ı kapalı olarak başlatıyoruz\r\n    this.$store.commit('toggleSidebar', true); \r\n  }\r\n},\r\n  methods: {\r\n     showSidebarTooltip(text, event) {\r\n    if (!this.isSidebarClosed) return;\r\n\r\n    const rect = event.currentTarget.getBoundingClientRect();\r\n    this.tooltip.text = text;\r\n    this.tooltip.top = rect.top + rect.height / 2;\r\n    this.tooltip.left = rect.right + 10; // sağa 10px boşluk\r\n    this.tooltip.visible = true;\r\n  },\r\n  hideSidebarTooltip() {\r\n    this.tooltip.visible = false;\r\n  },\r\n    openLanguage() {\r\n  this.showLanguageModal = true;\r\n},\r\n    getCurrencySymbol(code) {\r\n      const symbols = {\r\n        USD: '$',\r\n        EUR: '€',\r\n        TRY: '₺',\r\n        BRL: 'R$',\r\n        CNY: '¥',\r\n        INR: '₹',\r\n        IDR: 'Rp',\r\n        RUB: '₽'\r\n      };\r\n      return symbols[code] || code;\r\n    },\r\n    setActiveMode(mode) {\r\n      this.activeMode = mode;\r\n    },\r\n    \r\n    toggleDarkMode() {\r\n      this.isDarkMode = !this.isDarkMode;\r\n      document.body.classList.toggle('dark-mode', this.isDarkMode);\r\n    },\r\n   \r\n    handleJackpotClick() {\r\n    console.log('Jackpot image clicked1!');\r\n    this.$emit('openJackpotModal');  // Event gönderimi\r\n  },\r\n    ...mapActions(['toggleSidebar', 'toggleSidebarMobile','openJackpotModal','modalsSetShow']),\r\n    checkIfMobile() {\r\n      this.isMobile = window.innerWidth <= 768; // 768px altındaki ekranlar mobil sayılır\r\n      if (this.isMobile) {\r\n        this.isSidebarOpen = false; // Mobilde sidebar varsayılan olarak kapalı\r\n      }\r\n    },\r\n    \r\n    \r\n\r\n    toggleCategory(categoryName) {\r\n      this.activeCategory = this.activeCategory === categoryName ? '' : categoryName;\r\n    },\r\n  getSubCategories(categoryName) {\r\n    const category = this.categories.find(cat => cat.name === categoryName);\r\n    return category ? category.subCategories : [];\r\n  },\r\n  navigateTo(route) {\r\n    this.$router.push(route);\r\n  },\r\n    toggleMobileSidebar() {\r\n      this.isSidebarOpen = !this.isSidebarOpen; // Mobilde sidebar'ı açıp kapatır\r\n      this.toggleSidebarMobile(); // Vuex'teki durumu da günceller\r\n    },\r\n  },\r\n  beforeDestroy() {\r\n    window.removeEventListener('resize', this.checkIfMobile);\r\n  },\r\n  \r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.sidebar {\r\n  background: var(--sidebar-bg);\r\n  position: fixed;\r\n  top: 61px;\r\n  bottom: 0px;\r\n  left: 0px;\r\n  width: 16.375rem;\r\n  display: flex;\r\n  flex-direction: column;\r\n  overflow-y: auto;\r\n  max-height: calc(100vh - 61px);\r\n 