n}\r\n.sub-menu + .button-item {\r\n  margin-top: 10px;\r\n}\r\n.sub-menu + .button-item {\r\n  margin-top: 10px;\r\n}\r\n\r\n.sub-item:hover {\r\n  background: var(--hover);\r\n  border-radius: 8px;\r\n}\r\n\r\n/* Alt Menü İkonları */\r\n.sub-item-icon {\r\n  width: 20px;\r\n  height: 20px;\r\n}\r\n\r\n/* Alt Menü Metni */\r\n.sub-item-text {\r\n  padding-left: 8px;\r\n  font-family: var(--font-header);\r\n  font-size: 12px;\r\n    font-variant-numeric: lining-nums tabular-nums;\r\n    font-weight: 600;\r\n    letter-spacing: -.02em;\r\n    line-height: 18px;\r\n    margin-bottom: 0;\r\n    margin-top: 0;\r\n  color: white;\r\n  flex-grow: 1;\r\n}\r\n\r\n.extra-buttons {\r\n  position: relative;\r\n  border-radius: 5px;\r\n  margin: 10px;\r\n  background: var(--background2);\r\n  z-index: 1;\r\n   \r\n\r\n  /* overflow: hidden kaldırılıyor */\r\n  /* overflow: visible olarak bırakılıyor */\r\n}\r\n\r\n\r\n\r\n\r\n\r\n/* Extra Butonlar */\r\n.extra-buttons .button-item {\r\n  position: relative;     /* ✅ gerekli */\r\n  overflow: hidden;       /* ✅ before efektinin taşmaması için */\r\n  z-index: 1;    \r\n  border-radius: 6px;\r\n  margin-bottom: 5px;\r\n  background: none;\r\n  display: flex;\r\n  align-items: center;\r\n  cursor: pointer;\r\n}\r\n\r\n.extra-buttons .button-item:hover {\r\n  background: var(--hover);\r\n}\r\n\r\n/* Extra Buton İkonları */\r\n.extra-buttons .button-icon {\r\n  width: 24px;\r\n  height: 24px;\r\n  margin-right: 10px;\r\n}\r\n\r\n/* Animasyon Efektleri */\r\n.slide-fade-enter-active {\r\n  transition: all 0.3s ease-out;\r\n}\r\n\r\n.slide-fade-leave-active {\r\n  transition: all 0.2s ease-in;\r\n}\r\n\r\n.slide-fade-enter, .slide-fade-leave-to {\r\n  transform: translateY(-5px);\r\n  opacity: 0;\r\n}\r\n@media (max-width: 768px) {\r\n  .sidebar {\r\n     \r\n    z-index: 9;\r\n    height: calc(100vh - 121px);\r\n  }\r\n\r\n  .sidebar-closed {\r\n    transform: translateX(-100%); /* Kapalıyken görünmez */\r\n  }\r\n\r\n  .sidebar-open