		"const state = {\r\n    isSpinModalOpen: false, // Spin modalının açık/kapalı durumu\r\n    lastSpinTimestamp: null, // Kullanıcının son spin zamanı\r\n    spinRewards: [], // Mevcut ödül listesi\r\n  };\r\n  \r\n  const mutations = {\r\n    SET_SPIN_MODAL(state, status) {\r\n      state.isSpinModalOpen = status;\r\n    },\r\n    SET_LAST_SPIN_TIMESTAMP(state, timestamp) {\r\n      state.lastSpinTimestamp = timestamp;\r\n    },\r\n    SET_SPIN_REWARDS(state, rewards) {\r\n      state.spinRewards = rewards;\r\n    },\r\n  };\r\n  \r\n  const actions = {\r\n    openSpinModal({ commit }) {\r\n      commit('SET_SPIN_MODAL', true);\r\n    },\r\n    closeSpinModal({ commit }) {\r\n      commit('SET_SPIN_MODAL', false);\r\n    },\r\n    setLastSpinTimestamp({ commit }, timestamp) {\r\n      commit('SET_LAST_SPIN_TIMESTAMP', timestamp);\r\n    },\r\n    setSpinRewards({ commit }, rewards) {\r\n      commit('SET_SPIN_REWARDS', rewards);\r\n    },\r\n  };\r\n  \r\n  const getters = {\r\n    isSpinModalOpen: (state) => state.isSpinModalOpen,\r\n    lastSpinTimestamp: (state) => state.lastSpinTimestamp,\r\n    spinRewards: (state) => state.spinRewards,\r\n  };\r\n  \r\n  export default {\r\n    namespaced: true, // Modül isimlendirme desteği\r\n    state,\r\n    mutations,\r\n    actions,\r\n    getters,\r\n  };\r\n  ",
		"import axios from 'axios';\r\n\r\nconst state = {\r\n  userVip: null,\r\n  userXp: 0,\r\n  currentLevel: null,\r\n  vipLevels: [] // 🔹 Tüm VIP seviyeleri burada tutulacak\r\n};\r\n\r\nconst mutations = {\r\n  SET_VIP_DATA(state, { userVip, userXp, currentLevel, vipLevels }) {\r\n    state.userVip = userVip;\r\n    state.userXp = userXp;\r\n    state.currentLevel = currentLevel;\r\n    state.vipLevels = vipLevels || []; // 🔹 boş gelirse array yap\r\n  }\r\n};\r\n\r\nconst actions = {\r\n  async fetchUserVip({ commit, rootGetters }) {\r\n    const userId = rootGetters.authUser?.user?._id;\r\n    if (!userId) return;\r\n\r\n    try {\r\n      const res = await axios.get(`/vip/user-level/${userId}`);\r\n      commit('SET_VIP_DATA', {\r\n        userVip: res.data.userVip,\r\n        userXp: res.data.xp || 0,            // 🔹 Burada düzeltme\r\n        currentLevel: res.data.currentLevel,\r\n        vipLevels: res.data.levels || []\r\n      });\r\n    } catch (err) {\r\n      console.error('VIP verisi alınamadı:', err);\r\n    }\r\n  }\r\n};\r\n\r\n\r\nconst getters = {\r\n  userVip: state => state.userVip,\r\n  userXp: state => state.userXp,\r\n  vipLevel: state => state.currentLevel,\r\n\r\n  // 🔹 Bir sonraki seviyeyi bul\r\n  nextVipLevel: (state) => {\r\n    if (!state.currentLevel || !state.vipLevels.length) return null;\r\n    return state.vipLevels.find(l => l.level === state.currentLevel.level + 1) || null;\r\n  },\r\n\r\n  // 🔹 Bir sonraki seviyeye kalan XP\r\n  vipNextXp: (state, getters) => {\r\n    const next = getters.nextVipLevel;\r\n    if (!next) return 0;\r\n    return Math.max(next.requiredXp - state.userXp, 0);\r\n  },\r\n\r\n  // 🔹 Progress hesaplama (bir sonraki level bazlı)\r\n  vipProgress: (state, getters) => {\r\n    const next = getters.nextVipLevel;\r\n    if (!next || !next.requiredXp) return 100; // max level ise full\r\n    const percent = (state.userXp / next.requiredXp) * 100;\r\n    return Math.min(percent, 100).toFixed(2);\r\n  },\r\n\r\n  // 🔹 Görüntülenecek XP stringi (örn: 355 / 500)\r\n  vipDisplayXp: (state, getters) => {\r\n    const next = getters.nextVipLevel;\r\n    if (!next || !next.requiredXp) return `${state.userXp} / MAX`;\r\n    const current = Math.min(state.userXp, next.requiredXp);\r\n    return `${current} / ${next.requiredXp}`;\r\n  }\r\n};\r\n\r\nexport default {\r\n  namespaced: true,\r\n  state,\r\n  mutations,\r\n  actions,\r\n  getters\r\n};\r\n",
		"// store/modules/futures.js\r\nconst state = {\r\n  bets: []  // sadece aktif kullanıcıya ait pozisyonlar\r\n}\r\n\r\nconst getters = {\r\n  futuresBets: state => state.bets,\r\n  futuresActiveBets: state => state.bets.filter(b => b.status === 'open'),\r\n  futuresClosedBets: state => state.bets.filter(b => b.status === 'closed')\r\n}\r\n\r\nconst mutations = {\r\n  futures_add_or_update_bet(state, bet) {\r\n    const idx = state.bets.findIndex(b => b._id === bet._id)\r\n    if (idx >= 0) {\r\n      state.bets.splice(idx, 1, bet) // update\r\n    } else {\r\n      state.bets.push(bet) // add\r\n    }\r\n  }\r\n}\r\n\r\nexport default {\r\n  state,\r\n  getters,\r\n  mutations\r\n}\r\n",
		"import { createStore } from 'vuex'\n\nimport modals from './modules/modals'\nimport notifications from './modules/notifications'\nimport sound from './modules/sound'\nimport socket from './modules/socket'\nimport auth from './modules/auth'\nimport general from './modules/general'\nimport user from './modules/user'\nimport chat from './modules/chat'\nimport rain from './modules/rain'\nimport crash from './modules/crash'\nimport roll from './modules/roll'\nimport blackjack from './modules/blackjack'\nimport duels from './modules/duels'\nimport mines from './modules/mines'\nimport towers from './modules/towers'\nimport unbox from './modules/unbox'\nimport battles from './modules/battles'\nimport upgrader from './modules/upgrader'\nimport cashier from './modules/cashier'\nimport rakeback from './modules/rakeback'\nimport affiliates from './modules/affiliates'\nimport leaderboard from './modules/leaderboard'\nimport jackpot from './modules/jackpot'\nimport admin from './modules/admin'\nimport spin from './modules/spin'\nimport vip from './modules/vip'\nimport futures from './modules/futures'\n\nconst store = createStore({\n  modules: {\n    modals,\n    notifications,\n    sound,\n    socket,\n    auth,\n    general,\n    user,\n    chat,\n    rain,\n    futures,\n    crash,\n    roll,\n    blackjack,\n    duels,\n    mines,\n    towers,\n    unbox,\n    battles,\n    upgrader,\n    cashier,\n    rakeback,\n    affiliates,\n    leaderboard,\n    jackpot,\n    admin,\n    vip,\n    spin\n  }\n})\n\nexport default store\n",
		"<template>\n  <div>\n    <HomeBanner />\n    \n    <HomeMobile />\n      <HomeCategory\n      :categories=\"categories\"\n      :selectedCategory=\"selectedCategory\"\n      @update:selectedCategory=\"handleCategorySelect\"\n    />\n\n    <Search />\n   <HomeGame :selectedCategory=\"selectedCategory || 'lobby'\" />\n\n\n\n  </div>\n</template>\n\n<script>\nimport HomeBanner from '@/components/home/HomeBanner.vue';\nimport HomeMobile from '@/components/home/HomeMobile.vue';\nimport HomePromo from '@/components/home/HomePromo.vue';\nimport HomeCategory from '@/components/home/HomeCategory.vue';\nimport Search from '@/components/Search.vue';\nimport HomeGame from '@/components/home/HomeGame.vue';\nimport axios from 'axios';\n\nexport default {\n  name: 'Home',\n  components: {\n    HomeBanner,\n    HomePromo,\n    HomeMobile,\n    HomeCategory,\n    Search,\n    HomeGame\n  },\n  data() {\n    return {\n      categories: [],\n      selectedCategory: 'lobby'\n    };\n  },\n  created() {\n    axios.get('/public/categories')\n      .then(res => {\n        this.categories = res.data || [];\n      })\n      .catch(err => {\n        console.error('Kategori verisi alınamadı:', err);\n      });\n  },\n    methods: {\n    handleCategorySelect(slug) {\n  this.selectedCategory = slug;\n}\n\n  }\n};\n</script>\n",
		"<template>\r\n  <div class=\"banner-wrapper\" :style=\"isMobileOrTablet ? 'padding: 0' : 'padding: 0px'\">\r\n    <!-- PC Layout -->\r\n    <div class=\"banner-pc\" v-if=\"!isMobileOrTablet\">\r\n      <div class=\"home-row\">\r\n        <!-- Sol Geniş Slider (1 adet) -->\r\n        <div class=\"banner-card wide\">\r\n          <div class=\"embla\" ref=\"emblaTop\">\r\n            <div class=\"embla__container\">\r\n              <div\r\n                v-for=\"banner in homeTopBanners\"\r\n                :key=\"banner._id\"\r\n                class=\"embla__slide slide\"\r\n              >\r\n                <img :src=\"backendUrl + banner.imageUrl\" class=\"banner-image\" />\r\n                <div class=\"banner-text\">\r\n                  <h2 class=\"text3d-lg\">{{ banner.title }}</h2>\r\n                  <p class=\"text3d-sm\">{{ banner.subtitle }}</p>\r\n                  <a :href=\"banner.link\" class=\"banner-button\">{{ $t('home.Go Now') }}</a>\r\n                </div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Sağda 2 Banner (üst/alt) -->\r\n        <div class=\"right-banners\" style=\"display: none;\">\r\n          <div\r\n            v-for=\"banner in rightBanners\"\r\n            :key=\"banner._id\"\r\n            class=\"banner-card narrow\"\r\n          >\r\n            <img :src=\"backendUrl + banner.imageUrl\" class=\"banner-image\" />\r\n            <div class=\"banner-text\">\r\n              <h2 class=\"text3d-sm\">{{ banner.title }}</h2>\r\n              <a :href=\"banner.link\"> </a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Mobil Layout (dokunmuyoruz) -->\r\n    <div class=\"banner-mobile\" v-else>\r\n      <div class=\"embla\" ref=\"emblaMobile\">\r\n        <div class=\"embla__container\">\r\n          <div\r\n            v-for=\"banner in mobileTopBanners\"\r\n            :key=\"banner._id\"\r\n            class=\"embla__slide banner-card mobile-stacked\"\r\n          >\r\n            <img :src=\"backendUrl + banner.imageUrl\" class=\"banner-image\" />\r\n            <div class=\"banner-text\">\r\n              <h2 class=\"text3d-lg\">{{ banner.title }}</h2>\r\n              <p class=\"text3d-sm\">{{ banner.subtitle }}</p>\r\n              <a :href=\"banner.link\" class=\"banner-button\">{{ $t('home.Go Now') }}</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from 'axios'\r\nimport EmblaCarousel from 'embla-carousel'\r\nimport Autoplay from 'embla-carousel-autoplay'\r\n\r\nexport default {\r\n  data() {\r\n    return {\r\n      banners: [],\r\n      isMobileOrTablet: false,\r\n      backendUrl: process.env.VUE_APP_BACKEND_URL || 'https://apievrymatrix5d84k321.com',\r\n      emblaTop: null,\r\n      emblaMobile: null\r\n    }\r\n  },\r\n  computed: {\r\n    // Sol geniş slider\r\n    homeTopBanners() {\r\n      return this.banners.filter(b => b.position === 'HomeTop')\r\n    },\r\n    // Mobil için ikinci slider verisini koruyoruz\r\n    homeTop2Banners() {\r\n      return this.banners.filter(b => b.position === 'HomeTop2')\r\n    },\r\n    // Sağdaki 2 banner\r\n    rightBanners() {\r\n      return this.banners\r\n        .filter(b => b.position === 'HomeAlt' || b.position === 'HomeAlt2')\r\n        .slice(0, 2)\r\n    },\r\n    // Mobilde ikisi birleşsin\r\n    mobileTopBanners() {\r\n      return [...this.homeTopBanners, ...this.homeTop2Banners]\r\n    }\r\n  },\r\n  mounted() {\r\n    this.isMobileOrTablet = window.innerWidth <= 1024\r\n    this.fetchBanners()\r\n  },\r\n  beforeUnmount() {\r\n    // bileşen kapanırken temizle\r\n    if (this.emblaTop) this.emblaTop.destroy()\r\n    if (this.emblaMobile) this.emblaMobile.destroy()\r\n  },\r\n  methods: {\r\n    async fetchBanners() {\r\n      try {\r\n        const res = await axios.get('/public/banners')\r\n        this.banners = res.data\r\n        this.$nextTick(() => this.initEmbla())\r\n      } catch (err) {\r\n        console.error('API ERROR', err)\r\n      }\r\n    },\r\n    initEmbla() {\r\n      const options = { loop: true }\r\n      const autoplay = Autoplay({\r\n        delay: 4000, // 4 saniyede bir geçiş\r\n        stopOnInteraction: true,\r\n        stopOnMouseEnter: true\r\n      })\r\n\r\n      // PC için sol geniş slider\r\n      if (this.$refs.emblaTop && !this.emblaTop) {\r\n        this.emblaTop = EmblaCarousel(this.$refs.emblaTop, options, [autoplay])\r\n      }\r\n\r\n      // Mobil için slider\r\n      if (this.$refs.emblaMobile && !this.emblaMobile) {\r\n        this.emblaMobile = EmblaCarousel(this.$refs.emblaMobile, options, [autoplay])\r\n      }\r\n    }\r\n  }\r\n}\r\n</script>\r\n\r\n\r\n\r\n<style scoped>\r\n.banner-wrapper {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 16px;\r\n}\r\n\r\n/* PC düzeni */\r\n.banner-pc .home-row {\r\n  display: flex;\r\n  gap: 24px;\r\n}\r\n\r\n.banner-card {\r\n  position: relative;\r\n  border-radius: 10px;\r\n  overflow: hidden;\r\n  box-shadow: 0px 6px 20px rgba(0, 0, 0, 0.5);\r\n  width: 100%;\r\n}\r\n\r\n.banner-card.wide {  /* sol slider */\r\n  height: 350px;\r\n  flex: 2;\r\n}\r\n\r\n.right-banners {     /* sağdaki iki banner */\r\n  display: flex;\r\n  flex-direction: row;\r\n  gap: 21px;\r\n  flex: 1;\r\n}\r\n.banner-card.narrow {\r\n  height: 300px;\r\n}\r\n\r\n/* Mobil */\r\n.banner-card.mobile-stacked {\r\n  height: 150px;\r\n  flex: 0 0 90%;\r\n  margin-right: 16px;\r\n}\r\n\r\n/* görseller */\r\n.banner-image {\r\n  width: 100%;\r\n  height: 100%;\r\n  \r\n}\r\n\r\n\r\n/* Başlık üst-orta, buton sağ-altta – her kart için tutarlı */\r\n.banner-text {\r\n  position: absolute;\r\n  inset: 0;                       /* tüm alanı kapla */\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between; /* üst başlık — alt buton */\r\n  align-items: center;            /* yatayda ortala */\r\n  padding: 16px;\r\n  color: #fff;\r\n  z-index: 2;\r\n}\r\n\r\n.text3d-lg {\r\n  font-size: 2rem;\r\n  font-weight: 800;\r\n  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.7);\r\n  margin: 0;\r\n  text-align: center;\r\n  width: 100%;\r\n  display: none;\r\n}\r\n.text3d-sm {\r\n  font-size: 1.2rem;\r\n  font-weight: 800;\r\n  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.7);\r\n  margin: 0.5rem 0 0 0;\r\n  text-align: center;\r\n  width: 100%;\r\n  display: none;\r\n}\r\n\r\n/* buton sağ-alt köşeye güzelce otursun */\r\n.banner-button {\r\n  position: fixed;        /* Sabitlenmiş buton */\r\n  bottom: 20px;           /* Ekranın altından 20px yukarıda */\r\n  right: 20px;            /* Ekranın sağından 20px içeride */\r\n  z-index: 9999;          /* Hep üstte olsun */\r\n\r\n  padding: 12px 20px;\r\n  font-weight: 700;\r\n  font-size: 1rem;\r\n  color: #fff;\r\n  text-decoration: none;\r\n  border-radius: 12px;\r\n\r\n  background: var(--buttonyellow);\r\n  box-shadow: rgb(197, 106, 24) 0px -3px 0px 0px inset,\r\n              rgb(255, 234, 47) 0px 2px 0px 0px inset;\r\n  text-shadow: 0px 0px 4px #C56A18;\r\n\r\n  transition: all 0.25s ease;\r\n}\r\n\r\n.banner-button:hover {\r\n  transform: scale(1.05) translateY(-3px);\r\n  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.3),\r\n              rgb(197, 106, 24) 0px 2px 6px 0px inset;\r\n}\r\n\r\n.banner-button.small {\r\n  font-size: 0.9rem;\r\n  padding: 8px 14px;\r\n}\r\n\r\n/* Embla */\r\n.embla { \r\n  overflow: hidden; \r\n  height: 100%;      /* slider yüksekliği kartı doldursun */\r\n}\r\n.embla__container { \r\n  display: flex; \r\n  height: 100%;      /* container da kartın yüksekliğine uysun */\r\n}\r\n.embla__slide { \r\n  flex: 0 0 100%; \r\n  position: relative; \r\n  height: 100%;      /* her slide, kartı tam doldursun */\r\n  display: flex;     /* içeriği hizalayalım */\r\n}\r\n.embla__slide img {\r\n  width: 100%;\r\n  height: 100%;\r\n\r\n}\r\n\r\n</style>\r\n",
