		"<template>\r\n  <div class=\"category-bar-wrapper\">\r\n    <div class=\"category-bar\" ref=\"scrollRef\">\r\n      <!-- Lobby -->\r\n      <button\r\n        ref=\"lobbyBtn\"\r\n        :class=\"['category-button', { active: selectedCategory === 'lobby' }]\"\r\n        @click=\"selectCategory('lobby')\"\r\n      >\r\n        <img class=\"avatar\" :src=\"fullImg('/public/img/lobby.svg')\" alt=\"Lobby\" />\r\n        <span class=\"label\"> {{ $t('home.Lobby') }}</span>\r\n      </button>\r\n\r\n      <!-- Rivo Originals -->\r\n      <button\r\n        :class=\"['category-button', { active: selectedCategory === 'rivo-originals' }]\"\r\n        @click=\"selectCategory('rivo-originals')\"\r\n      >\r\n        <img class=\"avatar\" :src=\"fullImg('/public/img/rivo.gif')\" alt=\"Rivo Originals\" />\r\n        <span class=\"label\">Rivo</span>\r\n      </button>\r\n\r\n      <!-- Favorites -->\r\n      <button\r\n        v-if=\"hasFavorites\"\r\n        :class=\"['category-button', { active: selectedCategory === 'favorites' }]\"\r\n        @click=\"selectCategory('favorites')\"\r\n      >\r\n        <img class=\"avatar\" :src=\"fullImg('/public/img/star.svg')\" alt=\"Favorites\" />\r\n        <span class=\"label\"> {{ $t('home.Favorites') }}</span>\r\n      </button>\r\n\r\n      <!-- Dynamic Categories -->\r\n      <button\r\n        v-for=\"category in categories\"\r\n        :key=\"category._id\"\r\n        :ref=\"setButtonRef(category._id)\"\r\n        :class=\"['category-button', { active: selectedCategory === category.slug }]\"\r\n        @click=\"selectCategory(category.slug)\"\r\n      >\r\n        <img class=\"avatar\" :src=\"fullImg(category.img)\" :alt=\"category.name\" />\r\n        <span class=\"label\">{{ category.name }}</span>\r\n      </button>\r\n\r\n      <div\r\n        class=\"underline\"\r\n        :style=\"{ left: underlineStyle.left + 'px', width: underlineStyle.width + 'px' }\"\r\n      />\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nexport default {\r\n  name: 'HomeCategory',\r\n  props: {\r\n    categories: {\r\n      type: Array,\r\n      required: true\r\n    },\r\n    selectedCategory: {\r\n      type: String,\r\n      default: 'lobby'\r\n    },\r\n    hasFavorites: {\r\n      type: Boolean,\r\n      default: false\r\n    }\r\n  },\r\n  data() {\r\n    return {\r\n      underlineStyle: { left: 0, width: 0 },\r\n      buttonRefs: {},\r\n      isMobile: false\r\n    };\r\n  },\r\n  watch: {\r\n    selectedCategory() {\r\n      this.$nextTick(this.updateUnderline);\r\n    }\r\n  },\r\n  mounted() {\r\n    this.isMobile = window.innerWidth <= 1024;\r\n    this.updateUnderline();\r\n    window.addEventListener('resize', this.handleResize);\r\n  },\r\n  beforeDestroy() {\r\n    window.removeEventListener('resize', this.handleResize);\r\n  },\r\n  methods: {\r\n    handleResize() {\r\n      this.isMobile = window.innerWidth <= 1024;\r\n    },\r\n    selectCategory(id) {\r\n      this.$emit('update:selectedCategory', id);\r\n    },\r\n    updateUnderline() {\r\n      const id = this.selectedCategory || 'lobby';\r\n      const btn = this.buttonRefs[id] || this.$refs.lobbyBtn;\r\n      if (btn) {\r\n        this.underlineStyle.left = btn.offsetLeft;\r\n        this.underlineStyle.width = btn.offsetWidth;\r\n      }\r\n    },\r\n    setButtonRef(id) {\r\n      return (el) => {\r\n        if (el) this.buttonRefs[id] = el;\r\n      };\r\n    },\r\n    fullImg(path) {\r\n      if (!path) return '';\r\n      if (path.startsWith('http')) return path;\r\n      return process.env.VUE_APP_BACKEND_URL + path;\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.category-bar-wrapper {\r\n  width: 100%;\r\n  position: relative;\r\n}\r\n\r\n\r\n.category-bar {\r\n  width: 100%;\r\n   \r\n  display: flex;\r\n  overflow-x: auto;\r\n       gap: 7px;\r\n  border-radius: 5px;\r\n  margin-bottom: 15px;\r\n          margin-top: 15px;\r\n  position: relative;\r\n  scrollbar-width: none;\r\n}\r\n.category-bar::-webkit-scrollbar {\r\n  display: none;\r\n}\r\n\r\n.category-button {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 0.4rem 0.8rem;\r\n  background: #191939;\r\n  border-radius: 10px;\r\n  color: white;\r\n   padding-top: 10px;\r\n   padding-bottom: 10px;\r\n  border: none;\r\n  cursor: pointer;\r\n  font-family: var(--font-header);\r\n  font-weight: 600;\r\n  font-size: 13px;\r\n}\r\n.category-button .avatar {\r\n  width: 20px;\r\n  height: 20px;\r\n  object-fit: contain;\r\n}\r\n.category-button.active {\r\n  color: #fff;\r\n  background: #7841ee;\r\n}\r\n\r\n@media (max-width: 1024px) {\r\n  .category-button {\r\n   \r\n    font-size: 12px;\r\n  }\r\n  .category-button .avatar {\r\n    width: 20px;\r\n    height: 20px;\r\n  }\r\n  .category-bar-wrapper {\r\n    padding-left: 10px;\r\n    padding-right: 10px;\r\n    z-index: 1;\r\n    margin-top: 10px;\r\n  }\r\n \r\n\r\n  .category-bar {\r\n  width: 100%;\r\n  padding-top: 5px;\r\n  padding: 0;\r\n  display: flex;\r\n  overflow-x: auto;\r\n \r\n  border-radius: 8px;\r\n  margin-bottom: 15px;\r\n  position: relative;\r\n  scrollbar-width: none;\r\n}\r\n}\r\n</style>\r\n",
