		"<template>\r\n  <div class=\"search-bar-wrapper\">\r\n    <!-- Search Bar -->\r\n    <div class=\"search-bar\" :class=\"{ focused }\">\r\n      <img src=\"@/assets/icons/search.svg\" alt=\"Son Aramalar\" class=\"section-icon\" />\r\n      <input\r\n        type=\"text\"\r\n        v-model=\"query\"\r\n        @focus=\"handleFocus\"\r\n        @input=\"handleInput\"\r\n        :placeholder=\"$t('search.placeholder')\"\r\n      />\r\n      <span class=\"close-icon\" v-if=\"focused\" @click=\"handleClose\">✖</span>\r\n    </div>\r\n\r\n    <!-- Expandable Area -->\r\n    <transition name=\"slide-down\">\r\n      <div v-if=\"focused\" class=\"search-results-panel\">\r\n\r\n        <!-- Arama Sonuçları -->\r\n        <div v-if=\"query.trim().length > 1 && results.length > 0\" class=\"section\">\r\n          <div class=\"section-header\">\r\n           <img src=\"@/assets/icons/promo.svg\" alt=\"Sonuçlar\" class=\"section-icon\" />\r\n          <h4 class=\"section-title\">{{ $t('search.result') }}</h4>\r\n          </div>\r\n          <div class=\"scroll-row\">\r\n            <div\r\n  v-for=\"game in results\"\r\n  :key=\"game._id\"\r\n  class=\"game-card\"\r\n  @click=\"launchGame(game)\"\r\n>\r\n              <img class=\"game-banner\" :src=\"fullImg(game.banner)\" :alt=\"game.game_name\" />\r\n              <div class=\"game-info\">\r\n                <div class=\"game-name\">{{ game.game_name }}</div>\r\n                <div class=\"provider-code\">{{ game.provider?.name || game.provider_code }}</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Son Aramalar -->\r\n        <div class=\"section\">\r\n          <div class=\"section-header\">\r\n          <img src=\"@/assets/icons/clock.svg\" alt=\"Son Aramalar\" class=\"section-icon\" />\r\n          <h4 class=\"section-title\"> {{ $t('search.lastsearch') }}</h4>\r\n          </div>\r\n          <div class=\"recent-searches\">\r\n            <span\r\n              v-for=\"(item, index) in recentSearches\"\r\n              :key=\"index\"\r\n              class=\"tag\"\r\n              @click=\"query = item\"\r\n            >\r\n              {{ item }}\r\n            </span>\r\n            <span v-if=\"recentSearches.length === 0\"> {{ $t('search.nosearch') }}</span>\r\n          </div>\r\n        </div>\r\n\r\n        <!-- Önerilen Oyunlar -->\r\n        <div class=\"section\">\r\n          <div class=\"section-header\">\r\n          <img src=\"@/assets/icons/thumbup.svg\" alt=\"Önerilenler\" class=\"section-icon\" />\r\n          <h4 class=\"section-title\"> {{ $t('search.likesearch') }}</h4>\r\n          </div>\r\n          <div class=\"scroll-row\">\r\n            <div\r\n  v-for=\"game in featuredGames\"\r\n  :key=\"game._id\"\r\n  class=\"game-card\"\r\n  @click=\"launchGame(game)\"\r\n>\r\n              <img class=\"game-banner\" :src=\"fullImg(game.banner)\" :alt=\"game.game_name\" />\r\n              <div class=\"game-info\">\r\n                <div class=\"game-name\">{{ game.game_name }}</div>\r\n                <div class=\"provider-code\">{{ game.provider?.name || game.provider_code }}</div>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n\r\n      </div>\r\n    </transition>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from 'axios';\r\n\r\nexport default {\r\n  name: 'Search',\r\n  data() {\r\n    return {\r\n      query: '',\r\n      focused: false,\r\n      results: [],\r\n      featuredGames: [],\r\n      recentSearches: [],\r\n      searchTimeout: null // <-- debounce için\r\n    };\r\n  },\r\n  methods: {\r\n    launchGame(game) {\r\n    this.$router.push({ name: 'GameStart', params: { id: game.game_code } });\r\n  },\r\n    handleFocus() {\r\n      this.focused = true;\r\n    },\r\n    handleClose() {\r\n      this.query = '';\r\n      this.focused = false;\r\n      this.results = [];\r\n    },\r\n    handleInput() {\r\n      clearTimeout(this.searchTimeout);\r\n\r\n      this.searchTimeout = setTimeout(() => {\r\n        const q = this.query.trim();\r\n        if (q.length > 1) {\r\n          axios\r\n            .get(`/public/games/search?query=${q}`)\r\n            .then(res => {\r\n              this.results = res.data;\r\n            })\r\n            .catch(() => (this.results = []));\r\n\r\n          if (!this.recentSearches.includes(q)) {\r\n            const updated = [q, ...this.recentSearches.slice(0, 9)];\r\n            this.recentSearches = updated;\r\n            localStorage.setItem('recentSearches', JSON.stringify(updated));\r\n          }\r\n        } else {\r\n          this.results = [];\r\n        }\r\n      }, 1000); // 1 saniye bekleme süresi\r\n    },\r\n    fullImg(path) {\r\n      if (!path) return '';\r\n      if (path.startsWith('http')) return path;\r\n      return process.env.VUE_APP_BACKEND_URL + path;\r\n    }\r\n  },\r\n  created() {\r\n    this.recentSearches = JSON.parse(localStorage.getItem('recentSearches') || '[]');\r\n    axios\r\n      .get('/public/games/featured/list?limit=15')\r\n      .then(res => (this.featuredGames = res.data))\r\n      .catch(() => (this.featuredGames = []));\r\n  }\r\n};\r\n\r\n</script>\r\n\r\n<style scoped>\r\n\r\n.search-bar-wrapper {\r\n  width: 100%;\r\n      padding-left: 3px;\r\n    padding-right: 3px;\r\n  \r\n}\r\n\r\n\r\n.search-bar {\r\n  position: relative;\r\n  display: flex;\r\n  align-items: center;\r\n  background: var(--search-bg);\r\n  padding: 10px 16px;\r\n  border-radius: 5px;\r\n  color: white;\r\n  transition: all 0.3s ease;\r\n  z-index: 1;\r\n  overflow: hidden;\r\n      outline: rgb(44, 40, 82) solid 2px;\r\n}\r\n\r\n \r\n\r\n.search-bar input {\r\n  background: transparent;\r\n  border: none;\r\n  outline: none;\r\n  flex: 1;\r\n  color: white;\r\n  font-size: 16px;\r\n  margin-left: 10px;\r\n}\r\n\r\n\r\n.search-icon,\r\n.close-icon {\r\n  font-size: 18px;\r\n  cursor: pointer;\r\n}\r\n.search-results-panel {\r\n  position: relative;\r\n  overflow: hidden;\r\n  border-radius: 0 0 5px 5px;\r\n  padding: 20px;\r\n  color: white;\r\n  background: var(--search2-bg);\r\n  transition: all 0.3s ease;\r\n  z-index: 1;\r\n  margin-top: -3px;\r\n}\r\n\r\n \r\n\r\n\r\n.section {\r\n  margin-bottom: 20px;\r\n}\r\n\r\n.section-header {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.section-icon {\r\n  width: 20px;\r\n  height: 20px;\r\n  object-fit: contain;\r\n}\r\n.section-title {\r\n  font-weight: bold;\r\n  margin: 0;\r\n  font-size: 14px;\r\n}\r\n\r\n.scroll-row {\r\n  display: flex;\r\n  overflow-x: auto;\r\n  gap: 15px;\r\n}\r\n.scroll-row::-webkit-scrollbar {\r\n  height: 6px;\r\n}\r\n.scroll-row::-webkit-scrollbar-thumb {\r\n  background: #ffffff22;\r\n  border-radius: 5px;\r\n}\r\n.game-card {\r\n  width: 150px;\r\n  flex-shrink: 0;\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n  background: transparent;\r\n  transition: transform 0.2s ease;\r\n}\r\n.game-card:hover {\r\n  transform: scale(1.02);\r\n}\r\n\r\n.game-banner {\r\n  width: 100%;\r\n\r\n}\r\n.game-info {\r\n  padding: 8px;\r\n}\r\n.game-name {\r\n  font-size: 14px;\r\n  font-weight: bold;\r\n}\r\n.provider-code {\r\n  font-size: 12px;\r\n  color: #ccc;\r\n}\r\n.recent-searches .tag {\r\n  background: var(--search-bg);\r\n  padding: 6px 10px;\r\n  border-radius: 5px;\r\n  margin: 4px 6px 0 0;\r\n  display: inline-block;\r\n  cursor: pointer;\r\n}\r\n.slide-down-enter-active,\r\n.slide-down-leave-active {\r\n  transition: all 0.3s ease;\r\n}\r\n.slide-down-enter,\r\n.slide-down-leave-to {\r\n  opacity: 0;\r\n  transform: translateY(-10px);\r\n}\r\n\r\n@media (max-width: 1024px) {\r\n \r\n  .search-bar-wrapper {\r\n  padding-left: 10px;\r\n  padding-right: 10px;\r\n  \r\n}\r\n}\r\n</style>\r\n",
