		"<template>\r\n  <div class=\"home-game-wrapper\">\r\n\r\n    <CategorySection\r\n  v-if=\"selectedCategory === 'lobby' || selectedCategory === 'rivo-originals'\"\r\n  :category=\"rivoOriginals\"\r\n  :favorites=\"favorites\"\r\n  :onToggleFavorite=\"toggleFavorite\"\r\n  :loading=\"false\"\r\n  :isRivoOriginals=\"true\"  \r\n  key=\"rivo\"\r\n/>\r\n\r\n  <!-- HOT CATEGORY -->\r\n<!-- HOT CATEGORY -->\r\n<CategorySection\r\n  v-if=\"selectedCategory === 'lobby' || selectedCategory === 'hot'\"\r\n  :category=\"hotCategory\"\r\n  :favorites=\"favorites\"\r\n  :onToggleFavorite=\"toggleFavorite\"\r\n  :loading=\"loading\"\r\n  key=\"hot\"\r\n/>\r\n\r\n<!-- FAVORITES -->\r\n<CategorySection\r\n  v-if=\"(selectedCategory === 'favorites' && favoriteGames.length > 0) || (selectedCategory === 'lobby' && favoriteGames.length > 0)\"\r\n  :category=\"favoriteCategoryWithUniqueKeys\"\r\n  :favorites=\"favorites\"\r\n  :onToggleFavorite=\"toggleFavorite\"\r\n  :loading=\"false\"\r\n  key=\"favorites\"\r\n/>\r\n\r\n\r\n\r\n\r\n \r\n\r\n<!-- API CATEGORIES -->\r\n<CategorySection\r\n  v-for=\"category in visibleCategories\"\r\n  :key=\"'cat-' + category._id\"\r\n  :category=\"category\"\r\n  :favorites=\"favorites\"\r\n  :onToggleFavorite=\"toggleFavorite\"\r\n  :loading=\"loading\"\r\n/>\r\n\r\n\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from 'axios';\r\nimport CategorySection from '@/components/home/CategorySection.vue';\r\n\r\nexport default {\r\n  name: 'HomeGame',\r\n  components: {\r\n    CategorySection\r\n  },\r\n  props: {\r\n    selectedCategory: {\r\n      type: String,\r\n      default: 'lobby'\r\n    }\r\n  },\r\n  data() {\r\n    return {\r\n      categories: [],\r\n      favorites: [],\r\n      favoriteGames: [],\r\n      loading: true,\r\n      hotCategory: {\r\n        name: 'Hot',\r\n        img: '/public/img/hot.svg',\r\n        slug: 'hot',\r\n        total_games: 0,\r\n        games: []\r\n      },\r\n      favoriteCategory: {\r\n        name: 'Favorites',\r\n        img: '/public/img/star.svg',\r\n        slug: 'favorites',\r\n        total_games: 0,\r\n        games: []\r\n      },\r\n      rivoOriginals: {\r\n        name: 'Rivo Originals',\r\n        img: '/public/img/rivo.gif',\r\n        slug: 'rivo-originals',\r\n        total_games: 6,\r\n        games: [\r\n          { _id: \"rivo1\", game_name: \"Rivo Turbo\", banner: \"/public/img/games/6.png\", views: 1234, provider: { name: \"RivoBIT\" }, slug: \"turbo\" },\r\n          { _id: \"rivo8\", game_name: \"Rivo Witch X\", banner: \"/public/img/games/1.png\", views: 432, provider: { name: \"RivoBIT\" }, route: \"Crash\" },\r\n          { _id: \"rivo2\", game_name: \"Rivo Wingo\", banner: \"/public/img/games/3.png\", views: 867, provider: { name: \"RivoBIT\" }, slug: \"Wingo\" },\r\n          { _id: \"rivo3\", game_name: \"Rivo Unbox\", banner: \"/public/img/games/2.png\", views: 432, provider: { name: \"RivoBIT\" }, slug: \"unbox\" },\r\n          { _id: \"rivo4\", game_name: \"Rivo Mines\", banner: \"/public/img/games/4.png\", views: 432, provider: { name: \"RivoBIT\" }, slug: \"mines\" },\r\n          { _id: \"rivo5\", game_name: \"Rivo Towers\", banner: \"/public/img/games/5.png\", views: 432, provider: { name: \"RivoBIT\" }, slug: \"towers\" },\r\n          { _id: \"rivo6\", game_name: \"Rivo Roll\", banner: \"/public/img/games/7.png\", views: 432, provider: { name: \"RivoBIT\" }, slug: \"roll\" },\r\n \r\n        ]\r\n      }\r\n    };\r\n  },\r\n computed: {\r\n  favoriteCategoryWithUniqueKeys() {\r\n    // ID'yi değiştirme, sadece key için ayrı kullan\r\n    const seen = new Set();\r\n    const uniqueGames = this.favoriteGames.filter(game => {\r\n      if (seen.has(game._id)) return false;\r\n      seen.add(game._id);\r\n      return true;\r\n    });\r\n\r\n    return {\r\n      ...this.favoriteCategory,\r\n      games: uniqueGames\r\n    };\r\n  },\r\n   visibleCategories() {\r\n    if (!this.categories) return [];\r\n    // Lobby seçiliyse tüm kategorileri göster\r\n    if (this.selectedCategory === 'lobby') return this.categories;\r\n\r\n    // Değilse sadece eşleşeni göster\r\n    return this.categories.filter(c => c.slug === this.selectedCategory);\r\n  }\r\n},\r\n\r\n  methods: {\r\n    toggleFavorite(gameId) {\r\n      const exists = this.favorites.includes(gameId);\r\n      const updated = exists\r\n        ? this.favorites.filter(id => id !== gameId)\r\n        : [...this.favorites, gameId];\r\n\r\n      this.favorites = updated;\r\n      localStorage.setItem('gameFavorites', JSON.stringify(updated));\r\n      this.updateFavoriteGames();\r\n    },\r\n    updateFavoriteGames() {\r\n      const allGames = [\r\n  ...this.hotCategory.games,\r\n  ...this.rivoOriginals.games,\r\n  ...this.categories.flatMap(c => c.games)\r\n];\r\n\r\n// Favori oyunları benzersiz hale getir\r\nconst favMap = {};\r\nallGames.forEach(game => {\r\n  if (this.favorites.includes(game._id)) {\r\n    favMap[game._id] = game;\r\n  }\r\n});\r\nconst favGames = Object.values(favMap);\r\n\r\nthis.favoriteGames = favGames;\r\nthis.favoriteCategory.games = favGames;\r\nthis.favoriteCategory.total_games = favGames.length;\r\n    },\r\n    getCategoryGames(category) {\r\n  return category.games.filter(game => !this.favorites.includes(game._id));\r\n}\r\n\r\n  },\r\n  \r\n  created() {\r\n    const savedFavorites = JSON.parse(localStorage.getItem('gameFavorites') || '[]');\r\n    this.favorites = savedFavorites;\r\n\r\n    axios.get('/public/games/featured/list?limit=50')\r\n      .then(res => {\r\n        this.hotCategory.games = res.data || [];\r\n        this.hotCategory.total_games = this.hotCategory.games.length;\r\n      })\r\n      .catch(() => {\r\n        this.hotCategory.games = [];\r\n      });\r\n\r\n    axios.get('/public/games/categories/with-games')\r\n      .then(res => {\r\n        this.categories = res.data.data || [];\r\n      })\r\n      .catch(() => {\r\n        this.categories = [];\r\n      })\r\n      .finally(() => {\r\n        this.loading = false;\r\n        this.updateFavoriteGames();\r\n      });\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.home-game-wrapper {\r\n  padding: 20px 0px;\r\n}\r\n</style>\r\n",
		"<template>\r\n  <div class=\"category-section\">\r\n    <div class=\"category-header\">\r\n      <div class=\"category-title\">\r\n        <img :src=\"fullImg(this.category.img)\" alt=\"icon\" class=\"category-icon\" />\r\n        <h3>{{ this.category.name }}</h3>\r\n      </div>\r\n      <div class=\"category-controls\">\r\n           <button\r\n    v-if=\"!['rivo-originals','hot','favorites'].includes(category.slug)\"\r\n    class=\"see-all\"\r\n    @click=\"goToCategory(this.category.slug)\"\r\n  >\r\n    {{ $t('home.See All') }} \r\n    ({{ typeof this.category.total_games === 'number' \r\n        ? this.category.total_games \r\n        : this.category.games.length }})\r\n  </button>\r\n\r\n       <button\r\n    class=\"arrow left\"\r\n    :class=\"{ disabled: atStart }\"\r\n    @click=\"scroll('left')\"\r\n  >\r\n    &lt;\r\n  </button>\r\n  <button\r\n    class=\"arrow right\"\r\n    :class=\"{ disabled: atEnd }\"\r\n    @click=\"scroll('right')\"\r\n  >\r\n    &gt;\r\n  </button>\r\n\r\n      \r\n      </div>\r\n    </div>\r\n\r\n    <div\r\n      class=\"game-list\"\r\n      ref=\"scrollRef\"\r\n      @mousedown=\"startDrag\"\r\n      @mousemove=\"onDrag\"\r\n      @mouseup=\"stopDrag\"\r\n      @mouseleave=\"stopDrag\"\r\n    >\r\n      <div\r\n        v-for=\"game in this.category.games\"\r\n        :key=\"(this.category.slug === 'favorites' ? 'fav-' : '') + game._id\"\r\n        class=\"game-card\"\r\n        @mouseenter=\"hovered = game._id\"\r\n        @mouseleave=\"hovered = null\"\r\n        @click=\"launchGame(game)\"\r\n      >\r\n        <div class=\"img-wrapper\">\r\n          <div class=\"banner-card\">\r\n            <img :src=\"fullImg(game.banner)\" alt=\"banner\" class=\"banner\" />\r\n          </div>\r\n\r\n          <div class=\"overlay\" v-if=\"hovered === game._id\">\r\n            <div class=\"overlay-content\"></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"game-info\">\r\n          <div class=\"top\">\r\n            <span class=\"provider\">{{ game.provider?.name || game.provider_code }}</span>\r\n            <span\r\n              class=\"favorite\"\r\n              :class=\"{ active: favorites.includes(game._id) }\"\r\n              @click.stop=\"onToggleFavorite(game._id)\"\r\n            >\r\n              <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"20\" height=\"20\" viewBox=\"0 0 24 24\"\r\n                :fill=\"favorites.includes(game._id) ? '#ffea2f' : '#2c3756'\">\r\n                <path\r\n                  d=\"M22,10.1c0.1-0.5-0.3-1.1-0.8-1.1l-5.7-0.8L12.9,3c-0.1-0.2-0.2-0.3-0.4-0.4C12,2.3,11.4,2.5,11.1,3L8.6,8.2L2.9,9\r\n                    C2.6,9,2.4,9.1,2.3,9.3c-0.4,0.4-0.4,1,0,1.4l4.1,4l-1,5.7c0,0.2,0,0.4,0.1,0.6c0.3,0.5,0.9,0.7,1.4,0.4l5.1-2.7l5.1,2.7\r\n                    c0.1,0.1,0.3,0.1,0.5,0.1v0c0.1,0,0.1,0,0.2,0c0.5-0.1,0.9-0.6,0.8-1.2l-1-5.7l4.1-4C21.9,10.5,22,10.3,22,10.1z\"\r\n                />\r\n              </svg>\r\n            </span>\r\n          </div>\r\n          <div class=\"bottom\">\r\n            <span class=\"name\">{{ shortName(game.game_name) }}</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nexport default {\r\n  name: 'CategorySection',\r\n  props: {\r\n    category: Object,\r\n    favorites: Array,\r\n    onToggleFavorite: Function,\r\n    loading: Boolean,\r\n    isRivoOriginals: {\r\n      type: Boolean,\r\n      default: false\r\n    }\r\n  },\r\n  data() {\r\n    return {\r\n      isDragging: false,\r\n      startX: 0,\r\n      scrollStart: 0,\r\n      hovered: null,\r\n      atStart: true,\r\n    atEnd: false,\r\n    };\r\n  },\r\n  mounted() {\r\n  this.checkScrollEdges()\r\n  this.$refs.scrollRef.addEventListener('scroll', this.checkScrollEdges)\r\n},\r\nbeforeUnmount() {\r\n  this.$refs.scrollRef.removeEventListener('scroll', this.checkScrollEdges)\r\n},\r\n  methods: {\r\n     scroll(direction) {\r\n    const el = this.$refs.scrollRef\r\n    const card = el.querySelector('.game-card')\r\n    const step = card ? card.offsetWidth + 10 : 300\r\n    const amount = direction === 'left' ? -step : step\r\n    el.scrollBy({ left: amount, behavior: 'smooth' })\r\n  },\r\n  checkScrollEdges() {\r\n    const el = this.$refs.scrollRef\r\n    this.atStart = el.scrollLeft <= 0\r\n    this.atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth\r\n  },\r\nlaunchGame(game) {\r\n  if (this.isRivoOriginals) {\r\n    const routeMap = {\r\n      crash: 'Crash',\r\n      roll: 'Roll',\r\n      blackjack: 'Blackjack',\r\n      duels: 'Duels',\r\n      mines: 'Mines',\r\n      towers: 'Towers',\r\n      unbox: 'UnboxOverview',\r\n      turbo: 'TurboTrade',\r\n      wingo: 'Wingo'\r\n    };\r\n\r\n    const slug = (game.slug || game.route || '').toLowerCase();\r\n    const routeName = routeMap[slug];\r\n\r\n    if (routeName) {\r\n      this.$router.push({ name: routeName });\r\n    } else {\r\n      console.warn('Bu Rivo oyunu desteklenmiyor:', game.game_name, `(${slug})`);\r\n    }\r\n  } else {\r\n    this.$router.push({ name: 'GameStart', params: { id: game.game_code } });\r\n  }\r\n},\r\n\r\n    fullImg(path) {\r\n      if (!path) return '';\r\n      if (path.startsWith('http')) return path;\r\n      return process.env.VUE_APP_BACKEND_URL + path;\r\n    },\r\n    shortName(name) {\r\n      return name.length > 18 ? name.slice(0, 18) + '...' : name;\r\n    },\r\n    scroll(direction) {\r\n      const el = this.$refs.scrollRef;\r\n      const amount = direction === 'left' ? -300 : 300;\r\n      el.scrollBy({ left: amount, behavior: 'smooth' });\r\n    },\r\n    startDrag(e) {\r\n      this.isDragging = true;\r\n      this.startX = e.pageX - this.$refs.scrollRef.offsetLeft;\r\n      this.scrollStart = this.$refs.scrollRef.scrollLeft;\r\n    },\r\n    onDrag(e) {\r\n      if (!this.isDragging) return;\r\n      e.preventDefault();\r\n      const x = e.pageX - this.$refs.scrollRef.offsetLeft;\r\n      const walk = (x - this.startX) * 2;\r\n      this.$refs.scrollRef.scrollLeft = this.scrollStart - walk;\r\n    },\r\n    stopDrag() {\r\n      this.isDragging = false;\r\n    },\r\n    goToCategory(slug) {\r\n      this.$router.push({ name: 'Category', params: { slug } });\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.category-section {\r\n  \r\n}\r\n\r\n.category-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 12px;\r\n}\r\n\r\n.category-title {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n}\r\n\r\n.category-icon {\r\n  width: 28px;\r\n  height: 28px;\r\n}\r\n\r\n.category-controls {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n}\r\n\r\n \r\n.see-all {\r\n  background: linear-gradient(to bottom, #01e0a3 0%, #00aa6d 95%, transparent 60%),\r\n              linear-gradient(to bottom, #3a6d5f, #3a6d5f);\r\n  border: none;\r\n  padding: 6px 12px;\r\n  color: black;\r\n  font-weight: bold;\r\n  cursor: pointer;\r\n}\r\n\r\n.arrow {\r\n  border: none;\r\n  padding: 6px 12px;\r\n  font-weight: bold;\r\n  cursor: pointer;\r\n  color: white;\r\n  transition: background 0.3s;\r\n}\r\n\r\n/* Aktif */\r\n.arrow.left {\r\n  border-radius: 6px 0 0 6px;\r\n  background: #2c2852;\r\n      height: 35px;\r\n}\r\n.arrow.right {\r\n  border-radius: 0 6px 6px 0;\r\n  background: #2c2852;\r\n      height: 35px;\r\n}\r\n\r\n/* Pasif (scroll başında veya sonunda) */\r\n.arrow.left.disabled {\r\n  background: #191939; /* gri ton */\r\n  cursor: not-allowed;\r\n      height: 35px;\r\n}\r\n.arrow.right.disabled {\r\n  background: #191939;\r\n  cursor: not-allowed;\r\n      height: 35px;\r\n}\r\n\r\n/* See all */\r\n.see-all {\r\n  border-radius: 6px;\r\n      height: 35px;\r\n  background: #2c2852;\r\n  color: white;\r\n}\r\n\r\n\r\n/* See all butonu (her taraf yuvarlak) */\r\n.see-all {\r\n  border-radius: 6px; /* normal yuvarlak */\r\n}\r\n\r\n\r\n.game-list {\r\n  display: flex;\r\n  overf