		"<template>\n    <div class=\"crash\">\n        <div class=\"crash-container\">\n            <transition name=\"fade\" mode=\"out-in\">\n                <div v-if=\"socketCrash.connected === false\" class=\"container-loading\" key=\"loading\">\n                    <div class=\"loading-element\"></div>\n                    <div class=\"loading-element\"></div>\n                </div>\n                <div v-else class=\"container-data\" key=\"data\">\n                    <div class=\"data-left\">\n                        <CrashGame />\n                        <CrashHistory />\n                    </div>\n\n                    <CrashControls />\n                </div>\n            </transition>\n        </div>\n\n       \n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import Bets from '@/components/bets/Bets';\n    import CrashGame from '@/components/crash/CrashGame';\n    import CrashHistory from '@/components/crash/CrashHistory';\n    import CrashControls from '@/components/crash/CrashControls';\n\n    export default {\n        name: 'Crash',\n        metaInfo: {\n            title: 'Crash - https://velobet280.com'\n        },\n        components: {\n            Bets,\n            CrashGame,\n            CrashHistory,\n            CrashControls\n        },\n        methods: {\n            ...mapActions(['socketConnectCrash', 'socketDisconnectCrash'])\n        },\n        computed: {\n            ...mapGetters(['socketCrash']),\n        },\n        created() {\n            this.socketConnectCrash();\n        },\n        beforeRouteLeave(to, from, next) {\n            this.socketDisconnectCrash();\n            next();\n        }\n    }\n</script>\n\n<style scoped>\n    .crash {\n        width: 100%;\n        position: relative;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 45px 10px;\n\n    }\n\n    .crash .crash-container {\n        width: 1120px;\n        border-radius: 12px;\n        background: var(--background);\n        box-shadow: 0px 4px 10px rgba(7, 26, 41, 0.25);\n        border: 4px solid rgb(9, 12, 29);\n       \n    }\n\n   \n\n    .crash .container-loading {\n        display: flex;\n        justify-content: space-between;\n        padding: 15px;\n    }\n\n    .crash .loading-element {\n        height: 510px;\n        position: relative;\n        border-radius: 15px;\n        background: var(--button1);\n        overflow: hidden;\n    }\n\n    .crash .loading-element:nth-child(1) {\n        width: calc(100% - 290px);\n    }\n\n    .crash .loading-element:nth-child(2) {\n        width: 275px;\n    }\n\n    .crash .loading-element::after {\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        content: '';\n        top: 0;\n        left: 0;\n        animation-name: loading_animation;\n        animation-duration: 1s;\n        animation-timing-function: ease;\n        animation-iteration-count: infinite;\n        background: linear-gradient(to right, #ffffff00 0%, rgba(255, 255, 255, 0.1) 50%, #ffffff00 100%);\n    }\n\n    .crash .container-loading.fade-leave-active {\n        transition: opacity 0.5s;\n    }\n\n    .crash .container-loading.fade-leave-to {\n        opacity: 0;\n    }\n\n    .crash .container-data {\n        display: flex;\n        justify-content: space-between;\n        padding: 15px;\n    }\n\n    .crash .container-data.fade-enter-active {\n        transition: opacity 0.5s;\n    }\n\n    .crash .container-data.fade-enter-from {\n        opacity: 0;\n    }\n\n    .crash .data-left {\n        width: calc(100% - 290px);\n    }\n\n    @keyframes loading_animation {\n        0% { transform: translateX(-100%); }\n        50% { transform: translateX(100%); }\n        100% { transform: translateX(100%); }\n    }\n\n    @media only screen and (max-width: 1140px) {\n        \n        .crash .crash-container {\n            width: 100%;\n        }\n\n    }\n\n    @media only screen and (max-width: 950px) {\n\n        .crash {\n            padding: 25px 10px 443px 10px;\n        }\n\n        .crash .container-loading,\n        .crash .container-data {\n            flex-direction: column;\n            padding: 10px;\n        }\n\n        .crash .loading-element {\n            width: 100%!important;\n        }\n\n        .crash .loading-element:nth-child(2) {\n            height: 200px;\n            margin-top: 15px;\n        }\n\n        .crash .data-left {\n            width: 100%;\n        }\n\n    }\n</style>\n",
		"<template>\n    <div class=\"bets\">\n        <div class=\"bets-nav\">\n            <button v-if=\"authUser.user !== null\" v-on:click=\"betsSetTab('my')\" class=\"nav-link\" v-bind:class=\"{ 'link-active': betsTab === 'my' }\">{{ $t('bets.1') }}</button>\n            <button v-on:click=\"betsSetTab('all')\" class=\"nav-link\" v-bind:class=\"{ 'link-active': betsTab === 'all' }\">{{ $t('bets.2') }}</button>\n          \n        </div>\n        <div class=\"bets-list\">\n            <div class=\"list-head\">\n                <div class=\"head-game\">{{ $t('bets.5') }}</div>\n                <div class=\"head-user\">{{ $t('bets.6') }}</div>\n                <div class=\"head-time\">{{ $t('bets.7') }}</div>\n                <div class=\"head-wager\">{{ $t('bets.8') }}</div>\n                <div class=\"head-multiplier\">{{ $t('bets.9') }}</div>\n                <div class=\"head-payout\">{{ $t('bets.10') }}</div>\n            </div>\n            <div class=\"list-content\">\n                <transition name=\"fade\" mode=\"out-in\">\n                    <div v-if=\"generalBets.bets === null || generalBets.loading === true\" class=\"content-loading\" key=\"loading\">\n                        <LoadingAnimation />\n                    </div>\n                    <div v-else-if=\"betsGetList.length > 0\" class=\"content-list\" key=\"data\">\n\n                        <BetsElement v-for=\"bet in betsGetList\" v-bind:key=\"bet._id + betsTab\" v-bind:bet=\"bet\" />\n\n                    </div>\n                    <div v-else class=\"content-empty\" key=\"empty\">{{ $t('bets.11') }}</div>\n                </transition>\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import LoadingAnimation from '@/components/LoadingAnimation';\n    import BetsElement from '@/components/bets/BetsElement';\n\n    export default {\n        name: 'Bets',\n        components: {\n            LoadingAnimation,\n            BetsElement\n        },\n        data() {\n            return {\n                betsTab: 'all'\n            }\n        },\n        methods: {\n            ...mapActions([\n                'generalGetBetsDataSocket'\n            ]),\n            betsSetTab(tab) {\n                this.betsTab = tab;\n            }\n        },\n        computed: {\n            ...mapGetters([\n                'authUser', \n                'generalBets'\n            ]),\n            betsGetList() {\n                let bets = [];\n\n                if(this.generalBets.bets !== null && this.generalBets.bets[this.betsTab] !== undefined) {\n                    bets = this.generalBets.bets[this.betsTab].slice(0, 12);\n                }\n\n                return bets;\n            }\n        },\n        created() {\n            if(this.generalBets.bets === null && this.generalBets.loading === false) {\n                const data = {};\n                this.generalGetBetsDataSocket(data);\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .bets {\n        width: 100%;\n        margin-top: 50px;\n    }\n\n    .bets .bets-nav {\n        width: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n    }\n\n    .bets .bets-nav button.nav-link {\n        position: relative;\n        margin-right: 40px;\n        padding-bottom: 23px;\n        font-size: 16px;\n        font-weight: 600;\n        color: #bbbfd0;\n        transition: all 0.3s ease;\n    }\n\n    .bets .bets-nav button.nav-link:last-of-type {\n        margin-right: 0;\n    }\n\n    .bets .bets-nav button.nav-link::after {\n       content: '';\n       width: 100%;\n       height: 1px;\n       position: absolute;\n       left: 0;\n       bottom: 0;\n       background-color: #ffffff;\n       transition: all 0.3s ease;\n       opacity: 0;\n   }\n\n   .bets .bets-nav button.nav-link.link-active {\n       color: #ffffff;\n   }\n\n   .bets .bets-nav button.nav-link.link-active::after {\n       opacity: 1;\n   }\n\n   .bets .bets-list {\n       width: 100%;\n       height: 440px;\n       position: relative;\n       border-radius: 15px;\n       overflow: hidden;\n   }\n\n   .bets .bets-list::after {\n       content: '';\n       width: 100%;\n       height: 28px;\n       position: absolute;\n       bottom: 0;\n       left: 0;\n       background: linear-gradient(0deg, rgba(1, 22, 39, 0.75) 0%, rgba(1, 22, 39, 0) 100%);\n       z-index: 1;\n   }\n\n   .bets .list-head {\n        width: 100%;\n        height: 52px;\n        position: relative;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        padding: 0 35px;\n        background-color: #082842;\n   }\n\n   .bets .head-game {\n       width: 20%;\n       font-weight: 700;\n       font-size: 14px;\n       color: #8bacc8;\n   }\n\n   .bets .head-user {\n       width: 20%;\n       font-weight: 700;\n       font-size: 14px;\n       color: #8bacc8;\n   }\n\n   .bets .head-time {\n       width: 20%;\n       font-weight: 700;\n       font-size: 14px;\n       color: #8bacc8;\n   }\n\n   .bets .head-wager {\n        width: 15%;\n        font-weight: 700;\n        font-size: 14px;\n        color: #8bacc8;\n    }\n\n    .bets .head-multiplier {\n        width: 10%;\n        font-weight: 700;\n        font-size: 14px;\n        color: #8bacc8;\n    }\n\n    .bets .head-payout {\n        width: 15%;\n        text-align: right;\n        font-weight: 700;\n        font-size: 14px;\n        color: #8bacc8;\n    }\n\n    .bets .list-content {\n        width: 100%;\n        height: calc(100% - 52px);\n        overflow: hidden;\n    }\n\n    .bets .content-loading {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n    }\n\n    .bets .content-loading.fade-leave-active {\n        transition: opacity 0.5s;\n    }\n\n    .bets .content-loading.fade-leave-to {\n        opacity: 0;\n    }\n\n    .bets .content-data {\n        width: 100%;\n    }\n\n    .bets .content-empty {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        text-transform: uppercase;\n        font-size: 12px;\n        font-weight: 600;\n        color: #5e768e;\n    }\n\n    .bets .content-list.fade-enter-active,\n    .bets .content-empty.fade-enter-active {\n        transition: opacity 0.5s;\n    }\n\n    .bets .content-list.fade-enter-from,\n    .bets .content-empty.fade-enter-from {\n        opacity: 0;\n    }\n\n   @media only screen and (max-width: 1100px) {\n\n       .bets {\n           width: 100%;\n       }\n\n   }\n\n   @media only screen and (max-width: 950px) {\n\n       .bets {\n           position: absolute;\n           left: 0;\n           bottom: 0;\n           margin-top: 0;\n       }\n\n       .bets .bets-nav button.nav-link {\n           padding-bottom: 8px;\n       }\n\n       .bets .bets-list {\n            height: 388px;\n            border-radius: 0;\n        }\n\n       .bets .list-head {\n            display: none;\n       }\n\n       .bets .list-content {\n            height: 100%;\n        }\n\n   }\n\n   @media only screen and (max-width: 600px) {\n\n       .bets .bets-nav button.nav-link {\n           margin-right: 15px;\n           font-size: 12px;\n       }\n\n   }\n</style>\n",
		"<template>\n    <div class=\"bets-element\">\n        <div class=\"element-game\">\n            <IconCrash v-if=\"bet.method === 'crash'\" />\n            <IconRoll v-else-if=\"bet.method === 'roll'\" />\n            <IconBlackjack v-else-if=\"bet.method === 'blackjack'\" />\n            <IconDuels v-else-if=\"bet.method === 'duels'\" />\n            <IconMines v-else-if=\"bet.method === 'mines'\" />\n            <IconTowers v-else-if=\"bet.method === 'towers'\" />\n            <IconUnbox v-else-if=\"bet.method === 'unbox'\" />\n            <IconBattles v-else-if=\"bet.method === 'battles'\" />\n            <span v-bind:class=\"{\n                'gradient-yellow': bet.method === 'crash',\n                'gradient-green': bet.method === 'roll',\n                'gradient-blue-dark': bet.method === 'blackjack',\n                'gradient-red': bet.method === 'duels',\n                'gradient-purple': bet.method === 'mines',\n                'gradient-blue': bet.method === 'towers',\n                'gradient-pink': bet.method === 'unbox',\n                'gradient-orange': bet.method === 'battles'\n            }\">{{betsGetMethod}}</span>\n        </div>\n        <div class=\"element-user\" v-bind:class=\"[\n            bet.user === null ? \n                'user-hidden' :\n                ['user-' + betsGetRank(bet.user), 'user-' + betsGetLevelColor(bet.user)]\n        ]\">\n            <div class=\"user-avatar\">\n                <AvatarImage v-bind:image=\"bet.user === null ? null : bet.user.avatar\" />\n            </div>\n            <div v-if=\"bet.user !== null\" v-html=\"bet.user.username\" class=\"user-username\"></div>\n            <div v-else>Anonymous</div>\n        </div>\n        <div class=\"element-time\">\n            <span>{{ betsGetDate[0] }},</span>{{ betsGetDate[1] }}\n        </div>\n        <div class=\"element-wager\">\n            <img src=\"@/assets/img/icons/coin.svg\" alt=\"icon\" />\n            <div class=\"wager-value\">\n                <span>{{betsFormatValue(betsGetAmount).split('.')[0]}}</span>.{{betsFormatValue(betsGetAmount).split('.')[1]}}\n            </div>\n        </div>\n        <div class=\"element-multiplier\">\n            <span v-bind:class=\"{ 'gradient-green': betsGetMultiplier > 0 }\">{{parseFloat(betsGetMultiplier).toFixed(2)}}x</span>\n        </div>\n        <div class=\"element-payout\" v-bind:class=\"{ 'payout-positive': (bet.payout / betsGetAmount) > 0 }\">\n            <img src=\"@/assets/img/icons/coin.svg\" alt=\"icon\" />\n            <div class=\"payout-value\">\n                <span>{{betsFormatValue(bet.payout).split('.')[0]}}</span>.{{betsFormatValue(bet.payout).split('.')[1]}}\n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\n    import AvatarImage from '@/components/AvatarImage';\n    import IconCrash from '@/components/icons/IconCrash';\n    import IconRoll from '@/components/icons/IconRoll';\n    import IconBlackjack from '@/components/icons/IconBlackjack';\n    import IconDuels from '@/components/icons/IconDuels';\n    import IconMines from '@/components/icons/IconMines';\n    import IconTowers from '@/components/icons/IconTowers';\n    import IconUnbox from '@/components/icons/IconUnbox';\n    import IconBattles from '@/components/icons/IconBattles';\n\n    export default {\n        name: 'BetsElement',\n        components: {\n            AvatarImage,\n            IconCrash,\n            IconRoll,\n            IconBlackjack,\n            IconDuels,\n            IconMines,\n            IconTowers,\n            IconUnbox,\n            IconBattles\n        },\n        props: [\n            'bet'\n        ],\n        methods: {\n            betsFormatValue(value) {\n                return parseFloat(Math.floor(value ) ).toFixed(2).toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',');\n            },\n            betsGetRank(user) {\n                let rank = user.rakeback;\n\n                if(user.rank !== 'user') { rank = user.rank; }\n\n                return rank;\n            },\n            betsGetLevelColor(user) {\n                let color = '';\n\n                if(user.level >= 2 && user.level < 26) { color = 'blue'; }\n                else if(user.level >= 26 && user.level < 51) { color = 'green'; }\n                else if(user.level >= 51 && user.level < 76) { color = 'orange'; }\n                else if(user.level >= 76 && user.level < 100) { color = 'red'; }\n                else if(user.level >= 100) { color = 'purple'; }\n\n                return color;\n            }\n        },\n        computed: {\n            betsGetMethod() {\n                let method = this.bet.method.charAt(0).toUpperCase() + this.bet.method.slice(1);\n\n                if(this.bet.method === 'duels') {\n                    method = 'Dice Duels';\n                }\n\n                return method;\n            },\n            betsGetDate() {\n                let date = new Date(this.bet.updatedAt).toLocaleString('en-US', { \n                    hour12: true, \n                    year: 'numeric', \n                    month: 'numeric', \n                    day: 'numeric', \n                    hour: '2-digit', \n                    minute:'2-digit' \n                });\n\n                return date.split(',');\n            },\n            betsGetAmount() {\n                let amount = this.bet.amount;\n\n                if(this.bet.method === 'blackjack') {\n                    amount = Math.floor(this.bet.amount.main + this.bet.amount.sideLeft + this.bet.amount.sideRight);\n                    if(this.bet.actions.includes('split') === true) { amount = Math.floor(amount + this.bet.amount.main); }\n                }\n\n                return amount;\n            },\n            betsGetMultiplier() {\n                let multiplier = this.bet.multiplier / 100;\n\n                if(['crash', 'roll'].includes(this.bet.method) === true) { multiplier = this.bet.payout / this.betsGetAmount; }\n\n                return multiplier;\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .bets-element {\n        width: 100%;\n        height: 52px;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        padding: 0 35px;\n        background-color: #031b2e;\n    }\n\n    .bets-element:nth-child(even) {\n        background-color: #051e33;\n    }\n\n    .bets-element .element-game {\n        width: 20%;\n        display: flex;\n        align-items: center;\n    }\n\n    .bets-element .element-game svg {\n        margin-right: 10px;\n        fill: #bbbfd0;\n    }\n\n    .bets-element .element-game span {\n        font-size: 14px;\n        font-weight: 700;\n    }\n\n    .bets-element .element-user {\n         width: 20%;\n         display: flex;\n         align-items: center;\n         font-size: 14px;\n         font-weight: 400;\n         color: #bbbfd0;\n    }\n\n    .bets-element .element-user.user-hidden {\n        font-style: italic;\n    }\n\n    .bets-element .user-avatar {\n        width: 26px;\n        height: 26px;\n        display: flex;\n        justify-content: center;\n        align-items: flex-end;\n        margin-right: 10px;\n        border-radius: 50%;\n        border: 1px solid #9e9e9e;\n        overflow: hidden;\n    }\n\n    .bets-element .element-user.user-blue .user-avatar {\n        border: 1px solid #559ee4;\n    }\n\n    .bets-element .element-user.user-green .user-avatar {\n        border: 1px solid #b8e92d;\n    }\n\n    .bets-element .element-user.user-orange .user-avatar {\n        border: 1px solid #fca311;\n    }\n\n    .bets-element .element-user.user-red .user-avatar {\n        border: 1px solid #ff4e4e;\n    }\n\n    .bets-element .element-user.user-purple .user-avatar {\n        border: 1px solid #6953f1;\n    }\n\n    .bets-element .element-user.user-partner .user-avatar {\n        border: 1px solid #eca822;\n    }\n\n    .bets-element .element-user.user-mod .user-avatar {\n        border: 1px solid #ffb703;\n    }\n\n    .bets-element .element-user.user-admin .user-avatar {\n        border: 1px solid #01e0a3;\n    }\n\n    .bets-element .user-avatar .avatar-image {\n        width: 20px;\n        height: 20px;\n    }\n\n    .bets-element .user-hidden .user-avatar .avatar-image {\n        width: 24px;\n        height: 24px;\n    }\n\n    .bets-element .user-username {\n        max-width: 100px;\n        white-space: nowrap;\n        overflow: hidden;\n        text-overflow: ellipsis;\n    }\n\n    .bets-element .element-time {\n         width: 20%;\n         display: flex;\n         align-items: center;\n         font-size: 14px;\n         font-weight: 400;\n         color: #bbbfd0;\n    }\n\n    .bets-element .element-time span {\n        margin-right: 4px;\n    }\n\n    .bets-element .element-wager,\n    .bets-element .element-payout {\n        width: 15%;\n        display: flex;\n        align-items: center;\n    }\n\n    .bets-element .element-payout {\n        justify-content: flex-end;\n    }\n\n    .bets-element .element-wager img,\n    .bets-element .element-payout img {\n        width: 18px;\n        height: 18px;\n        margin-right: 10px;\n    }\n\n    .bets-element .wager-value,\n    .bets-element .payout-value {\n        font-size: 10px;\n        font-weight: 600;\n        color: #bbbfd0;\n    }\n\n    .bets-element .wager-value span,\n    .bets-element .payout-value span {\n        font-size: 14px;\n        font-weight: 800;\n    }\n\n    .bets-element .wager-value span,\n    .bets-element .payout-positive .payout-value span {\n        color: #ffffff;\n    }\n\n    .bets-element .element-multiplier {\n        width: 10%;\n        display: flex;\n        align-items: center;\n        font-size: 14px;\n        font-weight: 400;\n        color: #bbbfd0;\n    }\n\n    .bets-element .element-multiplier.multiplier-positive {\n\n    }\n\n    @media only screen and (max-width: 950px) {\n\n        .bets-element {\n            height: auto;\n            position: relative;\n            display: grid;\n            grid-template-rows: 42px 54px;\n            grid-template-columns: 33.33% 33.33% 33.33%;\n            padding: 0;\n            background: none;\n            border-top: 1px solid #0f324e;\n        }\n\n        .bets-element:nth-child(even) {\n            background: none;\n        }\n\n        .bets-element .element-game,\n        .bets-element .element-user,\n        .bets-element .element-time {\n            width: 100%;\n            height: 100%;\n            justify-content: center;\n            background-color: rgba(15, 50, 78, 0.35);\n        }\n\n        .bets-element .element-game {\n            grid-row: 1;\n        }\n\n        .bets-element .element-user {\n            grid-column: 1;\n            grid-row: 1;\n        }\n\n        .bets-element .user-username {\n            max-width: 90px;\n        }\n\n        .bets-element .element-time {\n            grid-column: 2;\n            grid-row: 1;\n        }\n\n        .bets-element .element-wager,\n        .bets-element .element-multiplier,\n        .bets-element .element-payout {\n            width: 100%;\n            height: 100%;\n            justify-content: center;\n            background-color: rgba(4, 26, 45, 0.5);\n        }\n\n        .bets-element .element-wager {\n            grid-column: 1;\n            grid-row: 2;\n        }\n\n        .bets-element .element-multiplier {\n            position: relative;\n            grid-column: 2;\n            grid-row: 2;\n        }\n\n        .bets-element .element-multiplier::before {\n            content: '';\n            width: 1px;\n            height: 18px;\n            position: absolute;\n            top: 50%;\n            left: 0;\n            transform: translate(0, -50%);\n            background-color: #0c324e;\n        }\n\n        .bets-element .element-multiplier::after {\n            content: '';\n            width: 1px;\n            height: 18px;\n      