		"// src/assets/wingoAssets.js\r\n\r\nimport red from '@/assets/img/wingo/red.png'\r\nimport green from '@/assets/img/wingo/green.png'\r\nimport violet from '@/assets/img/wingo/violet.png'\r\n\r\nimport img0 from '@/assets/img/wingo/0.png'\r\nimport img1 from '@/assets/img/wingo/1.png'\r\nimport img2 from '@/assets/img/wingo/2.png'\r\nimport img3 from '@/assets/img/wingo/3.png'\r\nimport img4 from '@/assets/img/wingo/4.png'\r\nimport img5 from '@/assets/img/wingo/5.png'\r\nimport img6 from '@/assets/img/wingo/6.png'\r\nimport img7 from '@/assets/img/wingo/7.png'\r\nimport img8 from '@/assets/img/wingo/8.png'\r\nimport img9 from '@/assets/img/wingo/9.png'\r\n\r\nexport const wingoImages = {\r\n  red,\r\n  green,\r\n  violet,\r\n  0: img0,\r\n  1: img1,\r\n  2: img2,\r\n  3: img3,\r\n  4: img4,\r\n  5: img5,\r\n  6: img6,\r\n  7: img7,\r\n  8: img8,\r\n  9: img9\r\n}\r\n",
		"<template>\r\n  <div class=\"result-modal\" v-if=\"visible\">\r\n    <div class=\"modal-bg\" :style=\"{ backgroundImage: `url(${modalImage})` }\">\r\n      <!-- 🏆 Title -->\r\n      <div class=\"title\">\r\n        <template v-if=\"profit >= 0\">\r\n          {{ $t('gameResult.congratulations') }}\r\n        </template>\r\n        <template v-else>\r\n          {{ $t('gameResult.youLost') }} <span class=\"emoji\">😭</span>\r\n        </template>\r\n      </div>\r\n\r\n      <!-- 🎯 Result -->\r\n      <div class=\"lottery-result\">\r\n        <img :src=\"colorImage\" alt=\"color\" class=\"result-img\" />\r\n        <img :src=\"numberImage\" alt=\"number\" class=\"result-img\" />\r\n      </div>\r\n\r\n      <!-- 🧾 No bet -->\r\n      <div v-if=\"!userBet\" class=\"info\">\r\n        {{ $t('gameResult.noBetsPlaced') }}\r\n      </div>\r\n\r\n      <!-- 💰 Bet Info -->\r\n      <div v-else class=\"info\">\r\n        <!-- TOP LINE: Total Bet & Win -->\r\n        <div class=\"top-line\">\r\n          <span class=\"label\">{{ $t('gameResult.totalBet') }}:</span>\r\n          <span>{{ totalBet }} {{ getCurrencySymbol(currency) }}</span>\r\n\r\n          <span class=\"label\">| {{ $t('gameResult.totalWin') }}:</span>\r\n          <span>{{ totalWin }} {{ getCurrencySymbol(currency) }}</span>\r\n        </div>\r\n\r\n        <!-- BOTTOM LINE: Total Profit -->\r\n        <div class=\"profit-line\" :class=\"profit >= 0 ? 'profit' : 'loss'\">\r\n          {{ $t('gameResult.totalProfit') }}:\r\n          {{ profit >= 0 ? '+' : '-' }}{{ Math.abs(profit) }} {{ getCurrencySymbol(currency) }}\r\n        </div>\r\n      </div>\r\n\r\n      <!-- 🆔 Round ID -->\r\n      <div class=\"round-id\">{{ $t('gameResult.roundId') }}: {{ roundId }}</div>\r\n\r\n      <!-- ❌ Close -->\r\n      <button class=\"close-btn\" @click=\"close\">{{ $t('gameResult.close') }}</button>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup>\r\nimport { computed, watch, ref } from 'vue'\r\nimport { wingoImages } from '@/assets/wingoAssets'\r\nimport winSoundFile from '@/assets/sounds/win.mp3'\r\nimport loseSoundFile from '@/assets/sounds/lose.mp3'\r\n\r\nconst props = defineProps({\r\n  visible: Boolean,\r\n  result: Object\r\n})\r\n\r\nconst emit = defineEmits(['close'])\r\n\r\nconst totalBet = computed(() => props.result?.totalBet || 0)\r\nconst totalWin = computed(() => props.result?.totalWin || 0)\r\nconst profit = computed(() => props.result?.profit || 0)\r\nconst currency = computed(() => props.result?.currency || '')\r\nconst roundId = computed(() => props.result?.roundId || '')\r\nconst userBet = computed(() => props.result?.userBet || false)\r\nconst colorImage = computed(() => wingoImages[props.result?.color] || '')\r\nconst numberImage = computed(() => wingoImages[props.result?.number] || '')\r\n\r\nconst modalWinImage = new URL('@/assets/img/modalbg.png', import.meta.url).href\r\nconst modalLoseImage = new URL('@/assets/img/modallosebg.png', import.meta.url).href\r\nconst modalImage = computed(() => profit.value < 0 ? modalLoseImage : modalWinImage)\r\n\r\nconst getCurrencySymbol = (code) => {\r\n  const map = {\r\n    TRY: '₺', USD: '$', EUR: '€', IDR: 'Rp', INR: '₹', CNY: '¥', BRL: 'R$'\r\n  }\r\n  return map[code] || code\r\n}\r\n\r\n// 🔒 En son ses çalınan round id\r\nconst lastPlayed = ref(null)\r\n\r\n// ✅ Sadece görünür OLDUĞUNDA ve roundId DEĞİŞTİĞİNDE ses çalsın\r\nwatch(\r\n  () => props.visible,\r\n  (visible) => {\r\n    const round = props.result?.roundId\r\n    if (visible && round && round !== lastPlayed.value) {\r\n      lastPlayed.value = round\r\n\r\n      const sound = new Audio(profit.value >= 0 ? winSoundFile : loseSoundFile)\r\n      sound.play().catch(e => console.warn('Ses hatası:', e))\r\n\r\n      setTimeout(() => {\r\n        emit('close')\r\n        lastPlayed.value = null // round bittiğinde tekrar izin ver\r\n      }, 3000)\r\n    }\r\n  }\r\n)\r\n</script>\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n\r\n<style scoped>\r\n.result-modal {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  width: 100vw;\r\n  height: 100vh;\r\n  background: rgba(0,0,0,0.6);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  z-index: 9999;\r\n}\r\n\r\n.modal-bg {\r\n  width: 300px;\r\n  height: 460px;\r\n  background-size: cover;\r\n  background-position: center;\r\n  position: relative;\r\n  padding: 30px 20px;\r\n  text-align: center;\r\n  color: #000;\r\n  font-weight: bold;\r\n  font-family: 'Poppins', sans-serif;\r\n}\r\n\r\n.amount-line {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  justify-content: center;\r\n  font-weight: bold;\r\n  font-size: 10px;\r\n}\r\n\r\n.amount-line .label {\r\n  opacity: 0.7;\r\n}\r\n.title {\r\n  font-size: 20px;\r\n  font-weight: bold;\r\n  margin-bottom: 12px;\r\n      margin-top: 100px;\r\n}\r\n\r\n.lottery-result {\r\n  display: flex;\r\n  flex-direction: row;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 10px;\r\n  margin-bottom: 16px;\r\n  margin-top: 40px;\r\n}\r\n\r\n.result-img {\r\n  width: 42px;\r\n  height: auto;\r\n}\r\n\r\n.info {\r\n  font-size: 16px;\r\n  margin-bottom: 10px;\r\n  margin-top: 50px;\r\n}\r\n\r\n.amount-line {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 6px;\r\n}\r\n\r\n.coin-icon {\r\n  width: 20px;\r\n  height: 20px;\r\n}\r\n\r\n.profit {\r\n  color: #00ff94;\r\n  font-weight: bold;\r\n}\r\n\r\n.loss {\r\n  color: #ff5555;\r\n  font-weight: bold;\r\n}\r\n\r\n.round-id {\r\n  font-size: 12px;\r\n  margin-top: 32px;\r\n  color: #000;\r\n}\r\n\r\n.close-btn {\r\n  margin-top: 12px;\r\n  padding: 6px 12px;\r\n  background: var(--button1);\r\n  color: #000;\r\n  font-weight: bold;\r\n  border: none;\r\n  border-radius: 6px;\r\n  cursor: pointer;\r\n      margin-top: 70px;\r\n}\r\n\r\n.top-line {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  flex-wrap: wrap;\r\n  gap: 6px;\r\n  font-size: 12px;\r\n  margin-bottom: 8px;\r\n}\r\n\r\n.profit-line {\r\n  font-size: 18px;\r\n  font-weight: bold;\r\n  text-align: center;\r\n  margin-top: 15px;\r\n}\r\n\r\n.emoji {\r\n  font-size: 28px;\r\n  margin-left: 6px;\r\n  display: inline-block;\r\n  transform: translateY(3px); /* biraz aşağı hizalama */\r\n}\r\n</style>\r\n",
		"import script from \"./ModalWingoResult.vue?vue&type=script&setup=true&lang=js\"\nexport * from \"./ModalWingoResult.vue?vue&type=script&setup=true&lang=js\"\n\nimport \"./ModalWingoResult.vue?vue&type=style&index=0&id=50da7628&scoped=true&lang=css\"\n\nimport exportComponent from \"../../../node_modules/vue-loader/dist/exportHelper.js\"\nconst __exports__ = /*#__PURE__*/exportComponent(script, [['__scopeId',\"data-v-50da7628\"]])\n\nexport default __exports__",
		"<template>\r\n<div class=\"flip-clock\">\r\n    <template v-for=\"data in timeData\" :key=\"data.label\">\r\n        <span class=\"flip-clock__piece\" :id=\"data.elementId\" v-show=\"data.show\">\r\n            <div v-if=\"flipAnimation\">\r\n                <span class=\"flip-clock__card flip-card\" :style=\"countdownSize ? `font-size:${countdownSize}` : ''\">\r\n                    <b class=\"flip-card__top\">{{twoDigits(data.current)}}</b>\r\n                    <b class=\"flip-card__bottom\" :data-value=\"twoDigits(data.current)\"></b>\r\n                    <b class=\"flip-card__back\" :data-value=\"twoDigits(data.previous)\"></b>\r\n                    <b class=\"flip-card__back-bottom\" :data-value=\"twoDigits(data.previous)\"></b>\r\n                </span>\r\n            </div>\r\n            <div v-else>\r\n                <span class=\"no-animation__card\">{{twoDigits(data.current)}}</span>\r\n            </div>\r\n            <span v-if=\"showLabels\" class=\"flip-clock__slot\" :style=\"labelSize ? `font-size:${labelSize}` : ''\">{{ data.label }}</span>\r\n        </span>\r\n    </template>\r\n</div>\r\n</template>\r\n\r\n<script>\r\nimport {\r\n    computed,\r\n    onBeforeMount,\r\n    onMounted,\r\n    onUnmounted,\r\n    toRefs,\r\n    ref,\r\n    watch\r\n} from 'vue'\r\n\r\nimport moment from \"moment\";\r\nconst fmt = \"YYYY-MM-DD HH:mm:ss\";\r\nimport { v4 as uuidv4 } from 'uuid';\r\n\r\n\r\nexport default {\r\n    name: 'vue3-flip-countdown',\r\n    emits: [\"timeElapsed\"],\r\n    setup(props, {\r\n        emit\r\n    }) {\r\n        const uuid = uuidv4();\r\n        const {\r\n            deadline,\r\n            stop,\r\n            showDays,\r\n            showHours,\r\n            showMinutes,\r\n            showSeconds,\r\n            labels,\r\n            deadlineDate,\r\n            deadlineISO\r\n        } = toRefs(props);\r\n\r\n        let now = ref(Math.trunc(new Date().getTime() / 1000));\r\n        let date = ref(null);\r\n        let interval = ref(null);\r\n        let diff = ref(0);\r\n        let show = ref(false);\r\n        let timeData = ref([{\r\n                current: 0,\r\n                previous: 0,\r\n                label: labels.value.days,\r\n                elementId: 'flip-card-days-' + uuid,\r\n                show: showDays.value,\r\n            },\r\n            {\r\n                current: 0,\r\n                previous: 0,\r\n                label: labels.value.hours,\r\n                elementId: 'flip-card-hours-' + uuid,\r\n                show: showHours.value,\r\n            },\r\n            {\r\n                current: 0,\r\n                previous: 0,\r\n                label: labels.value.minutes,\r\n                elementId: 'flip-card-minutes-' + uuid,\r\n                show: showMinutes.value,\r\n            },\r\n            {\r\n                current: 0,\r\n                previous: 0,\r\n                label: labels.value.seconds,\r\n                elementId: 'flip-card-seconds-' + uuid,\r\n                show: showSeconds.value,\r\n            },\r\n        ]);\r\n\r\n        const updateAllCards = () => {\r\n            updateTime(0, days);\r\n            updateTime(1, hours);\r\n            updateTime(2, minutes);\r\n            updateTime(3, seconds);\r\n        }\r\n\r\n        const twoDigits = (value) => {\r\n            if (value != undefined) {\r\n                if (value.toString().length <= 1) {\r\n                    return '0' + value.toString();\r\n                }\r\n                return value.toString();\r\n            } else {\r\n                return '00';\r\n            }\r\n        }\r\n\r\n        const updateTime = (idx, newValue) => {\r\n            if (idx >= timeData.value.length || newValue === undefined) {\r\n                return;\r\n            }\r\n\r\n            // if (window['requestAnimationFrame']) {\r\n            //     frame = requestAnimationFrame(updateTime.bind(this));\r\n            // }\r\n\r\n            const d = timeData.value[idx];\r\n            const val = newValue.value < 0 ? 0 : newValue.value;\r\n            const el = document.querySelector(`#${d.elementId}`);\r\n\r\n            if (val !== d.current) {\r\n                d.previous = d.current;\r\n                d.current = val;\r\n\r\n                if (el) {\r\n                    el.classList.remove('flip');\r\n                    void el.offsetWidth;\r\n                    el.classList.add('flip');\r\n                }\r\n\r\n                if (idx === 0) {\r\n                    const els = el.querySelectorAll('span b');\r\n                    if (els) {\r\n                        for (let e of els) {\r\n                            const cls = e.classList[0];\r\n                            if (newValue.value / 1000 >= 1) {\r\n                                if (!cls.includes('-4digits')) {\r\n                                    const newCls = cls + '-4digits';\r\n                                    e.classList.add(newCls);\r\n                                    e.classList.remove(cls);\r\n                                }\r\n                            } else {\r\n                                if (cls.includes('-4digits')) {\r\n                                    const newCls = cls.replace('-4digits', '');\r\n                                    e.classList.add(newCls);\r\n                                    e.classList.remove(cls);\r\n                                }\r\n                            }\r\n                        }\r\n                    } else {\r\n                        //\r\n                    }\r\n                }\r\n            }\r\n        }\r\n\r\n        watch(deadline, (newVal) => {\r\n            const endTime = newVal;\r\n            date.value = Math.trunc(Date.parse(endTime.replace(/-/g, '/')) / 1000);\r\n            if (!date.value) {\r\n                throw new Error(\"Invalid props value, correct the 'deadline'\");\r\n            }\r\n        })\r\