    // if (window['cancelAnimationFrame']) {\r\n            //     cancelAnimationFrame(frame);\r\n            // }\r\n            clearInterval(interval.value);\r\n        });\r\n\r\n        return {\r\n            now,\r\n            date,\r\n            interval,\r\n            diff,\r\n            show,\r\n            timeData,\r\n            twoDigits,\r\n            emit,\r\n        }\r\n    },\r\n    props: {\r\n        deadline: {\r\n            type: String,\r\n            required: false,\r\n            default: moment()\r\n                .add(32, \"d\")\r\n                .add(10, \"s\")\r\n                .format(fmt),\r\n        },\r\n        deadlineISO: {\r\n            type: String,\r\n            required: false,\r\n        },\r\n        deadlineDate: {\r\n            type: Date,\r\n            required: false,\r\n        },\r\n        countdownSize: {\r\n            type: String,\r\n            required: false,\r\n            // default:\"2.2rem\"\r\n        },\r\n\r\n        labelSize: {\r\n            type: String,\r\n            required: false,\r\n            // default:\"2.2rem\"\r\n        },\r\n        stop: {\r\n            type: Boolean,\r\n            required: false,\r\n        },\r\n        flipAnimation: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: true,\r\n        },\r\n        showDays: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: true,\r\n        },\r\n        showHours: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: true,\r\n        },\r\n        showMinutes: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: true,\r\n        },\r\n        showSeconds: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: true,\r\n        },\r\n        showLabels: {\r\n            type: Boolean,\r\n            required: false,\r\n            default: tr