r;\r\n  gap: 0.85rem;\r\n \r\n  position: relative;\r\n}\r\n\r\n.number-wrapper {\r\n  position: relative;\r\n  width: calc(20% - 0.75rem);\r\n  height: 70px;\r\n  box-sizing: border-box;\r\n}\r\n\r\n.number-box {\r\n      background:var(--background);\r\n  border-radius: 12px;\r\n  padding: 1px;\r\n  height: 70px;\r\n  text-align: center;\r\n  cursor: pointer;\r\n  \r\n  transition: all 0.2s ease;\r\n  position: relative;\r\n  box-sizing: border-box;\r\n  overflow: visible;\r\n  z-index: 1;\r\n}\r\n\r\n.number-box::before {\r\n       content: '';\r\n    position: absolute;\r\n    inset: 0;\r\n    border-radius: 12px;\r\n    padding: 1px;\r\n    background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, #e0d601 100%);\r\n    -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);\r\n    -webkit-mask-composite: xor;\r\n    mask-composite: exclude;\r\n    z-index: -1;\r\n}\r\n\r\n.bet-amount {\r\n  position: absolute;\r\n  top: -10px;\r\n  right: -10px;\r\n  background: var(--background);\r\n  color: #fff;\r\n  padding: 3px 6px;\r\n  font-size: 11px;\r\n  font-weight: 600;\r\n  border-radius: 6px;\r\n  z-index: 3;\r\n}\r\n\r\n\r\n\r\n.number {\r\n  font-size: 18px;\r\n  font-weight: bold;\r\n  color: #fff;\r\n  position: relative;\r\n  z-index: 2;\r\n  background: var(--background);\r\n  border-radius: 8px;\r\n  padding: 4px 8px;\r\n  margin: 4px auto 0;\r\n  display: inline-block;\r\n}\r\n\r\n.number-img {\r\n  position: absolute;\r\n  top: 50%;\r\n  left: 50%;\r\n  width: 32px;\r\n  height: auto;\r\n  transform: translate(-50%, -50%);\r\n  z-index: 2;\r\n  pointer-events: none;\r\n}\r\n\r\n.chip-layer {\r\n  position: absolute;\r\n  width: 100%;\r\n  height: 100%;\r\n  top: 0;\r\n  left: 0;\r\n  pointer-events: none;\r\n  z-index: 1;\r\n}\r\n\r\n.chip {\r\n  position: absolute;\r\n  z-index: 2;\r\n}\r\n\r\n.flying-chip {\r\n  position: fixed;\r\n  top: 0;\r\n  left: 0;\r\n  width: 26px;\r\n  height: 26px;\r\n  background-image: url('@/assets/im