		"<template>\r\n  <div class=\"countdown-bar-wrapper\">\r\n    <div v-if=\"timeLeft > 0\" class=\"soft-blink\"> {{ $t('wingo.Place your bets') }}</div>\r\n    <div class=\"progress-container\">\r\n      <div class=\"progress-bar\" :style=\"{ width: animatedWidth + '%' }\"></div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref, onMounted, onUnmounted } from 'vue'\r\nimport { getCurrentInstance } from 'vue'\r\nimport moment from 'moment'\r\n\r\nconst { proxy } = getCurrentInstance()\r\nconst socket = proxy.$socket\r\n\r\nconst timeLeft = ref(0)\r\nconst maxTime = ref(30) // varsayılan 30 saniye\r\n\r\n// Bar genişliği (0–100)\r\nconst animatedWidth = ref(100)\r\n\r\nlet startTime = performance.now()\r\nlet animationFrame\r\n\r\n// Animasyon döngüsü\r\nconst animate = (now) => {\r\n  const elapsed = (now - startTime) / 1000 // saniye\r\n  const remaining = Math.max(timeLeft.value - elapsed, 0)\r\n  animatedWidth.value = Math.max((remaining / maxTime.value) * 100, 0)\r\n\r\n  if (remaining > 0) {\r\n    animationFrame = requestAnimationFrame(animate)\r\n  }\r\n}\r\n\r\n// Yeni round başladığında socket'ten dinle\r\nonMounted(() => {\r\n  socket.on('wingo:round:start', ({ endsAt, startedAt }) => {\r\n    const now = moment()\r\n    const end = moment(endsAt)\r\n    const start = moment(startedAt)\r\n\r\n    timeLeft.value = end.diff(now, 'seconds', true) // float saniye\r\n    maxTime.value = end.diff(start, 'seconds', true)\r\n\r\n    startTime = performance.now()\r\n    if (animationFrame) cancelAnimationFrame(animationFrame)\r\n    animationFrame = requestAnimationFrame(animate)\r\n  })\r\n\r\n  // Eğer sayfa yüklenirken event kaçtıysa, elle tetiklemek istersen burada emit edebilirsin (opsiyonel)\r\n})\r\n\r\nonUnmounted(() => {\r\n  if (animationFrame) cancelAnimationFrame(animationFrame)\r\n})\r\n</script>\r\n\r\n<style scoped>\r\n.countdown-bar-wrapper {\r\n  text-align: center;\r\n  user-select: none;\r\n}\r\n\r\n.soft-blink {\r\n  