		"<template>\r\n  <div class=\"history-bar\">\r\n    <div class=\"history-list\">\r\n      <div\r\n        v-for=\"(item, i) in history\"\r\n        :key=\"i\"\r\n        class=\"history-item\"\r\n        :class=\"getColorClass(item)\"\r\n      >\r\n        <img\r\n          :src=\"getNumberImage(item)\"\r\n          :alt=\"item\"\r\n          class=\"history-img\"\r\n        />\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref, onMounted, onUnmounted } from 'vue'\r\nimport { io } from 'socket.io-client'\r\n\r\n// 📦 Görseller\r\nimport img0 from '@/assets/img/wingo/0.png'\r\nimport img1 from '@/assets/img/wingo/1.png'\r\nimport img2 from '@/assets/img/wingo/2.png'\r\nimport img3 from '@/assets/img/wingo/3.png'\r\nimport img4 from '@/assets/img/wingo/4.png'\r\nimport img5 from '@/assets/img/wingo/5.png'\r\nimport img6 from '@/assets/img/wingo/6.png'\r\nimport img7 from '@/assets/img/wingo/7.png'\r\nimport img8 from '@/assets/img/wingo/8.png'\r\nimport img9 from '@/assets/img/wingo/9.png'\r\n\r\n// 📡 Socket bağlantısı\r\nconst socketURL = process.env.VUE_APP_SOCKET_URL || 'https://apievrymatrix5d84k321.com'\r\nconst socket = io(socketURL, {\r\n  transports: ['websocket'],\r\n  withCredentials: true\r\n})\r\n\r\n// 📜 Oyun geçmişi\r\nconst history = ref([])\r\n\r\n// 🧩 Sayı-görsel eşlemesi\r\nconst numberImages = {\r\n  0: img0, 1: img1, 2: img2, 3: img3, 4: img4,\r\n  5: img5, 6: img6, 7: img7, 8: img8, 9: img9\r\n}\r\n\r\n// 🔧 Güvenli görsel alma\r\nconst getNumberImage = (num) => {\r\n  const parsed = parseInt(num, 10)\r\n  return numberImages.hasOwnProperty(parsed) ? numberImages[parsed] : ''\r\n}\r\n\r\n// 🎨 Renk sınıfı\r\nconst getColorClass = (val) => {\r\n  const parsed = parseInt(val, 10)\r\n  if ([0, 5, 8].includes(parsed)) return 'violet'\r\n  return parsed % 2 === 0 ? 'green' : 'red'\r\n}\r\n\r\nonMounted(() => {\r\n  socket.emit('wingo:history:request')\r\n\r\n  socket.on('wingo:history:response', (data) => {\r\n    history.value = data\r\n      .map(n => parseInt(n, 10))\r\n      .filter(n => !isNaN(n) && n >= 0 && n <= 9)\r\n  })\r\n\r\n  socket.on('wingo:history:error', (err) => {\r\n    console.error('History error:', err)\r\n  })\r\n\r\n  socket.on('wingo:round:result', ({ result }) => {\r\n    const number = parseInt(result.number, 10)\r\n    if (!isNaN(number) && number >= 0 && number <= 9) {\r\n      if (history.value.length >= 20) history.value.pop()\r\n      history.value.unshift(number)\r\n    } else {\r\n      console.warn('❌ Geçersiz sonuç numarası:', result.number)\r\n    }\r\n  })\r\n})\r\n\r\nonUnmounted(() => {\r\n  socket.off('wingo:history:response')\r\n  socket.off('wingo:history:error')\r\n  socket.off('wingo:round:result')\r\n})\r\n</script>\r\n\r\n\r\n\r\n<style scoped>\r\n.history-bar::-webkit-scrollbar {\r\n  display: none;\r\n}\r\n.history-bar {\r\n  -ms-overflow-style: none;  /* IE/Edge */\r\n  scrollbar-width: none;     /* Firefox */\r\n}\r\n.history-bar {\r\n  width: 100%;\r\n  overflow-x: auto;\r\n  white-space: nowrap;\r\n}\r\n\r\n.history-list {\r\n  display: flex;\r\n  flex-wrap: nowrap; /* ❗ ALT SATIRA GEÇMESİN */\r\n  gap: 0.4rem;\r\n  padding: 4px 0;\r\n}\r\n\r\n.history-item {\r\n  flex-shrink: 0; /* ❗ Boyut küçülmesin */\r\n  width: 33px;\r\n  height: 33px;\r\n  display: grid;\r\n  place-items: center;\r\n  overflow: hidden;\r\n  border-radius: 4px;\r\n}\r\n\r\n.history-img {\r\n  width: 33px;\r\n  height: auto;\r\n  pointer-events: none;\r\n  user-select: none;\r\n}\r\n\r\n</style>\r\n",
