nesGame.revealed.length ? 1 : this.minesFactorialNumber(25 - this.minesGame.minesCount) / (this.minesFactorialNumber(this.minesGame.revealed.length) * this.minesFactorialNumber((25 - this.minesGame.minesCount) - this.minesGame.revealed.length));\n\n                    multiplier = 0.95 * (first / second);\n                    multiplier = multiplier < 1 ? 1.01 : multiplier;\n                    multiplier = Math.round(multiplier * 100) / 100;\n                }\n\n                return parseFloat(this.minesGame.amount * multiplier).toFixed(2);\n\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .mines-controls {\n        width: 270px;\n        display: flex;\n        flex-direction: column;\n        justify-content: space-between;\n        padding: 20px 15px;\n        border-radius: 15px;\n        background: var(--background);\n        border: 4px solid rgb(9, 12, 29);\n    }\n\n    .mines-controls .controls-top {\n        width: 100%;\n    }\n\n    .mines-controls .top-amount {\n        width: 100%;\n        height: 50px;\n        position: relative;\n        padding: 1px;\n    }\n\n     \n\n    .mines-controls .top-amount input {\n        width: 100%;\n        height: 100%;\n        padding: 0 100px 0 23px;\n        font-size: 12px;\n        font-weight: 600;\n        font-family: \"Montserrat\", Arial, \"Segoe UI\", Helvetica, sans-serif;\n        color: #ffffff;\n        background: var(--background2);\n         border-radius: 12px;\n         z-index: 1;\n    }\n\n    .mines-controls .top-amount input::placeholder {\n        color: #fff;\n    }\n\n    .mines-controls .top-amount img {\n        width: 19px;\n        height: 19px;\n        position: absolute;\n        top: 50%;\n        left: 15px;\n        transform: translate(0, -50%);\n    }\n\n    .mines-controls .amount-buttons {\n        position: absolute;\n        top: 50%;\n        right: 15px;\n        transform: translate(0, -50%);\n    }\n\n    .mines-controls .amount-buttons button 