		"<template>\n    <div class=\"towers\">\n        <div class=\"towers-container\">\n            <div class=\"container-game\" v-bind:class=\"['game-' + towersRisk]\">\n                <TowersRow v-for=\"row in 8\" v-bind:key=\"row\" v-bind:row=\"row - 1\" />\n            </div>\n            <TowersControls />\n        </div>\n        \n        <Bets />\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import Bets from '@/components/bets/Bets';\n    import TowersRow from '@/components/towers/TowersRow';\n    import TowersControls from '@/components/towers/TowersControls';\n\n    export default {\n        name: 'Towers',\n        metaInfo: {\n            title: 'Towers - https://velobet280.com'\n        },\n        components: {\n            Bets,\n            TowersRow,\n            TowersControls\n        },\n        methods: {\n            ...mapActions([\n                'socketConnectTowers', \n                'socketDisconnectTowers'\n            ])\n        },\n        computed: {\n            ...mapGetters([\n                'towersRisk'\n            ]),\n        },\n        created() {\n            this.socketConnectTowers();\n        },\n        beforeRouteLeave(to, from, next) {\n            this.socketDisconnectTowers();\n            next();\n        }\n    }\n</script>\n\n<style scoped>\n    .towers {\n        width: 100%;\n        position: relative;\n        display: flex;\n        flex-direction: column;\n        align-items: center;\n        padding: 45px 10px;\n    }\n\n    .towers .towers-container {\n        width: 525px;\n        padding: 20px 0;\n        border-radius: 25px;\n        background: var(--background);\n        \n        box-shadow: 0px 4px 10px rgba(7, 26, 41, 0.25);\n        position: relative;\n        z-index: 1;\n    }\n\n  \n\n    \n\n    .towers .container-game {\n        width: 100%;\n        display: flex;\n        flex-direction: column-reverse;\n    }\n\n    @media only screen an