		"<template>\r\n  <div class=\"page\">\r\n    <div class=\"content\">\r\n      <!-- Sol kısım: Header + Chart -->\r\n      <div class=\"left-side\">\r\n        <TurboHeader\r\n          v-model:symbol=\"symbol\"\r\n          :symbol-options=\"symbolOptions\"\r\n          v-model:interval=\"interval\"\r\n        />\r\n        <TurboTradeChart\r\n          :symbol=\"symbol\"\r\n          :direction=\"direction\"\r\n          :history-seconds=\"historySeconds\"\r\n          :end-time-sec=\"endTimeSec\"\r\n          :entry-price=\"externalEntryPrice\"\r\n          :interval=\"interval\"\r\n          price-scale=\"normal\"\r\n          @entry-fixed=\"onEntryFixed\"\r\n          @price-update=\"onPriceUpdate\" \r\n        />\r\n      </div>\r\n\r\n      <!-- Sağ kısım: Bet Input -->\r\n      <div class=\"bet-panel\">\r\n        <!-- ✅ Burada user ve socket gönderiyoruz -->\r\n        <BetInput :symbol=\"symbol\" :user=\"authUser\" :socket=\"socket\" />\r\n      </div>\r\n      \r\n    </div>\r\n    <FuturesPositions />\r\n  </div>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref, computed } from 'vue'\r\nimport { useStore } from 'vuex'\r\nimport { io } from 'socket.io-client'\r\n\r\nimport TurboTradeChart from '@/components/turbo/TurboTradeChart.vue'\r\nimport TurboHeader from '@/components/turbo/TurboHeader.vue'\r\nimport BetInput from '@/components/turbo/BetInput.vue'\r\nimport FuturesPositions from '@/components/turbo/FuturesPositions.vue'\r\n\r\n\r\nconst store = useStore()\r\nconst authUser = computed(() => store.getters.authUser.user)\r\n\r\n// ✅ socket bağlantısı\r\nconst socket = io(process.env.VUE_APP_SOCKET_URL, {\r\n  transports: ['websocket'],\r\n  withCredentials: true\r\n})\r\n\r\nconst symbol = ref('DOGEUSDT')\r\nconst symbolOptions = ref([\r\n  'BTCUSDT','ETHUSDT','USDCUSDT','SOLUSDT','XRPUSDT','DOGEUSDT','LINKUSDT','BNBUSDT',\r\n  'ADAUSDT','SUIUSDT','AVAXUSDT','LTCUSDT','PEPEUSDT','UNIUSDT','TRXUSDT','DOTUSDT','WLDUSDT'\r\n])\r\n\r\nconst currentPrice = ref(null)\r\n\r\nfunction onPriceUpdate(price) {\r\n  currentPrice.value = price\r\n}\r\n\r\nconst interval = ref('tick')\r\nconst durationSec = ref(30)\r\nconst direction = ref('UP')\r\nconst endTimeSec = ref(null)\r\nconst externalEntryPrice = ref(null)\r\nconst historySeconds = ref(90)\r\n\r\nfunction onEntryFixed(p) {\r\n  console.log('Entry fixed:', p)\r\n}\r\n</script>\r\n\r\n\r\n<style scoped>\r\n.page {\r\n  \r\n \r\n  padding: 0 10px;\r\n}\r\n\r\n/* PC: sol (header+chart) sağ (bet input) */\r\n.content {\r\n  display: flex;\r\n  gap: 20px;\r\n}\r\n\r\n/* Sol taraf dikey düzen */\r\n.left-side {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n}\r\n\r\n/* Sağ panel */\r\n.bet-panel {\r\n  width: 300px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* Mobil: alt alta */\r\n@media (max-width: 768px) {\r\n  .content {\r\n    flex-direction: column;\r\n  }\r\n  .bet-panel {\r\n    width: 100%;\r\n  }\r\n}\r\n</style>\r\n",
