rrentPrice = ref(null)\r\n\r\nfunction onPriceUpdate(price) {\r\n  currentPrice.value = price\r\n}\r\n\r\nconst interval = ref('tick')\r\nconst durationSec = ref(30)\r\nconst direction = ref('UP')\r\nconst endTimeSec = ref(null)\r\nconst externalEntryPrice = ref(null)\r\nconst historySeconds = ref(90)\r\n\r\nfunction onEntryFixed(p) {\r\n  console.log('Entry fixed:', p)\r\n}\r\n</script>\r\n\r\n\r\n<style scoped>\r\n.page {\r\n  \r\n \r\n  padding: 0 10px;\r\n}\r\n\r\n/* PC: sol (header+chart) sağ (bet input) */\r\n.content {\r\n  display: flex;\r\n  gap: 20px;\r\n}\r\n\r\n/* Sol taraf dikey düzen */\r\n.left-side {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n  min-height: 300px; /* ✅ chart’ın minimum yüksekliği */\r\n}\r\n\r\n.turbo-trade-chart {\r\n  flex: 1;\r\n  min-height: 250px;\r\n  max-height: 500px;\r\n}\r\n\r\n\r\n/* Sağ panel */\r\n.bet-panel {\r\n  width: 300px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* Mobil: alt alta */\r\n@media (max-width: 768px) {\r\n  .content {\r\n    flex-direction: column;\r\n  }\r\n  .bet-panel {\r\n    width: 100%;\r\n  }\r\n}\r\n</style>\r\n",
