		" \r\n<script>\r\nimport CategoryBanner from '@/components/banner/BannerCategory.vue';\r\nimport HomeDepositMethods from '@/components/home/HomeDepositMethods';\r\nimport CategorySection from '@/components/home/CategorySection.vue';\r\nimport Search from '@/components/Search.vue';\r\nimport axios from 'axios';\r\nimport { mapGetters } from 'vuex';\r\n\r\nexport default {\r\n  name: 'GameCategory',\r\n  metaInfo: {\r\n    title: 'RivoBIT: The Innovative Crypto Gambling Site'\r\n  },\r\n  components: {\r\n    CategoryBanner,\r\n    HomeDepositMethods,\r\n    CategorySection,\r\n    Search\r\n  },\r\n  data() {\r\n    return {\r\n      games: [],\r\n      gamesToShow: 18,\r\n      totalGames: 0,\r\n      offset: 0,\r\n      providers: [],\r\n      selectedProvider: null,\r\n      isDropdownOpen: false,\r\n      favorites: JSON.parse(localStorage.getItem('favorites')) || [],\r\n      categoryName: this.$route.params.slug || 'Games'\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser']),\r\n    sortedGames() {\r\n      const favs = this.games.filter(g => this.favorites.includes(g._id));\r\n      const rest = this.games.filter(g => !this.favorites.includes(g._id));\r\n      return [...favs, ...rest];\r\n    },\r\n    favoriteGames() {\r\n      return this.games.filter(game => this.favorites.includes(game._id));\r\n    },\r\n    favoriteCategoryWithUniqueKeys() {\r\n      return {\r\n        slug: 'favorites',\r\n        name: 'Favoriler',\r\n        img: '/img/fav.png',\r\n        total_games: this.favoriteGames.length,\r\n        games: this.favoriteGames.map(g => ({ ...g, _id: `fav-${g._id}` }))\r\n      };\r\n    }\r\n  },\r\n  methods: {\r\n    async fetchProviders() {\r\n      try {\r\n        const category = this.categoryName.toLowerCase();\r\n        const response = await axios.get(`/public/providers/category/${category}`);\r\n        if (response.data.success) {\r\n          this.providers = response.data.data;\r\n        } else {\r\n          console.error('Failed to fetch providers:', response.data.message);\r\n        }\r\n      } catch (error) {\r\n        console.error('Error fetching providers:', error);\r\n      }\r\n    },\r\n\r\n    async fetchGames(reset = false) {\r\n      try {\r\n        const category = this.categoryName.toLowerCase();\r\n        const params = {\r\n          limit: this.gamesToShow,\r\n          offset: this.offset,\r\n          provider_code: this.selectedProvider?.provider_code || null\r\n        };\r\n\r\n        const response = await axios.get(`/public/games/category/${category}`, { params });\r\n\r\n        const responseData = response.data;\r\n        const gamesArray = Array.isArray(responseData)\r\n          ? responseData\r\n          : responseData.data || [];\r\n\r\n        this.totalGames = responseData.total || gamesArray.length;\r\n\r\n        const newGames = gamesArray.filter(\r\n          (newGame) => !this.games.some((existingGame) => existingGame._id === newGame._id)\r\n        );\r\n\r\n        if (reset) {\r\n          this.games = newGames;\r\n        } else {\r\n          this.games.push(...newGames);\r\n        }\r\n      } catch (error) {\r\n        console.error('Failed to fetch games:', error?.response?.data || error.message);\r\n      }\r\n    },\r\n\r\n    toggleDropdown() {\r\n      this.isDropdownOpen = !this.isDropdownOpen;\r\n    },\r\n\r\n    selectProvider(provider) {\r\n      if (this.selectedProvider?.provider_code === provider.provider_code) {\r\n        this.selectedProvider = null;\r\n      } else {\r\n        this.selectedProvider = provider;\r\n      }\r\n\r\n      this.offset = 0;\r\n      this.games = [];\r\n      this.fetchGames(true);\r\n      this.isDropdownOpen = false;\r\n    },\r\n\r\n    toggleFavorite(gameId) {\r\n      const index = this.favorites.indexOf(gameId);\r\n      if (index === -1) {\r\n        this.favorites.push(gameId);\r\n      } else {\r\n        this.favorites.splice(index, 1);\r\n      }\r\n      localStorage.setItem('favorites', JSON.stringify(this.favorites));\r\n    },\r\n\r\n    launchGame(game) {\r\n      this.$router.push({ name: 'GameStart', params: { id: game.game_code } });\r\n    },\r\n\r\n    loadMoreGames() {\r\n      if (this.games.length < this.totalGames) {\r\n        this.offset += this.gamesToShow;\r\n        this.fetchGames();\r\n      }\r\n    }\r\n  },\r\n  watch: {\r\n    '$route.params.slug': {\r\n      handler(newSlug) {\r\n        this.categoryName = newSlug;\r\n        this.offset = 0;\r\n        this.games = [];\r\n        this.fetchGames(true);\r\n        this.fetchProviders();\r\n      },\r\n      immediate: true\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n\r\n <template>\r\n  <div class=\"home\">\r\n    <!-- Banner -->\r\n    <div class=\"home-banner\">\r\n      <CategoryBanner :slug=\"categoryName\" />\r\n    </div>\r\n\r\n    <!-- Arama + Filter / Provider -->\r\n    <div class=\"search-provider-row\">\r\n      <!-- Mobilde yan yana -->\r\n      <div class=\"mobile-filter-provider\">\r\n        <div class=\"filter-dropdown\">\r\n          <img src=\"@/assets/img/filter.svg\" alt=\"Filter Icon\" class=\"filter-icon\" />\r\n          <span class=\"filter-text\">{{ $t('category.filter') }}</span>\r\n        </div>\r\n\r\n        <div class=\"provider-dropdown-container\">\r\n          <div class=\"dropdown\">\r\n            <button class=\"dropdown-toggle\" @click=\"toggleDropdown\">\r\n              <img src=\"@/assets/img/provider.svg\" alt=\"Provider Icon\" class=\"dropdown-icon\" />\r\n              <span class=\"dropdown-text\">\r\n                {{ selectedProvider ? selectedProvider.provider_code : $t('category.select') }}\r\n              </span>\r\n            </button>\r\n            <div v-if=\"isDropdownOpen\" class=\"dropdown-menu\">\r\n              <div\r\n                v-for=\"(provider, index) in providers\"\r\n                :key=\"index\"\r\n                class=\"dropdown-item\"\r\n                @click=\"selectProvider(provider)\"\r\n              >\r\n                <input\r\n                  type=\"checkbox\"\r\n                  :checked=\"provider.provider_code === selectedProvider?.provider_code\"\r\n                />\r\n                <span>{{ provider.provider_code }}</span>\r\n                <span class=\"provider-count\">({{ provider.count }})</span>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Search -->\r\n      <div class=\"search-container\">\r\n        <Search />\r\n      </div>\r\n\r\n      <!-- PC’de yan yana -->\r\n      <div class=\"desktop-filter-provider\">\r\n        <div class=\"filter-dropdown\">\r\n          <img src=\"@/assets/img/filter.svg\" alt=\"Filter Icon\" class=\"filter-icon\" />\r\n          <span class=\"filter-text\">{{ $t('category.filter') }}</span>\r\n        </div>\r\n\r\n        <div class=\"provider-dropdown-container\">\r\n          <div class=\"dropdown\">\r\n            <button class=\"dropdown-toggle\" @click=\"toggleDropdown\">\r\n              <img src=\"@/assets/img/provider.svg\" alt=\"Provider Icon\" class=\"dropdown-icon\" />\r\n              <span class=\"dropdown-text\">\r\n  {{ selectedProvider ? selectedProvider.provider_code : $t('category.select') }}\r\n</span>\r\n\r\n            </button>\r\n            <div v-if=\"isDropdownOpen\" class=\"dropdown-menu\">\r\n              <div\r\n                v-for=\"(provider, index) in providers\"\r\n                :key=\"index\"\r\n                class=\"dropdown-item\"\r\n                @click=\"selectProvider(provider)\"\r\n              >\r\n                <input\r\n                  type=\"checkbox\"\r\n                  :checked=\"provider.provider_code === selectedProvider?.provider_code\"\r\n                />\r\n                <span>{{ provider.provider_code }}</span>\r\n                <span class=\"provider-count\">({{ provider.count }})</span>\r\n              </div>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Kategoriler -->\r\n    <CategorySection\r\n      v-if=\"categoryName === 'favorites' && favoriteGames.length > 0\"\r\n      :category=\"favoriteCategoryWithUniqueKeys\"\r\n      :favorites=\"favorites\"\r\n      :onToggleFavorite=\"toggleFavorite\"\r\n      :loading=\"false\"\r\n      key=\"favorites\"\r\n    />\r\n\r\n    <!-- Oyun listesi -->\r\n    <div class=\"game-category\" v-else>\r\n      <div class=\"games-list\">\r\n        <div v-for=\"(game, index) in sortedGames\" :key=\"index\" class=\"game-item\">\r\n          <div class=\"game-card\" @click=\"launchGame(game)\">\r\n            <img :src=\"game.banner\" alt=\"Game Banner\" class=\"game-banner\" />\r\n            <div class=\"game-meta\">\r\n              <div class=\"provider-row\">\r\n                <span class=\"provider-code\">{{ game.provider?.name || game.provider_code }}</span>\r\n                <span\r\n                  class=\"favorite\"\r\n                  :class=\"{ active: favorites.includes(game._id) }\"\r\n                  @click.stop=\"toggleFavorite(game._id)\"\r\n                >\r\n                  <svg\r\n                    xmlns=\"http://www.w3.org/2000/svg\"\r\n                    width=\"20\"\r\n                    height=\"20\"\r\n                    viewBox=\"0 0 24 24\"\r\n                    :fill=\"favorites.includes(game._id) ? '#FFD700' : '#2c3756'\"\r\n                  >\r\n                    <path\r\n                      d=\"M22,10.1c0.1-0.5-0.3-1.1-0.8-1.1l-5.7-0.8L12.9,3c-0.1-0.2-0.2-0.3-0.4-0.4C12,2.3,11.4,2.5,11.1,3L8.6,8.2L2.9,9\r\n                        C2.6,9,2.4,9.1,2.3,9.3c-0.4,0.4-0.4,1,0,1.4l4.1,4l-1,5.7c0,0.2,0,0.4,0.1,0.6c0.3,0.5,0.9,0.7,1.4,0.4l5.1-2.7l5.1,2.7\r\n                        c0.1,0.1,0.3,0.1,0.5,0.1v0c0.1,0,0.1,0,0.2,0c0.5-0.1,0.9-0.6,0.8-1.2l-1-5.7l4.1-4C21.9,10.5,22,10.3,22,10.1z\"\r\n                    />\r\n                  </svg>\r\n                </span>\r\n              </div>\r\n              <span class=\"game-name\">{{ game.game_name }}</span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <!-- Load more -->\r\n      <div v-if=\"games.length < totalGames\" class=\"see-more-container\">\r\n        <button @click=\"loadMoreGames\" class=\"see-more-button\"> {{ $t('category.showmore') }}</button>\r\n      </div>\r\n\r\n      <!-- Progress -->\r\n      <div v-if=\"totalGames > 0\" class=\"game-progress-info\">\r\n        <div class=\"progress-bar\">\r\n          <div\r\n            class=\"progress-fill\"\r\n            :style=\"{ width: `${(games.length / totalGames) * 100}%` }\"\r\n          ></div>\r\n        </div>\r\n        <div class=\"progress-text\">\r\n           {{ $t('category.shown') }} {{ games.length }} {{ $t('category.of') }} {{ totalGames }} {{ $t('category.games') }}\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Deposit Methods -->\r\n    <HomeDepositMethods />\r\n  </div>\r\n</template>\r\n\r\n<style scoped>\r\n/* Genel */\r\n.home {\r\n  width: 100%;\r\n  max-width: 100%;\r\n  padding: 0 10px;\r\n  box-sizing: border-box;\r\n  overflow-x: hidden;\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.home-banner {\r\n  width: 100%;\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n/* Filter - Provider - Search */\r\n.search-provider-row {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 15px;\r\n  width: 100%;\r\n  margin: 10px 0 20px;\r\n}\r\n\r\n.filter-dropdown {\r\n  background: var(--search-bg);\r\n  color: white;\r\n  padding: 10px;\r\n  border-radius: 5px;\r\n  font-family: var(--font-header);\r\n  font-weight: 600;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n      outline: rgb(44, 40, 82) solid 2px;\r\n}\r\n\r\n.filter-icon {\r\n  width: 18px;\r\n  height: 18px;\r\n  object-fit: contain;\r\n}\r\n\r\n.desktop-filter-provider {\r\n  display: none;\r\n  gap: 10px;\r\n}\r\n\r\n.mobile-filter-provider {\r\n  display: flex;\r\n  gap: 10px;\r\n  width: 100%;\r\n}\r\n\r\n.mobile-filter-provider > .filter-dropdown,\r\n.mobile-filter-provider > .provider-dropdown-container {\r\n  flex: 1;\r\n}\r\n\r\n.search-container {\r\n  flex: 1 1 100%;\r\n  min-width: 200px;\r\n}\r\n\r\n/* Dropdown */\r\n.dropdown {\r\n  position: relative;\r\n  display: inline-block;\r\n}\r\n\r\n.dropdown-toggle {\r\n  background: var(--search-bg);\r\n  color: white;\r\n  padding: 7px 20px;\r\n  border: none;\r\n  border-radius: 5px;\r\n  cursor: pointer;\r\n  width: 190px;\r\n  text-align: left;\r\n  font-family: var(--font-header);\r\n  font-weight: 600;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n      outline: rgb(44, 40, 82) solid 2px;\r\n      height: 39px;\r\n}\r\n\r\n.dropdown-icon {\r\n  width: 20px;\r\n  height: 20px;\r\n}\r\n\r\n.dropdown-menu {\r\n  max-height: 300px;\r\n  overflow-y: auto;\r\n  background: var(--search-bg);\r\n  color: white;\r\n  border-radius: 5px;\r\n  width: 190px;\r\n  position: absolute;\r\n  top: 100%;\r\n  right: 0;\r\n  z-index: 1000;\r\n}\r\n\r\n.dropdown-item {\r\n  padding: 10px 15px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  cursor: pointer;\r\n}\r\n\r\n.dropdown-item:hover {\r\n  background: var(--background2);\r\n}\r\n\r\n.provider-count {\r\n  font-size: 14px;\r\n  opacity: 0.8;\r\n}\r\n\r\n/* Oyun listesi */\r\n.game-category {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  width: 100%;\r\n}\r\n\r\n.games-list {\r\n  display: grid;\r\n  gap: 15px;\r\n  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));\r\n  width: 100%;\r\n}\r\n\r\n.game-item {\r\n  position: relative;\r\n}\r\n\r\n.game-banner {\r\n  width: 100%;\r\n  max-width: 160px;\r\n  aspect-ratio: 16/11;\r\n  border-radius: 10px;\r\n  object-fit: cover;\r\n  margin: 0 auto;\r\n}\r\n\r\n.game-meta {\r\n  margin-top: 5px;\r\n  padding: 0 4px;\r\n  position: relative;\r\n}\r\n\r\n.provider-code {\r\n  font-size: 11px;\r\n  color: #ccc;\r\n}\r\n\r\n.game-name {\r\n  font-size: 14px;\r\n  font-weight: bold;\r\n  color: white;\r\n  line-height: 1.2;\r\n}\r\n\r\n.favorite {\r\n  position: absolute;\r\n  right: 0;\r\n  top: 0;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Load More */\r\n.see-more-container {\r\n  display: flex;\r\n  justify-content: center;\r\n  margin: 20px 0;\r\n}\r\n\r\n.see-more-button {\r\n  padding: 10px 20px;\r\n  font-size: 14px;\r\n      background: var(--buttonyellow);\r\n    box-shadow: rgb(197, 106, 24) 0px -3px 0px 0px inset, rgb(255, 234, 47) 0px 2px 0px 0px inset;\r\n    color: #fff;\r\n    text-shadow: 0px 0px 4px #C56A18;\r\n    border-radius: 12px;\r\n\r\n  cursor: pointer;\r\n  font-family: var(--font-header);\r\n  font-weight: 600;\r\n}\r\n\r\n/* Progress */\r\n.game-progress-info {\r\n  width: 100%;\r\n  max-width: 300px;\r\n  margin-top: 10px;\r\n  text-align: center;\r\n}\r\n\r\n.progress-bar {\r\n  height: 8px;\r\n  width: 100%;\r\n  background: #28285a;\r\n  border-radius: 4px;\r\n  overflow: hidden;\r\n  margin-bottom: 6px;\r\n}\r\n\r\n.progress-fill {\r\n  height: 100%;\r\n  background: var(--bar-inner);\r\n  transition: width 0.3s ease;\r\n}\r\n\r\n.progress-text {\r\n  font-size: 13px;\r\n  color: #aaa;\r\n  font-family: 'Rubik', sans-serif;\r\n}\r\n\r\n/* Responsive */\r\n@media (max-width: 768px) {\r\n  .desktop-filter-provider {\r\n    display: none !important;\r\n  }\r\n  .mobile-filter-provider {\r\n    display: flex;\r\n  }\r\n  .games-list {\r\n    grid-template-columns: repeat(3, 1fr);\r\n    gap: 8px;\r\n  }\r\n  .game-name,\r\n  .favorite,\r\n  .provider-code {\r\n    display: none;\r\n  }\r\n}\r\n\r\n/* PC düzeni */\r\n@media (min-width: 769px) {\r\n  .mobile-filter-provider {\r\n    display: none !important;\r\n  }\r\n\r\n  .search-provider-row {\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: space-between;\r\n    gap: 15px;\r\n    width: 100%;\r\n  }\r\n\r\n  .search-container {\r\n    flex: 1; /* Arama genişlesin */\r\n    min-width: 300px;\r\n  }\r\n\r\n  .desktop-filter-provider {\r\n    display: flex;\r\n    gap: 10px;\r\n    flex-shrink: 0; /* daralmayı engeller */\r\n  }\r\n\r\n  .dropdown-toggle,\r\n  .filter-dropdown {\r\n    height: 39px;\r\n    display: flex;\r\n    align-items: center;\r\n  }\r\n}\r\n\r\n\r\n@media (max-width: 1024px) {\r\n    .search-bar-wrapper[data-v-7cb41050] {\r\n        padding-left: 0;\r\n        padding-right: 0;\r\n    }\r\n}\r\n</style>\r\n",
		"<template>\r\n  <div class=\"category-banner-wrapper\">\r\n    <!-- Masaüstü: 3 slide -->\r\n    <div class=\"banner-pc\" v-if=\"!isMobileOrTablet\">\r\n      <div class=\"embla\" ref=\"emblaPC\">\r\n        <div class=\"embla__container\">\r\n          <div\r\n            v-for=\"(banner, index) in banners\"\r\n            :key=\"banner._id\"\r\n            class=\"embla__slide banner-card\"\r\n          >\r\n            <img :src=\"backendUrl + banner.imageUrl\" class=\"banner-image\" />\r\n            <div class=\"banner-text\">\r\n              <h2 class=\"text3d-lg\">{{ banner.title }}</h2>\r\n              <p class=\"text3d-sm\">{{ banner.subtitle }}</p>\r\n              <a :href=\"banner.link\" class=\"banner-button\">Go Now</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <button class=\"embla__arrow embla__arrow--prev\" @click=\"scrollPrevPC\">&#60;</button>\r\n      <button class=\"embla__arrow embla__arrow--next\" @click=\"scrollNextPC\">&#62;</button>\r\n\r\n      <div class=\"progress-dots\">\r\n       <div\r\n  v-for=\"(banner, index) in banners\"\r\n  :key=\"index\"\r\n  class=\"dot\"\r\n  :class=\"{\r\n    active: index === selectedIndex,\r\n    passed: index < selectedIndex\r\n  }\"\r\n>\r\n  <div\r\n    v-if=\"index === selectedIndex\"\r\n    class=\"fill\"\r\n    :key=\"progressKey\"\r\n  ></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Mobil: 1 slide -->\r\n    <div class=\"banner-mobile\" v-else>\r\n      <div class=\"embla\" ref=\"emblaMobile\">\r\n        <div class=\"embla__container\">\r\n          <div\r\n            v-for=\"(banner, index) in banners\"\r\n            :key=\"banner._id\"\r\n            class=\"embla__slide banner-card mobile-stacked\"\r\n          >\r\n            <img :src=\"backendUrl + banner.imageUrl\" class=\"banner-image\" />\r\n            <div class=\"banner-text\">\r\n              <h2 class=\"text3d-lg\">{{ banner.title }}</h2>\r\n              <p class=\"text3d-sm\">{{ banner.subtitle }}</p>\r\n              <a :href=\"banner.link\" class=\"banner-button\">Go Now</a>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"progress-dots\">\r\n        <div\r\n          v-for=\"(banner, index) in banners\"\r\n          :key=\"index\"\r\n          class=\"dot\"\r\n          :class=\"{\r\n  active: index === selectedIndexMobile,\r\n  passed: index < selectedIndexMobile\r\n}\"\r\n        >\r\n          <div\r\n            v-if=\"index === selectedIndexMobile\"\r\n            class=\"fill\"\r\n            :key=\"progressKeyMobile\"\r\n          ></div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script setup>\r\nimport { ref, onMounted, onUnmounted, nextTick } from 'vue'\r\nimport axios from 'axios'\r\nimport emblaCarousel from 'embla-carousel'\r\n\r\nconst props = defineProps({\r\n  slug: { type: String, required: true }\r\n})\r\n\r\nconst banners = ref([])\r\nconst backendUrl = process.env.VUE_APP_BACKEND_URL || 'https://apievrymatrix5d84k321.com'\r\n\r\nconst isMobileOrTablet = ref(false)\r\n\r\nconst selectedIndex = ref(0)\r\nconst progressKey = ref(0)\r\nconst selectedIndexMobile = ref(0)\r\nconst progressKeyMobile = ref(0)\r\n\r\nconst emblaPC = ref(null)\r\nconst emblaMobile = ref(null)\r\nlet emblaInstancePC = null\r\nlet emblaInstanceMobile = null\r\n\r\nconst scrollNextPC = () => emblaInstancePC?.scrollNext()\r\nconst scrollPrevPC = () => emblaInstancePC?.scrollPrev()\r\n\r\nlet intervalPC = null\r\nlet intervalMobile = null\r\n\r\nonMounted(async () => {\r\n  isMobileOrTablet.value = window.innerWidth <= 1024\r\n\r\n  try {\r\n    const res = await axios.get(`/public/banners/${props.slug}`)\r\n    banners.value = res.data || []\r\n  } catch (err) {\r\n    console.error('Banner fetch error:', err)\r\n  }\r\n\r\n  await nextTick()\r\n\r\n  if (emblaPC.value) {\r\n    emblaInstancePC = emblaCarousel(emblaPC.value, {\r\n      loop: true,\r\n      align: 'start',\r\n      slidesToScroll: 1,\r\n    })\r\n    emblaInstancePC.on('select', () => {\r\n      selectedIndex.value = emblaInstancePC.selectedScrollSnap()\r\n      progressKey.value++\r\n    })\r\n  }\r\n\r\n  if (emblaMobile.value) {\r\n    emblaInstanceMobile = emblaCarousel(emblaMobile.value, {\r\n      loop: true,\r\n      align: 'center',\r\n      slidesToScroll: 1,\r\n    })\r\n    emblaInstanceMobile.on('select', () => {\r\n      selectedIndexMobile.value = emblaInstanceMobile.selectedScrollSnap()\r\n      progressKeyMobile.value++\r\n    })\r\n  }\r\n\r\n  intervalPC = setInterval(() => {\r\n    if (!isMobileOrTablet.value && emblaInstancePC && banners.value.length > 1) {\r\n      emblaInstancePC.scrollNext()\r\n    }\r\n  }, 5000)\r\n\r\n  intervalMobile = setInterval(() => {\r\n    if (isMobileOrTablet.value && emblaInstanceMobile && banners.value.length > 1) {\r\n      emblaInstanceMobile.scrollNext()\r\n    }\r\n  }, 5000)\r\n})\r\n\r\nonUnmounted(() => {\r\n  clearInterval(intervalPC)\r\n  clearInterval(intervalMobile)\r\n  emblaInstancePC?.destroy()\r\n  emblaInstanceMobile?.destroy()\r\n})\r\n</script>\r\n\r\n<style scoped>\r\n/* Stil kısmını değiştirmedim, doğrudan senin verdiğin gibi kullanabilirsin. Aynı şekilde devam edebilir. */\r\n.category-banner-wrapper {\r\n  width: 100%;\r\n  margin-bottom: 10px;\r\n}\r\n/* embla, embla__container, embla__slide, .banner-card vs. aynı kalabilir */\r\n</style>\r\n\r\n\r\n<style scoped>\r\n.category-banner-wrapper {\r\n  width: 100%;\r\n  margin-bottom: 10px;\r\n}\r\n.embla {\r\n  position: relative;\r\n  width: 100%;\r\n  overflow: hidden;\r\n}\r\n.embla__container {\r\n  display: flex;\r\n  user-select: none;\r\n}\r\n.embla__slide {\r\n  position: relative;\r\n  flex: 0 0 33.3333%;\r\n  min-width: 0;\r\n  margin-right: 12px;\r\n  border-radius: 10px;\r\n  overflow: hidden;\r\n  height: 220px;\r\n  background: #191e26;\r\n}\r\n.banner-card {\r\n  box-shadow: 0 3px 16px #0008;\r\n  border-radius: 10px;\r\n}\r\n.banner-image {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n.banner-text {\r\n  position: absolute;\r\n  top: 16px;\r\n  left: 16px;\r\n  color: white;\r\n  max-width: 70%;\r\n  z-index: 2;\r\n}\r\n.text3d-lg {\r\n  font-size: 1.4rem;\r\n  font-weight: bold;\r\n  text-shadow: 1px 1px 4px #000;\r\n  margin: 0;\r\n}\r\n.text3d-sm {\r\n  font-size: 1rem;\r\n  font-weight: 600;\r\n  text-shadow: 1px 1px 3px #000;\r\n  margin-top: 6px;\r\n}\r\n.banner-button {\r\n  display: inline-block;\r\n  margin-top: 0.5rem;\r\n  padding: 8px 14px;\r\n  font-weight: 700;\r\n  font-size: 0.9rem;\r\n  color: white;\r\n  text-decoration: none;\r\n  border-radius: 5px;\r\n  background: linear-gradient(to bottom, #01e0a3 0%, #00aa6d 95%);\r\n  transition: transform 0.3s ease;\r\n}\r\n.banner-button:hover {\r\n  transform: translateY(-2px);\r\n}\r\n.embla__arrow {\r\n  position: absolute;\r\n  top: 50%;\r\n  transform: translateY(-50%);\r\n  z-index: 3;\r\n  background: none;\r\n  border: none;\r\n  font-size: 20px;\r\n  color: #8899a8;\r\n  cursor: pointer;\r\n  transition: color 0.2s;\r\n}\r\n.embla__arrow--prev {\r\n  left: -32px;\r\n}\r\n.embla__arrow--next {\r\n  right: -32px;\r\n}\r\n.embla__arrow:hover {\r\n  color: #fff;\r\n}\r\n.progress-dots {\r\n  display: flex;\r\n  justify-content: center;\r\n  margin-top: 12px;\r\n  gap: 6px;\r\n}\r\n.dot {\r\n  width: 18px;\r\n  height: 8px;\r\n  background-color: #28285a;\r\n  border-radius: 8px;\r\n  position: relative;\r\n  overflow: hidden;\r\n  transition: all 0.3s;\r\n}\r\n\r\n.dot.active {\r\n  width: 38px;\r\n  height: 8px;\r\n  background-color: #28285a;\r\n}\r\n\r\n.dot.passed {\r\n  background: var(--bar-inner);\r\n}\r\n.fill {\r\n  position: absolute;\r\n  left: 0;\r\n  top: 0;\r\n  height: 100%;\r\n  background: var(--bar-inner);\r\n  border-radius: 8px;\r\n  animation: progressFill 5s linear forwards;\r\n}\r\n@keyframes progressFill {\r\n  from { width: 0%; }\r\n  to { width: 100%; }\r\n}\r\n\r\n/* Mobil özel: 1 slide ortalanmış, dotlar */\r\n@media (max-width: 1024px) {\r\n  .embla__slide {\r\n    flex: 0 0 90%;\r\n    margin-right: 8px;\r\n    height: 140px;\r\n  }\r\n  .banner-card {\r\n    height: 140px;\r\n  }\r\n}\r\n</style>",
