w', 'modalsSetShow']),\n            homeCashierButton() {\n                if(this.authUser.user === null) {\n                    this.notificationShow({ type: 'error', message: 'Please sign in to perform this action.' });\n                    return;\n                }\n\n                this.modalsSetShow('Cashier');\n            }\n        },\n        computed: {\n            ...mapGetters(['authUser'])\n        }\n\n    }\n</script>\n\n<style scoped>\n    .home-deposit-methods {\n        width: 100%;\n        position: relative;\n        margin-top: 85px;\n    }\n\n    .home-deposit-methods::before {\n        content: '';\n        width: 100%;\n        height: 1px;\n        position: absolute;\n        top: 0;\n        left: 0;\n        background: linear-gradient(90deg, rgba(2, 25, 44, 0) 0%, #ffeb00 calc(50% - 110px), rgba(2, 25, 44, 0) calc(50% - 108px), rgba(2, 25, 44, 0) calc(50% + 108px), #ffeb00 calc(50% + 110px), rgba(2, 25, 44, 0) 100%);\n        z-index: -1;\n    }\n\n    .home-deposit-methods::after {\n        content: '';\n        width: 100%;\n        height: 1px;\n        position: absolute;\n        bottom: 0;\n        left: 0;\n        background: linear-gradient(90deg, rgba(3, 28, 49, 0) 0%, #ffeb00 50%, rgba(3, 28, 49, 0) 100%);\n        z-index: 0;\n    }\n\n    .home-deposit-methods .methods-title {\n        position: absolute;\n        top: 0;\n        left: 50%;\n        transform: translate(-50%, -50%);\n        white-space: nowrap;\n        font-size: 18px;\n        font-weight: 800;\n    }\n\n    .home-deposit-methods .methods-content {\n        width: 100%;\n        display: flex;\n        flex-wrap: wrap;\n        padding: 30px 0;\n        background: radial-gradient(50% 40% at 50% 90%, rgb(216 255 0 / 45%), rgba(26, 4, 54, 0) 100%);\n    }\n\n    .home-deposit-methods button.button-method {\n        width: 12.5%;\n        height: 105px;\n        position: relative;\n        display: flex;\n        flex-direction: column;\n        just