g, #3b7eb7 -25%, #145081 100%);\r\n    }\r\n\r\n    .home-featured {\r\n  display: grid;\r\n  gap: 20px;\r\n  margin-top: 20px;\r\n  grid-template-columns: repeat(4, 1fr); /* Masaüstünde 4 sütun */\r\n}\r\n\r\n.home-grid {\r\n      width: 100%;\r\n      max-width: 100%;\r\n      display: grid;\r\n      grid-template-columns: repeat(6, 1fr); /* Masaüstü için 4 sütun */\r\n      gap: 20px; /* Elemanlar arası boşluk */\r\n      margin: 20px 0;\r\n  }\r\n\r\n\r\n\r\n .grid-item {\r\ncursor: pointer;\r\ntext-align: center;\r\n}\r\n\r\n.grid-item img {\r\nmax-width: 100%;\r\nheight: auto;\r\ndisplay: block;\r\nborder-radius: 10px;\r\n\r\n}\r\n\r\n.featured-img {\r\n  width: 100%;\r\n  height: 140px;\r\n  border-radius: 10px;\r\n  transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Mouse üzerine gelme efekti */\r\n.featured-img:hover {\r\n  transform: scale(1.1); /* Resmi büyüt */\r\n  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3); /* Gölge efekti */\r\n}\r\n\r\n/* Mobil düzen - 2x2 düzeni */\r\n@media (max-width: 768px) {\r\n  .home-featured {\r\n    grid-template-columns: repeat(2, 1fr); /* Mobilde 2 sütun */\r\n  }\r\n  .featured-img  {\r\n    width: 100%;\r\n    height: 95px;\r\n  }\r\n}\r\n\r\n    .home .featured-content,\r\n    .home .games-content {\r\n        width: 100%;\r\n        display: flex;\r\n        flex-wrap: wrap;\r\n    }\r\n\r\n    @media only screen and (max-width: 1600px) {\r\n\r\n        .home .home-banner,\r\n        .home .home-featured,\r\n        .home .home-games {\r\n            width: 100%;\r\n        }\r\n\r\n    }\r\n\r\n    @media only screen and (max-width: 950px) {\r\n\r\n        .home {\r\n            padding: 0px 10px 443px 10px;\r\n        }\r\n\r\n    }\r\n    .category-section {\r\n        width: 100%;\r\n        max-width: 100%;\r\n        margin: 20px 0;\r\n    }\r\n\r\n    .category-header {\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\