background: var(--background) !important;\r\n  border-radius: 8px;\r\n  width: 100%;\r\n  \r\n  \r\n  color: white;\r\n}\r\n\r\n.game-search-icon {\r\n  width: 24px;\r\n  height: 24px;\r\n  margin-right: 10px;\r\n}\r\n\r\n.game-search-input {\r\n  width: 100%;\r\n  background-color: transparent;\r\n  border: none;\r\n  outline: none;\r\n  color: white;\r\n  font-size: 16px;\r\n  font-family: \"Rubik\", sans-serif;\r\n}\r\n\r\n.game-search-input::placeholder {\r\n  color: #aaa;\r\n  font-size: 14px;\r\n}\r\n\r\n/* Search Results Container */\r\n.game-search-results {\r\n  background: var(--background) !important;\r\n  color: white;\r\n  padding: 20px;\r\n  border-radius: 8px;\r\n  \r\n  margin-top: 10px;\r\n  position: relative;\r\n}\r\n\r\n/* Close Button */\r\n.game-search-close-button {\r\n  position: absolute;\r\n  top: 10px;\r\n  right: 10px;\r\n  background: none;\r\n  border: none;\r\n  color: white;\r\n  font-size: 18px;\r\n  font-weight: bold;\r\n  cursor: pointer;\r\n}\r\n\r\n/* Search Results Header */\r\n.game-search-header {\r\n  display: flex;\r\n  align-items: center;\r\n  margin-bottom: 15px;\r\n  font-size: 18px;\r\n  font-weight: bold;\r\n  color: white;\r\n}\r\n\r\n.game-search-header img {\r\n  width: 20px;\r\n  height: 20px;\r\n  margin-right: 10px;\r\n}\r\n\r\n/* Search Results Content */\r\n.game-search-content {\r\n  display: flex;\r\n  gap: 15px;\r\n  overflow-x: auto; /* Yatay kaydırma */\r\n  white-space: nowrap; /* Tek sıra */\r\n  padding-bottom: 10px;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.2);\r\n}\r\n\r\n.game-search-item {\r\n  flex-shrink: 0; /* Kaydırılabilir öğe */\r\n  width: 120px;\r\n  height: 120px;\r\n  border-radius: 8px;\r\n  overflow: hidden;\r\n  background-color: #01344e;\r\n  cursor: pointer;\r\n  transition: transform 0.3s ease, box-shadow 0.3s ease;\r\n}\r\n\r\n.game-search-item img {\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n}\r\n\r\n.game-search-item:hover {\r\n  transform: scale(1.0