ze: 14px;\r\n  font-weight: bold;\r\n}\r\n\r\n.provider-code {\r\n  font-size: 12px;\r\n  opacity: 0.7;\r\n  color: white;\r\n}\r\n\r\n/* Like Button */\r\n.like-button {\r\n  position: absolute;\r\n  bottom: -5px;\r\n  right: 10px;\r\n  cursor: pointer;\r\n}\r\n\r\n.like-img {\r\n  width: 20px;\r\n  height: 20px;\r\n  transition: transform 0.3s ease;\r\n}\r\n\r\n.like-button:hover .like-img {\r\n  transform: scale(1.2);\r\n}\r\n\r\n/* Hover Effects */\r\n\r\n.game-item:hover .game-overlay {\r\n  opacity: 1;\r\n}\r\n\r\n    @media only screen and (max-width: 1600px) {\r\n        .home .home-banner,\r\n        .home .home-featured,\r\n        .home .home-buttons,\r\n        .home .home-games {\r\n            width: 100%;\r\n        }\r\n        .home .home-buttons {\r\n            flex-wrap: nowrap;\r\n        }\r\n    }\r\n\r\n    @media only screen and (max-width: 950px) {\r\n        .home {\r\n            padding: 0px 10px 443px 10px;\r\n        }\r\n\r\n        .home .home-buttons {\r\n            flex-wrap: nowrap;\r\n        }\r\n\r\n        .search-container {\r\n            padding: 0 10px;\r\n        }\r\n\r\n        .search-box {\r\n            max-width: 100%;\r\n        }\r\n\r\n        .home .button-item {\r\n            width: 90px;\r\n            margin: 0 5px;\r\n        }\r\n    }\r\n\r\n    @media only screen and (max-width: 768px) {\r\n      .home-grid {\r\n          grid-template-columns: repeat(3, 1fr); /* Mobil için 2 sütun */\r\n      }\r\n  }\r\n \r\n</style>\r\n",
		"<template>\n    <div class=\"home-banner-user\">\n        <div class=\"user-inner\">\n            <img src=\"@/assets/img/banner/userbanner.png\" />\n            \n            <div v-if=\"authUser.user === null\" class=\"inner-guest\">\n                <span class=\"gradient-green\">{{ $t('hous.1') }}</span>\n                <AuthButton />\n            </div>\n            <div v-else class=\"inner-auth\" v-bind:class=\"[\n                'auth-' + homeGetLevelColor\n            ]\">\n                <span class=\"gradient-green\">{{ $t('hous.2') }}</span>\n                <div class=\"auth-info\">\n                    <div class=\"info-avatar\">\n                        <AvatarImage v-bind:image=\"authUser.user.avatar\" />\n                    </div>\n                    <span v-html=\"authUser.user.username\"></span>\n                </div>\n              \n            </div>\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import AuthButton from '@/components/AuthButton';\n    import AvatarImage from '@/components/AvatarImage';\n\n    export default {\n        name: 'HomeBannerUser',\n        components: {\n            AuthButton,\n            AvatarImage\n        },\n        computed: {\n            ...mapGetters([\n                'authUser'\n            ]),\n            homeGetLevel() {\n                let level = Math.floor(Math.pow(this.authUser.user.xp  / 100, 1 / 3));\n                return level >= 100 ? 100 : level; \n            },\n            homeGetLevelColor() {\n                let color = '';\n\n                if(this.homeGetLevel >= 2 && this.homeGetLevel < 26) { color = 'blue'; }\n                else if(this.homeGetLevel >= 26 && this.homeGetLevel < 51) { color = 'green'; }\n                else if(this.homeGetLevel >= 51 && this.homeGetLevel < 76) { color = 'orange'; }\n                else if(this.homeGetLevel >= 76 && this.homeGetLevel < 100) { color = 'red'; }\n                else if(this.homeGetLevel >= 100) { color = 'purple'; }\n\n                return color;\n            },\n            homeGetLevelBet() {\n                return this.homeGetLevel >= 100 ? 2970100 : (Math.pow(this.homeGetLevel + 1, 3) - Math.pow(this.homeGetLevel, 3)) * 100;\n            },\n            homeGetLevelProgress() {\n                return Math.floor((this.homeGetLevel >= 100 ? 2970100 * 1000 : this.authUser.user.xp - (Math.pow(this.homeGetLevel, 3) * 100 * 1000)) / 10) / 100;\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .home-banner-user {\n        width: 100%;\n        height: 175px;\n        position: relative;\n        \n        padding: 1px;\n        z-index: 1;\n    }\n\n    .home-banner-user::before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        border-radius: 15px;\n        \n        z-index: -1;\n    }\n\n    .home-banner-user::after {\n        content: '';\n        width: calc(100% - 2px);\n        height: calc(100% - 2px);\n        position: absolute;\n        top: 1px;\n        left: 1px;\n        border-radius: 15px;\n        \n        z-index: -1;\n    }\n\n    .home-banner-user .user-inner {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        padding: 22px 180px 22px 35px;\n        border-radius: 15px;\n        \n        z-index: 1;\n    }\n\n    .home-banner-user .user-inner img:nth-of-type(1) {\n        height: calc(100% - 1px);\n        width: 100%;\n        position: absolute;\n        top: 0;\n        right: 0;\n        z-index: 0;\n        z-index: -1;\n    }\n\n    .home-banner-user .user-inner img:nth-of-type(2) {\n        height: 205px;\n        position: absolute;\n        bottom: -23px;\n        right: -15px;\n        transform: scaleX(-1);\n        z-index: -1;\n    }\n\n    .home-banner-user .inner-guest,\n    .home-banner-user .inner-auth {\n        height: 100%;\n        displa