              </svg>\n            </button>\n        </div>\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import HomeNewsElement from '@/components/home/HomeNewsElement';\n\n    export default {\n        name: 'HomeBannerNews',\n        components: {\n            HomeNewsElement\n        },\n        data() {\n            return {\n                homeBanners: ['Rain'],\n                homePosition: 0,\n                homeDirection: null,\n                homeInterval: null\n            }\n        },\n        methods: {\n            homeStartInterval() {\n                clearInterval(this.homeInterval);\n                this.homeInterval = setInterval(() => {\n                    this.homeNextButton();\n                }, 6000);\n            },\n            homePreviousButton() {\n                this.homeDirection = 'left';\n                this.homePosition = this.homePosition === 0 ? this.homeBanners.length - 1 : this.homePosition - 1;\n                this.homeStartInterval();\n            },\n            homeNextButton() {\n                this.homeDirection = 'right';\n                this.homePosition = this.homePosition >= this.homeBanners.length - 1 ? 0 : this.homePosition + 1;\n                this.homeStartInterval();\n            }\n        },\n        beforeUnmount() {\n            clearInterval(this.homeInterval);\n        },\n        mounted() {\n            this.homeStartInterval();\n        }\n    }\n</script>\n\n<style scoped>\n    .home-banner-news {\n        width: calc(50% - 15px);\n        height: 175px;\n        position: relative;\n        padding: 0 0 1px 0;\n    }\n\n    .home-banner-news::before {\n        content: '';\n        width: 100%;\n        height: 100%;\n        position: absolute;\n        top: 0;\n        left: 0;\n        border-radius: 15px;\n        background: linear-gradient(180deg, rgba(0, 0, 0, 0) 0%, #1a486b 100%);\n        z-index: -1;\n    }\n\n    .home-banner-news::after {\n        content: '';\n        width: calc(100% - 2px);\n        height: calc(100% - 2px);\n        position: absolute;\n        top: 1px;\n        left: 1px;\n        border-radius: 15px;\n        background-color: #031d32;\n        z-index: -1;\n    }\n\n    .home-banner-news .news-inner {\n        width: 100%;\n        height: 100%;\n        display: flex;\n        justify-content: space-between;\n        border-radius: 15px;\n        overflow: hidden;\n    }\n\n    .home-banner-news .news-inner img {\n        height: 100%;\n    }\n\n    .home-banner-news .news-inner button.button-previous,\n    .home-banner-news .news-inner button.button-next {\n        width: 35px;\n        height: 100%;\n        display: flex;\n        justify-content: center;\n        align-items: center;\n        background-color: #092035;\n        z-index: 1;\n    }\n\n    .home-banner-news .news-inner button.button-previous {\n        border-radius: 15px 0 0 15px;\n    }\n\n    .home-banner-news .news-inner button.button-next {\n        border-radius: 0 15px 15px 0;\n    }\n\n    .home-banner-news .news-inner button.button-previous svg,\n    .home-banner-news .news-inner button.button-next svg {\n        fill: #93adc5;\n        transition: fill 0.3s ease;\n    }\n\n    .home-banner-news .news-inner button.button-next svg {\n        transform: rotate(180deg);\n    }\n\n    .home-banner-news .news-inner button.button-previous:hover svg,\n    .home-banner-news .news-inner button.button-next:hover svg {\n        fill: #ffffff;\n    }\n\n    .home-banner-news .inner-content {\n        width: calc(100% - 70px);\n        height: 100%;\n        position: relative;\n        overflow: hidden;\n    }\n\n    @media only screen and (max-width: 900px) {\n\n        .home-banner-news {\n            width: 100%;\n            margin-top: 15px;\n        }\n\n    }\n</style>\n",
		"<template>\n    <transition v-bind:name=\"homeGetTransition\">\n        <div v-if=\"position === index\" class=\"home-news-element\">\n           <keep-alive>\n  <component\n    :is=\"'Banner' + (banner === 'JackPot' ? 'Jackpot' : banner === 'Tournament' ? 'Tournament' : banner)\"\n  />\n</keep-alive>\n        </div>\n    </transition>\n</template>\n\n<script>\n    import BannerRain from '@/components/banner/BannerRain';\n    import BannerJackpot from '@/components/banner/BannerJackpot';\n    import BannerTournament from '@/components/banner/BannerTournament';\n\n    export default {\n        name: 'HomeNewsBanner',\n        components: {\n            BannerRain,\n            BannerJackpot,\n            BannerTournament\n        },\n        props: ['banner', 'direction', 'position', 'index'],\n        data() {\n            return {\n                currentBanner: 0, // Şu anki bannerın indexi\n                banners: ['Rain', 'JackPot', 'Tournament'], // Bannerlar listesi\n                intervalId: null // Zamanlayıcı\n            };\n        },\n        computed: {\n            homeGetTransition() {\n                return 'slider-fade'; // Geçiş animasyonu ismi\n            },\n            banner() {\n                return this.banners[this.currentBanner]; // Sırasıyla bannerı getir\n            }\n        },\n        mounted() {\n            this.startBannerRotation(); // Sayfa yüklendiğinde başlat\n        },\n        beforeDestroy() {\n            clearInterval(this.intervalId); // Bileşen yok olduğunda interval'i temizle\n        },\n        methods: {\n            startBannerRotation() {\n                // 5 saniyede bir banner değiştirme işlemi\n                this.intervalId = setInterval(() => {\n                    this.currentBanner = (this.currentBanner + 1) % this.banners.length;\n                }, 5000); // 5 saniyede bir banner değiştir\n            }\n        }\n    }\n</script>\n\n<style scoped>\n    .home-news-element {\n        position: absolute;\n        top: 0;\n        bottom: 0;\n        left: 0;\n        right: 0;\n    }\n\n    /* Geçiş animasyonları */\n    .slider-fade-enter-active,\n    .slider-fade-leave-active {\n        transition: opacity 0.5s ease, transform 0.5s ease; /* Animasyon süresi ve tipi */\n    }\n\n    .slider-fade-enter, .slider-fade-leave-to /* .slider-fade-leave-active for below version 2.1.8 */ {\n        opacity: 0; /* Saydamlık başlangıç ve bitiş */\n        transform: scale(1.05); /* Biraz büyüterek görsel etki */\n    }\n\n    /* Sol ve sağ kaydırma için animasyonlar */\n    .home-news-element.slider-left-enter-active,\n    .home-news-element.slider-left-leave-active,\n    .home-news-element.slider-right-enter-active,\n    .home-news-element.slider-right-leave-active {\n        transition: all 0.5s ease;\n    }\n\n    .home-news-element.slider-left-enter {\n        transform: translateX(-100%);\n    }\n\n    .home-news-element.slider-left-leave-to {\n        transform: translateX(100%);\n    }\n\n    .home-news-element.slider-right-enter {\n        transform: translateX(100%);\n    }\n\n    .home-news-element.slider-right-leave-to {\n        transform: translateX(-100%);\n    }\n</style>\n",
		"<template>\n    <div class=\"banner-rain\">\n        <div class=\"rain-text\">\n            <div class=\"text-header\">\n                RAIN\n                <button v-on:click=\"rainSetDropdownTip(true)\" class=\"button-tip\">\n                    <div class=\"button-inner\">\n                        <IconRain />\n                        <span class=\"gradient-green\">TIP RAIN</span>\n                    </div>\n                </button>\n            </div>\n            <div class=\"text-info\">Rain is distributed every <span>30 minutes</span> via the chat. Play and tip the rain to contribute towards the rain!</div>\n            <div class=\"text-bottom\">\n                <div class=\"bottom-timer\">\n                    <IconTimerGradient />\n                    <div class=\"timer-value\">\n                        <span>{{rainTimer.split(':')[0]}}</span>m\n                        <span>{{rainTimer.split(':')[1]}}</span>s\n                    </div>\n                </div>\n                <div class=\"bottom-amount\">\n                    <img src=\"@/assets/img/icons/coin.svg\" alt=\"icon\" />\n                    <div class=\"amount-value\">\n                        <span>{{rainFormatValue(generalRain.site.amount).split('.')[0]}}</span>.{{rainFormatValue(generalRain.site.amount).split('.')[1]}}\n                    </div>\n                </div>\n            </div>\n        </div>\n        <img src=\"@/assets/img/banner-rain.png\" />\n    </div>\n</template>\n\n<script>\n    import { mapGetters, mapActions } from 'vuex';\n    import IconRain from '@/components/icons/IconRain';\n    import IconTimerGradient from '@/components/icons/IconTimerGradient';\n\n    export default {\n        name: 'BannerRain',\n        components: {\n            IconRain,\n            IconTimerGradient\n        },\n        data() {\n            return {\n                rainTimerInterval: null,\n                rainTimer: '00:00'\n            }\n        },\n        methods: {\n            ...mapActions(['rainSetDropdownTip']),\n           \n            rainFormatValue(value) {\n                return parseFloat(Math.floor(value / 10) / 100).toFixed(2).toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',');\n            },\n            rainStartTimer() {\n                const endingTime = new Date(this.generalRain.site.updatedAt).getTime() + (1000 * 60 * (this.generalRain.site.state === 'running' ? 2 : 30));\n                let timeLeft = Math.floor((endingTime - (new Date().getTime() + this.generalTimeDiff)) / 1000);\n                timeLeft = this.generalRain.site.state === 'pending' ? 60 * 2 : timeLeft <= 0 ? 0 : timeLeft;\n\n                let timeMinutes = Math.floor((timeLeft % (60 * 60)) / 60);\n                timeMinutes = timeMinutes < 10 ? '0' + timeMinutes : timeMinutes;\n                let timeSeconds = Math.floor(timeLeft % 60);\n                timeSeconds = timeSeconds < 10 ? '0' + timeSeconds : timeSeconds;\n\n                this.rainTimer = timeMinutes.toString() + ':' + timeSeconds.toString();\n            }\n        },\n        computed: {\n            ...mapGetters(['generalTimeDiff', 'generalRain']),\n        },\n        beforeDestroy() {\n            clearInterval(this.rainTimerInterval);\n        },\n        created() {\n            this.rainTimerInterval = setInterval(() => { this.rainStartTimer(); }, 500);\n        }\n    }\n</script>\n\n<style scoped>\n    .banner-rain {\n        width: 100%;\n        height: 100%;\n        position: relative;\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        padding: 20px 40px 20px 25px;\n        background: linear-gradient(100deg, rgba(2, 243, 127, 0.74) 0%, rgba(2, 216, 113, 0.65) 7%, rgba(0, 0, 0, 0) 50%),\n                    linear-gradient(0deg, rgba(0, 0, 0, 0.2), rgba(0, 0, 0, 0.2)),\n                    radial-gradient(110% 110% at 50% 30%, #005e3e 0%, #021729 100%);\n        overflow: hidden;\n        z-index: 1;\n  