		"<template>\r\n  <div class=\"game-start-container\">\r\n    <!-- Game iframe -->\r\n    <div class=\"iframe-wrapper\">\r\n      <div v-if=\"isLoading\" class=\"loading-placeholder\">\r\n        <p>Loading game...</p>\r\n      </div>\r\n\r\n      <iframe\r\n        v-if=\"gameUrl\"\r\n        :src=\"gameUrl\"\r\n        frameborder=\"0\"\r\n        allowfullscreen\r\n        class=\"game-iframe\"\r\n        @load=\"onIframeLoad\"\r\n        @error=\"onIframeError\"\r\n      ></iframe>\r\n    </div>\r\n\r\n    <!-- Game details & controls -->\r\n    <div class=\"game-info\">\r\n      <div class=\"game-header\">\r\n        <h1>{{ gameDetails.game_name }}</h1>\r\n        <span class=\"provider\">{{ gameDetails.provider_code }}</span>\r\n      </div>\r\n\r\n      <div class=\"game-controls\">\r\n       \r\n\r\n        <!-- Share -->\r\n        <button class=\"control-btn\" @click=\"openShareModal\">\r\n         <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" viewBox=\"0 0 32 32\"><path fill=\"#7b6cb9\" d=\"M14 3a1 1 0 1 1 0 2H7.5A2.5 2.5 0 0 0 5 7.5v17A2.5 2.5 0 0 0 7.5 27h17a2.5 2.5 0 0 0 2.5-2.5V19a1 1 0 1 1 2 0v5.5a4.5 4.5 0 0 1-4.5 4.5h-17A4.5 4.5 0 0 1 3 24.5v-17A4.5 4.5 0 0 1 7.5 3zm5.58-.907a1 1 0 0 1 1.067.146l10 8.5a1 1 0 0 1 0 1.523l-10 8.5A1 1 0 0 1 18.999 20v-3.96c-3.193.258-5.636 1.722-7.34 3.213a15.6 15.6 0 0 0-2.115 2.26a13 13 0 0 0-.645.93l-.027.046l-.006.006l.001.001A1 1 0 0 1 7 22.036c0-.222-.003-.444.003-.666c.011-.406.042-.982.12-1.67c.155-1.37.5-3.218 1.265-5.08s1.967-3.776 3.855-5.225C13.948 8.086 16.161 7.2 19 7.032V3a1 1 0 0 1 .58-.907\"/></svg>\r\n          <span>Share</span>\r\n        </button>\r\n\r\n        <div class=\"divider\"></div>\r\n\r\n        <!-- Movie Mode -->\r\n        <button class=\"control-btn\" @click=\"toggleMovieMode\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\"><path fill=\"#7b6cb9\" d=\"M20 3H4c-1.103 0-2 .897-2 2v14c0 1.103.897 2 2 2h16c1.103 0 2-.897 2-2V5c0-1.103-.897-2-2-2m.001 6q-.002 0 0 0h-.465l-2.667-4H20zM15.5 15L10 18v-6zm-.964-6l-2.667-4h2.596l2.667 4zm-2.404 0H9.536L6.869 5h2.596zM4 5h.465l2.667 4H4z\"/></svg>\r\n          <span>Movie Mode</span>\r\n        </button>\r\n\r\n        <!-- Fullscreen -->\r\n        <button @click=\"toggleFullscreen\" class=\"control-btn\">\r\n          <svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 48 48\"><g fill=\"none\" stroke=\"#7b6cb9\" stroke-linejoin=\"round\" stroke-width=\"4\"><path stroke-linecap=\"round\" d=\"M16 40H6a2 2 0 0 1-2-2V10a2 2 0 0 1 2-2h36a2 2 0 0 1 2 2v6\"/><path fill=\"#7b6cb9\" d=\"M42 24H26a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2V26a2 2 0 0 0-2-2Z\"/></g></svg>\r\n          <span>Fullscreen</span>\r\n        </button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Share Modal -->\r\n    <div v-if=\"showShareModal\" class=\"share-modal-overlay\" @click.self=\"closeShareModal\">\r\n      <div class=\"share-modal\">\r\n        <h3>Paylaş</h3>\r\n        <div class=\"social-icons\">\r\n          <a :href=\"`https://www.facebook.com/sharer/sharer.php?u=${shareUrl}`\" target=\"_blank\">\r\n            <img src=\"@/assets/icons/facebook.png\" alt=\"Facebook\" />\r\n          </a>\r\n          <a :href=\"`https://twitter.com/intent/tweet?url=${shareUrl}&text=${gameDetails.game_name}`\" target=\"_blank\">\r\n            <img src=\"@/assets/icons/twitter.png\" alt=\"Twitter\" />\r\n          </a>\r\n          <a :href=\"`https://t.me/share/url?url=${shareUrl}`\" target=\"_blank\">\r\n            <img src=\"@/assets/icons/telegram.png\" alt=\"Telegram\" />\r\n          </a>\r\n          <a :href=\"`https://api.whatsapp.com/send?text=${shareUrl}`\" target=\"_blank\">\r\n            <img src=\"@/assets/icons/whatsapp.png\" alt=\"WhatsApp\" />\r\n          </a>\r\n          \r\n        </div>\r\n        <button class=\"close-btn\" @click=\"closeShareModal\">Kapat</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from \"axios\";\r\nimport { mapGetters } from \"vuex\";\r\n\r\nexport default {\r\n  name: \"GameStart\",\r\n  data() {\r\n    return {\r\n      gameDetails: {},\r\n      gameUrl: \"\",\r\n      isLoading: false,\r\n      isFavorite: false,\r\n      showShareModal: false,\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters([\"authUser\"]),\r\n    shareUrl() {\r\n      return window.location.href;\r\n    }\r\n  },\r\n  async mounted() {\r\n    this.isLoading = true;\r\n\r\n    try {\r\n      const gameId = this.$route.params.id;\r\n      const gameResponse = await axios.get(`/games/${gameId}`);\r\n\r\n      if (gameResponse.data.success) {\r\n        this.gameDetails = gameResponse.data.data;\r\n        const distribution = this.gameDetails.distribution?.toLowerCase() || \"\";\r\n\r\n        if (distribution === \"nexus\") {\r\n          await this.launchNexusGame();\r\n        } else if (distribution === \"drakon\") {\r\n          await this.launchDrakonGame();\r\n        } else if (distribution === \"pokerapi\") {\r\n          await this.launchPokerGame();\r\n        } else {\r\n          throw new Error(\"Unsupported game distribution: \" + distribution);\r\n        }\r\n      }\r\n    } catch (error) {\r\n      console.error(\"Error loading game:\", error.message);\r\n      alert(\"Oyun yüklenirken hata oluştu: \" + error.message);\r\n    }\r\n  },\r\n\r\n  methods: {\r\n    onIframeLoad() {\r\n      this.isLoading = false;\r\n    },\r\n    onIframeError() {\r\n      console.error(\"Iframe yüklenirken bir hata oluştu.\");\r\n      this.isLoading = false;\r\n    },\r\n\r\n// 🎯 POKERAPI GAME LAUNCH (Yeni /launch endpoint)\r\nasync launchPokerGame() {\r\n  try {\r\n    const response = await axios.post(\"/launch\", {\r\n      user_id: this.authUser?.user?.phone,\r\n      provider_code: this.gameDetails.provider_code,\r\n      game_uuid: this.gameDetails.game_code,\r\n      currency: \"BRL\",\r\n      lang: this.$i18n.locale || \"pt\",\r\n      type: \"slot\"\r\n    });\r\n\r\n    console.log(\"🎯 PokerAPI Launch Response:\", response.data);\r\n\r\n    // ✅ Yeni backend, başarılı yanıt olarak \"status:1\" ve \"game_url\" döndürüyor\r\n    if (response.data.status === 1 && response.data.game_url) {\r\n      this.gameUrl = response.data.game_url;\r\n\r\n      // 🎮 oyunu iframe yerine yeni sekmede açmak istersen:\r\n      // window.open(this.gameUrl, \"_blank\");\r\n\r\n      console.log(\"✅ Game launch success:\", this.gameUrl);\r\n    } else {\r\n      console.error(\"⚠️ Game launch failed:\", response.data);\r\n      throw new Error(response.data.msg || \"Failed to launch PokerAPI game.\");\r\n    }\r\n  } catch (error) {\r\n    console.error(\"❌ Error launching PokerAPI game:\", error);\r\n    alert(\"Poker oyunu başlatılamadı: \" + (error.response?.data?.msg || error.message));\r\n  }\r\n},\r\n\r\n    // 🎯 NEXUS GAME LAUNCH\r\n    async launchNexusGame() {\r\n      try {\r\n        const response = await axios.post(\"/gold_api\", {\r\n          method: \"game_launch\",\r\n          user_code: this.authUser?.user?._id,\r\n          provider_code: this.gameDetails.provider_code,\r\n          game_code: this.gameDetails.game_code,\r\n          lang: this.$i18n.locale,\r\n        });\r\n\r\n        if (response.data.status === 1 && response.data.launch_url) {\r\n          this.gameUrl = response.data.launch_url;\r\n        } else {\r\n          throw new Error(response.data.msg || \"Failed to launch Nexus game.\");\r\n        }\r\n      } catch (error) {\r\n        console.error(\"Error launching Nexus game:\", error.message);\r\n        throw error;\r\n      }\r\n    },\r\n\r\n    // 🎯 DRAKON GAME LAUNCH\r\n    async launchDrakonGame() {\r\n      try {\r\n        await axios.post(\"/drakon_api\", { method: \"authenticate\" });\r\n        const response = await axios.post(\"/drakon_api\", {\r\n          method: \"game_launch\",\r\n          user_id: this.authUser?.user?.phone,\r\n          game_id: this.gameDetails.game_code,\r\n          lang: this.$i18n.locale,\r\n          use_iframe: true,\r\n        });\r\n\r\n        if (response.data.status === 1) {\r\n          this.gameUrl = response.data.game_url || response.data.iframe_url;\r\n        } else {\r\n          throw new Error(response.data.msg || \"Failed to launch Drakon game.\");\r\n        }\r\n      } catch (error) {\r\n        console.error(\"Error launching Drakon game:\", error.message);\r\n        throw error;\r\n      }\r\n    },\r\n\r\n    toggleFavorite() {\r\n      this.isFavorite = !this.isFavorite;\r\n      alert(this.isFavorite ? \"Favorilere eklendi!\" : \"Favorilerden çıkarıldı!\");\r\n    },\r\n    openShareModal() {\r\n      this.showShareModal = true;\r\n    },\r\n    closeShareModal() {\r\n      this.showShareModal = false;\r\n    },\r\n    toggleMovieMode() {\r\n      const iframe = document.querySelector(\".iframe-wrapper\");\r\n      iframe.classList.toggle(\"movie-mode\");\r\n    },\r\n    toggleFullscreen() {\r\n      const iframeContainer = document.querySelector(\".iframe-wrapper\");\r\n      if (iframeContainer.requestFullscreen) {\r\n        iframeContainer.requestFullscreen();\r\n      } else if (iframeContainer.webkitRequestFullscreen) {\r\n        iframeContainer.webkitRequestFullscreen();\r\n      } else if (iframeContainer.msRequestFullscreen) {\r\n        iframeContainer.msRequestFullscreen();\r\n      }\r\n    },\r\n  },\r\n};\r\n</script>\r\n\r\n\r\n<style scoped>\r\n/* === CONTAINER === */\r\n.game-start-container {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 20px;\r\n  color: #fff;\r\n  font-family: var(--font-header);\r\n  padding: 15px;\r\n}\r\n\r\n/* === IFRAME === */\r\n.iframe-wrapper {\r\n  position: relative;\r\n  width: 100%;\r\n  height: 70vh;\r\n  background: #000;\r\n  border-radius: 12px;\r\n  overflow: hidden;\r\n  box-shadow: 0 4px 25px rgba(0,0,0,0.6);\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.iframe-wrapper.movie-mode {\r\n  position: fixed;\r\n  top: 60px;\r\n  left: 0;\r\n  right: 0;\r\n  bottom: 0;\r\n  height: calc(100vh - 60px);\r\n  z-index: 1000;\r\n  border-radius: 0;\r\n}\r\n\r\n.game-iframe {\r\n  width: 100%;\r\n  height: 100%;\r\n  border: none;\r\n}\r\n\r\n.loading-placeholder {\r\n  position: absolute;\r\n  inset: 0;\r\n  background: #111;\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  font-size: 18px;\r\n}\r\n\r\n/* === GAME INFO === */\r\n.game-info {\r\n  background: var(--background);\r\n  border-radius: 12px;\r\n  padding: 15px 20px;\r\n}\r\n\r\n.game-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 15px;\r\n}\r\n\r\n.game-header h1 {\r\n  font-size: 20px;\r\n  font-weight: 700;\r\n  margin: 0;\r\n  color: #7b6cb9;\r\n}\r\n\r\n.game-header .provider {\r\n  background: var(--background2);\r\n  padding: 5px 12px;\r\n  border-radius: 6px;\r\n  font-size: 13px;\r\n  color: #ccc;\r\n}\r\n\r\n/* === CONTROLS === */\r\n.game-controls {\r\n  display: flex;\r\n  flex-wrap: wrap;\r\n  gap: 12px;\r\n  align-items: center;\r\n}\r\n\r\n.control-btn {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  background: var(--background1);\r\n  border: none;\r\n  padding: 8px 12px;\r\n  border-radius: 6px;\r\n  font-size: 14px;\r\n  font-weight: 600;\r\n  color: #fff;\r\n  cursor: pointer;\r\n  transition: all 0.2s ease;\r\n}\r\n\r\n \r\n\r\n.divider {\r\n  width: 1px;\r\n  height: 24px;\r\n  background: rgba(255,255,255,0.2);\r\n}\r\n\r\n/* === SHARE MODAL === */\r\n.share-modal-overlay {\r\n  position: fixed;\r\n  inset: 0;\r\n  background: rgba(0,0,0,0.7);\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  z-index: 2000;\r\n}\r\n\r\n.share-modal {\r\n  background: var(--modal-bg);\r\n  padding: 20px;\r\n  border-radius: 12px;\r\n  width: 300px;\r\n  text-align: center;\r\n}\r\n\r\n.share-modal h3 {\r\n  margin-bottom: 15px