		"<template>\r\n  <div class=\"game-history-container\">\r\n    <div class=\"page-header\">\r\n      <h2>{{ $t('profile.gamehistory') }}</h2>\r\n      <div class=\"header-actions\">\r\n        <div class=\"items-per-page-selector\">\r\n          <span>{{ $t('profile.perpage') }}</span>\r\n          <select v-model=\"itemsPerPage\" @change=\"changePageSize\">\r\n            <option value=\"10\">10</option>\r\n            <option value=\"15\">15</option>\r\n            <option value=\"20\">20</option>\r\n            <option value=\"50\">50</option>\r\n          </select>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Loading -->\r\n    <div v-if=\"loading\" class=\"loading-container\">\r\n      <div class=\"spinner\"></div>\r\n      <p>{{ $t('profile.loading...') }}</p>\r\n    </div>\r\n\r\n    <!-- Empty -->\r\n    <div v-else-if=\"gameHistory.length === 0\" class=\"empty-state\">\r\n      <div class=\"empty-icon\">🎮</div>\r\n      <h3>{{ $t('profile.No bets found') }}</h3>\r\n    </div>\r\n\r\n    <!-- Desktop Table -->\r\n    <div v-if=\"!loading && gameHistory.length > 0\" class=\"table-container desktop-table\">\r\n      <table class=\"game-history-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>{{ $t('profile.5') }}</th> <!-- DATE -->\r\n            <th>{{ $t('profile.6') }}</th> <!-- GAME -->\r\n            <th>{{ $t('profile.16') }}</th> <!-- TYPE -->\r\n            <th>{{ $t('profile.Wager') }}</th>\r\n            <th>{{ $t('profile.Win') }}</th>\r\n            <th>{{ $t('profile.balance') }}</th>\r\n            <th>{{ $t('profile.Date') }}</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr v-for=\"(item, index) in gameHistory\" :key=\"index\">\r\n            <td>\r\n              <img :src=\"item.banner\" alt=\"Banner\" class=\"banner-image\" v-if=\"item.banner\" />\r\n              <span v-else>—</span>\r\n            </td>\r\n            <td class=\"game-name\">{{ item.game_name }}</td>\r\n            <td>{{ item.game_type }}</td>\r\n            <td><span class=\"bet-box\">-{{ formatBalance(item.bet_money) }}</span></td>\r\n            <td><span class=\"win-box\">+{{ formatBalance(item.win_money) }}</span></td>\r\n            <td>{{ formatBalance(item.balance_after) }}</td>\r\n            <td class=\"date\">{{ formatDate(item.created_at) }}</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n\r\n    <!-- Mobile Cards -->\r\n    <div v-if=\"!loading && gameHistory.length > 0\" class=\"mobile-cards\">\r\n      <div v-for=\"(item, index) in gameHistory\" :key=\"index\" class=\"card\">\r\n        <div class=\"card-header\">\r\n          <div class=\"game-info\">\r\n            <img :src=\"item.banner\" v-if=\"item.banner\" class=\"banner-thumb\" />\r\n            <div class=\"game-meta\">\r\n              <div class=\"game-name\">{{ item.game_name }}</div>\r\n              <div class=\"game-type\">{{ item.game_type }}</div>\r\n            </div>\r\n          </div>\r\n          <div class=\"date\">{{ formatDate(item.created_at) }}</div>\r\n        </div>\r\n        <div class=\"card-content\">\r\n          <div class=\"card-row\">\r\n            <span class=\"label\">{{ $t('profile.Wager') }}:</span>\r\n            <span class=\"value bet-box\">-{{ formatBalance(item.bet_money) }}</span>\r\n          </div>\r\n          <div class=\"card-row\">\r\n            <span class=\"label\">{{ $t('profile.Win') }}:</span>\r\n            <span class=\"value win-box\">+{{ formatBalance(item.win_money) }}</span>\r\n          </div>\r\n          <div class=\"card-row\">\r\n            <span class=\"label\">{{ $t('profile.balance') }}:</span>\r\n            <span class=\"value\">{{ formatBalance(item.balance_after) }}</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Pagination -->\r\n    <div v-if=\"!loading && pagination.totalRecords > 0\" class=\"pagination-container\">\r\n      <div class=\"pagination-info\">\r\n        {{ $t('profile.shown') }}\r\n        {{ (pagination.currentPage - 1) * pagination.pageSize + 1 }}-\r\n        {{ Math.min(pagination.currentPage * pagination.pageSize, pagination.totalRecords) }}\r\n        {{ $t('profile.total') }} {{ pagination.totalRecords }} {{ $t('profile.from the record') }}\r\n      </div>\r\n      <div class=\"pagination\">\r\n        <button @click=\"prevPage\" :disabled=\"pagination.currentPage === 1\" class=\"pagination-btn\">&lt;</button>\r\n        <button v-for=\"page in visiblePages\" :key=\"page\" @click=\"goToPage(page)\" :class=\"{ active: pagination.currentPage === page }\" class=\"page-btn\">\r\n          {{ page }}\r\n        </button>\r\n        <button @click=\"nextPage\" :disabled=\"pagination.currentPage === pagination.totalPages\" class=\"pagination-btn\">&gt;</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters } from 'vuex';\r\nimport axios from 'axios';\r\n\r\nexport default {\r\n  data() {\r\n    return {\r\n      gameHistory: [],\r\n      loading: true,\r\n      pagination: {\r\n        totalRecords: 0,\r\n        totalPages: 0,\r\n        currentPage: 1,\r\n        pageSize: 15\r\n      },\r\n      maxVisiblePages: 5\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser']),\r\n    visiblePages() {\r\n      const half = Math.floor(this.maxVisiblePages / 2);\r\n      let start = Math.max(1, this.pagination.currentPage - half);\r\n      let end = Math.min(this.pagination.totalPages, start + this.maxVisiblePages - 1);\r\n      if (end - start < this.maxVisiblePages - 1) {\r\n        start = Math.max(1, end - this.maxVisiblePages + 1);\r\n      }\r\n      return Array.from({ length: end - start + 1 }, (_, i) => start + i);\r\n    }\r\n  },\r\n  mounted() {\r\n    this.fetchGameHistory();\r\n  },\r\n  methods: {\r\n    async fetchGameHistory() {\r\n      try {\r\n        this.loading = true;\r\n        const userIdentifier = this.authUser.user.phone;\r\n        const res = await axios.get(`/game-history/${userIdentifier}?page=${this.pagination.currentPage}&limit=${this.pagination.pageSize}`);\r\n        this.gameHistory = res.data.history || [];\r\n        this.pagination = res.data.pagination || this.pagination;\r\n      } catch (err) {\r\n        console.error('Game history error:', err);\r\n      } finally {\r\n        this.loading = false;\r\n      }\r\n    },\r\n    changePageSize() {\r\n      this.pagination.pageSize = parseInt(this.pagination.pageSize);\r\n      this.pagination.currentPage = 1;\r\n      this.fetchGameHistory();\r\n    },\r\n    formatDate(d) {\r\n      if (!d) return '-';\r\n      return new Date(d).toLocaleDateString('tr-TR', {\r\n        year: 'numeric', month: '2-digit', day: '2-digit',\r\n        hour: '2-digit', minute: '2-digit'\r\n      });\r\n    },\r\n    formatBalance(v) {\r\n      if (v === null || v === undefined) return '-';\r\n      return Number(v).toFixed(3);\r\n    },\r\n    prevPage() {\r\n      if (this.pagination.currentPage > 1) {\r\n        this.pagination.currentPage--;\r\n        this.fetchGameHistory();\r\n      }\r\n    },\r\n    nextPage() {\r\n      if (this.pagination.currentPage < this.pagination.totalPages) {\r\n        this.pagination.currentPage++;\r\n        this.fetchGameHistory();\r\n      }\r\n    },\r\n    goToPage(p) {\r\n      if (p >= 1 && p <= this.pagination.totalPages) {\r\n        this.pagination.currentPage = p;\r\n        this.fetchGameHistory();\r\n      }\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n  \r\n  <style scoped>\r\n  .game-history-container {\r\n  padding: 10px;\r\n\r\n  color: #fff;\r\n \r\n}\r\n\r\n.page-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 24px;\r\n  flex-wrap: wrap;\r\n  gap: 16px;\r\n}\r\n\r\n.page-header h2 {\r\n  margin: 0;\r\n  font-size: 1.75rem;\r\n  font-weight: 700;\r\n  color: #B3BEC1;\r\n}\r\n\r\n.items-per-page-selector {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  background: var(--background2);\r\n  padding: 8px 12px;\r\n  border-radius: 8px;\r\n  display: none;\r\n}\r\n\r\n.items-per-page-selector select {\r\n  background: transparent;\r\n  border: 1px solid rgba(255,255,255,0.1);\r\n  border-radius: 4px;\r\n  color: #fff;\r\n  padding: 4px 8px;\r\n}\r\n\r\n/* Loading & empty */\r\n.loading-container, .empty-state {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  padding: 60px 20px;\r\n  gap: 16px;\r\n  color: #aaa;\r\n}\r\n\r\n.spinner {\r\n  width: 40px; height: 40px;\r\n  border: 4px solid rgba(255,255,255,0.1);\r\n  border-left: 4px solid #01e0a3;\r\n  border-radius: 50%;\r\n  animation: spin 1s linear infinite;\r\n}\r\n@keyframes spin { 100% { transform: rotate(360deg);} }\r\n\r\n/* Table */\r\n.table-container {\r\n  overflow-x: auto;\r\n  border-radius: 8px;\r\n  margin: 20px 0;\r\n}\r\n.game-history-table {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  background: var(--background2);\r\n}\r\n.game-history-table th {\r\n  background: rgba(0,0,0,0.2);\r\n  color: #B3BEC1;\r\n  padding: 14px;\r\n  font-weight: 600;\r\n}\r\n.game-history-table td {\r\n  padding: 14px;\r\n  border-bottom: 1px solid rgba(255,255,255,0.05);\r\n}\r\n.game-history-table tbody tr:nth-child(odd) {\r\n  background: rgba(255,255,255,0.02);\r\n}\r\n.game-history-table tbody tr:hover {\r\n  background: rgba(0,0,0,0.15);\r\n}\r\n.banner-image {\r\n  width: 100px;\r\n  border-radius: 6px;\r\n}\r\n\r\n/* Bet/Win styles */\r\n.bet-box {\r\n  background: rgba(255,82,82,0.15);\r\n  color: #ff5252;\r\n  padding: 3px 8px;\r\n  border-radius: 6px;\r\n  font-weight: 600;\r\n}\r\n.win-box {\r\n  background: rgba(0,255,194,0.15);\r\n  color: #01e0a3;\r\n  padding: 3px 8px;\r\n  border-radius: 6px;\r\n  font-weight: 600;\r\n}\r\n.date { color: #aaa; }\r\n\r\n/* Mobile Cards */\r\n.mobile-cards {\r\n  display: none;\r\n  gap: 12px;\r\n}\r\n.card {\r\n  background: var(--background2);\r\n  border-radius: 12px;\r\n  padding: 16px;\r\n  box-shadow: 0 2px 8px rgba(0,0,0,0.1);\r\n}\r\n.card-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  border-bottom: 1px solid rgba(255,255,255,0.05);\r\n  margin-bottom: 12px;\r\n  padding-bottom: 12px;\r\n}\r\n.game-info {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n.banner-thumb {\r\n  width: 50px; height: 50px;\r\n  border-radius: 6px;\r\n  object-fit: cover;\r\n}\r\n.game-meta .game-name {\r\n  font-weight: 600;\r\n}\r\n.game-meta .game-type {\r\n  font-size: 0.85rem;\r\n  color: #aaa;\r\n}\r\n.card-content { display: flex; flex-direction: column; gap: 8px; }\r\n.card-row { display: flex; justify-content: space-between; }\r\n.label { font-weight: 600; color: #B3BEC1; }\r\n.value { font-weight: 600; }\r\n\r\n/* Pagination */\r\n.pagination-container {\r\n  display: flex; justify-content: space-between; align-items: center;\r\n  margin-top: 20px; flex-wrap: wrap; gap: 12px;\r\n}\r\n.pagination-info { font-size: 0.9rem; color: #aaa; }\r\n.pagination { display: flex; gap: 6px; }\r\n.pagination-btn, .page-btn {\r\n  width: 36px; height: 36px;\r\n  border-radius: 8px;\r\n  background: var(--background2);\r\n  color: #fff;\r\n  font-weight: 600;\r\n  border: none; cursor: pointer;\r\n}\r\n.page-btn.active {\r\n  background: #01e0a3;\r\n  color: #000;\r\n}\r\n.pagination-btn:disabled { opacity: 0.5; cursor: not-allowed; }\r\n\r\n/* Responsive */\r\n@media (max-width: 768px) {\r\n  .desktop-table { display: none; }\r\n  .mobile-cards { display: flex; flex-direction: column; }\r\n}\r\n\r\n  </style>",
