		"<template>\r\n  <div class=\"transaction-history-container\">\r\n    <div class=\"page-header\">\r\n      <h2>{{ $t('İşlem Geçmişi') }}</h2>\r\n      <div class=\"header-actions\">\r\n        <div class=\"items-per-page-selector\">\r\n          <span>{{ $t('profile.perpage') }}:</span>\r\n          <select v-model=\"itemsPerPage\" @change=\"currentPage = 1\">\r\n            <option value=\"10\">10</option>\r\n            <option value=\"15\">15</option>\r\n            <option value=\"20\">20</option>\r\n            <option value=\"50\">50</option>\r\n          </select>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Filtreleme Butonları -->\r\n    <div class=\"filter-section\">\r\n      <div class=\"filter-buttons\">\r\n        <button\r\n          :class=\"{ active: activeFilter === 'deposit' }\"\r\n          @click=\"setFilter('deposit')\"\r\n          class=\"filter-btn\"\r\n        >\r\n          <span class=\"btn-icon\">↓</span>\r\n          {{ $t('profile.Deposit') }}\r\n        </button>\r\n        <button\r\n          :class=\"{ active: activeFilter === 'withdrawal' }\"\r\n          @click=\"setFilter('withdrawal')\"\r\n          class=\"filter-btn\"\r\n        >\r\n          <span class=\"btn-icon\">↑</span>\r\n          {{ $t('profile.Withdrawal') }}\r\n        </button>\r\n      </div>\r\n      \r\n      <div class=\"results-info\" v-if=\"!loading\">\r\n        <span class=\"results-count\">{{ filteredTransactions.length }} {{ $t('profile.result found') }}</span>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Yükleniyor Durumu -->\r\n    <div v-if=\"loading\" class=\"loading-container\">\r\n      <div class=\"spinner\"></div>\r\n      <p>{{ $t('profile.loading...') }}</p>\r\n    </div>\r\n\r\n    <!-- Veri Yoksa -->\r\n    <div v-else-if=\"filteredTransactions.length === 0\" class=\"empty-state\">\r\n      <div class=\"empty-icon\">📋</div>\r\n      <h3>{{ $t('profile.There are no transactions yet') }}</h3>\r\n      <p>{{ $t('profile.No action found matching this filter.') }}</p>\r\n    </div>\r\n\r\n <!-- Masaüstü Tablo -->\r\n<div v-if=\"!loading && filteredTransactions.length > 0\" class=\"table-container desktop-table\">\r\n  <table class=\"transaction-table\">\r\n    <thead>\r\n      <tr>\r\n        <th>{{ $t('profile.Transaction Type') }}</th>\r\n        <th>{{ $t('profile.Amount') }}</th>\r\n        <th>{{ $t('profile.Situation') }}</th>\r\n        <th>{{ $t('profile.Date') }}</th>\r\n      </tr>\r\n    </thead>\r\n    <tbody>\r\n      <tr v-for=\"(transaction, index) in paginatedTransactions\" :key=\"index\">\r\n        <td>\r\n          <div class=\"transaction-type\">\r\n            <span class=\"type-icon\" :class=\"transaction.type\">\r\n              {{ transaction.type === 'deposit' ? '↓' : '↑' }}\r\n            </span>\r\n            {{ transaction.type === 'deposit' ? $t('profile.Deposit') : $t('profile.Withdrawal') }}\r\n          </div>\r\n        </td>\r\n        <td class=\"amount\">{{ formatAmount(transaction.amount) }}</td>\r\n        <td>\r\n          <span :class=\"['status-badge', getStatusClass(transaction.status || transaction.state)]\">\r\n            {{ getStatusText(transaction.status || transaction.state) }}\r\n          </span>\r\n        </td>\r\n        <td class=\"date\">{{ formatDate(transaction.createdAt) }}</td>\r\n      </tr>\r\n    </tbody>\r\n  </table>\r\n</div>\r\n\r\n<!-- Mobil Kart Görünümü -->\r\n<div v-if=\"!loading && filteredTransactions.length > 0\" class=\"mobile-cards\">\r\n  <div v-for=\"(transaction, index) in paginatedTransactions\" :key=\"index\" class=\"card\">\r\n    <div class=\"card-header\">\r\n      <div class=\"transaction-type\">\r\n        <span class=\"type-icon\" :class=\"transaction.type\">\r\n          {{ transaction.type === 'deposit' ? '↓' : '↑' }}\r\n        </span>\r\n        {{ transaction.type === 'deposit' ? $t('profile.Deposit') : $t('profile.Withdrawal') }}\r\n      </div>\r\n      <span :class=\"['status-badge', getStatusClass(transaction.status || transaction.state)]\">\r\n        {{ getStatusText(transaction.status || transaction.state) }}\r\n      </span>\r\n    </div>\r\n    <div class=\"card-content\">\r\n      <div class=\"card-row\">\r\n        <span class=\"label\">{{ $t('profile.Amount') }}:</span>\r\n        <span class=\"value amount\">{{ formatAmount(transaction.amount) }}</span>\r\n      </div>\r\n      <div class=\"card-row\">\r\n        <span class=\"label\">{{ $t('profile.Date') }}:</span>\r\n        <span class=\"value date\">{{ formatDate(transaction.createdAt) }}</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n\r\n    <!-- Sayfalandırma -->\r\n    <div v-if=\"!loading && filteredTransactions.length > 0\" class=\"pagination-container\">\r\n      <div class=\"pagination-info\">\r\n        {{ $t('profile.shown') }} {{ (currentPage - 1) * itemsPerPage + 1 }}-{{ Math.min(currentPage * itemsPerPage, filteredTransactions.length) }} {{ $t('profile.total') }} {{ filteredTransactions.length }} {{ $t('profile.from the record') }}\r\n      </div>\r\n      <div class=\"pagination\">\r\n        <button \r\n          @click=\"prevPage\" \r\n          :disabled=\"currentPage === 1\" \r\n          class=\"pagination-btn\"\r\n          aria-label=\"Önceki sayfa\"\r\n        >\r\n          &lt;\r\n        </button>\r\n        \r\n        <div class=\"page-numbers\">\r\n          <button \r\n            v-for=\"page in visiblePages\" \r\n            :key=\"page\"\r\n            @click=\"goToPage(page)\"\r\n            :class=\"{ active: currentPage === page }\"\r\n            class=\"page-btn\"\r\n          >\r\n            {{ page }}\r\n          </button>\r\n          <span v-if=\"showEllipsis\" class=\"ellipsis\">...</span>\r\n        </div>\r\n        \r\n        <button \r\n          @click=\"nextPage\" \r\n          :disabled=\"currentPage === totalPages\" \r\n          class=\"pagination-btn\"\r\n          aria-label=\"Sonraki sayfa\"\r\n        >\r\n          &gt;\r\n        </button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters } from 'vuex';\r\nimport axios from 'axios';\r\n\r\nexport default {\r\n  data() {\r\n    return {\r\n      transactions: [],\r\n      activeFilter: 'deposit',\r\n      currentPage: 1,\r\n      itemsPerPage: 15,\r\n      loading: true,\r\n      maxVisiblePages: 5\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser']),\r\n    \r\n    filteredTransactions() {\r\n      if (!this.transactions) return [];\r\n      return this.transactions.filter(\r\n        (transaction) => {\r\n          const type = transaction.type === 'withdraw' ? 'withdrawal' : transaction.type;\r\n          return type === this.activeFilter;\r\n        }\r\n      );\r\n    },\r\n    \r\n    paginatedTransactions() {\r\n      const start = (this.currentPage - 1) * this.itemsPerPage;\r\n      const end = start + this.itemsPerPage;\r\n      return this.filteredTransactions.slice(start, end);\r\n    },\r\n    \r\n    totalPages() {\r\n      return Math.ceil(this.filteredTransactions.length / this.itemsPerPage);\r\n    },\r\n    \r\n    visiblePages() {\r\n      const half = Math.floor(this.maxVisiblePages / 2);\r\n      let start = Math.max(1, this.currentPage - half);\r\n      let end = Math.min(this.totalPages, start + this.maxVisiblePages - 1);\r\n      \r\n      if (end - start < this.maxVisiblePages - 1) {\r\n        start = Math.max(1, end - this.maxVisiblePages + 1);\r\n      }\r\n      \r\n      const pages = [];\r\n      for (let i = start; i <= end; i++) {\r\n        pages.push(i);\r\n      }\r\n      return pages;\r\n    },\r\n    \r\n    showEllipsis() {\r\n      return this.totalPages > this.maxVisiblePages && \r\n             Math.max(...this.visiblePages) < this.totalPages;\r\n    }\r\n  },\r\n  watch: {\r\n    activeFilter() {\r\n      this.currentPage = 1;\r\n    }\r\n  },\r\n  mounted() {\r\n    this.fetchTransactionHistory();\r\n  },\r\n  methods: {\r\n    async fetchTransactionHistory() {\r\n      try {\r\n        this.loading = true;\r\n        const userIdentifier = this.authUser.user._id || this.authUser.user.phone;\r\n        const response = await axios.get(`/transaction-history/${userIdentifier}`);\r\n        this.transactions = response.data.transactions || [];\r\n      } catch (error) {\r\n        console.error('İşlem geçmişi çekilirken hata oluştu:', error);\r\n        this.$toast.error('İşlem geçmişi yüklenirken bir hata oluştu');\r\n      } finally {\r\n        this.loading = false;\r\n      }\r\n    },\r\n\r\n    formatAmount(amount) {\r\n  if (!amount && amount !== 0) return '';\r\n  return Number(amount).toFixed(2);\r\n},\r\n\r\n    \r\n    setFilter(filter) {\r\n      this.activeFilter = filter;\r\n    },\r\n    \r\n    getStatusClass(status) {\r\n      const statusLower = status.toLowerCase();\r\n      if (statusLower.includes('pending') || statusLower.includes('beklemede')) {\r\n        return 'status-pending';\r\n      } else if (statusLower.includes('completed') || statusLower.includes('tamamlandı')) {\r\n        return 'status-completed';\r\n      } else if (statusLower.includes('rejected') || statusLower.includes('reddedildi')) {\r\n        return 'status-rejected';\r\n      }\r\n      return '';\r\n    },\r\n    \r\n    getStatusText(status) {\r\n      const statusLower = status.toLowerCase();\r\n      if (statusLower.includes('pending') || statusLower.includes('beklemede')) {\r\n        return this.$t('profile.Pending');\r\n      } else if (statusLower.includes('completed') || statusLower.includes('tamamlandı')) {\r\n        return this.$t('profile.Succes');\r\n      } else if (statusLower.includes('rejected') || statusLower.includes('reddedildi')) {\r\n        return this.$t('profile.Rejected');\r\n      }\r\n      return status;\r\n    },\r\n    \r\n    formatDate(dateString) {\r\n      if (!dateString) return '';\r\n      const date = new Date(dateString);\r\n      return date.toLocaleDateString('tr-TR', {\r\n        year: 'numeric',\r\n        month: '2-digit',\r\n        day: '2-digit',\r\n        hour: '2-digit',\r\n        minute: '2-digit',\r\n      });\r\n    },\r\n    \r\n    prevPage() {\r\n      if (this.currentPage > 1) {\r\n        this.currentPage--;\r\n      }\r\n    },\r\n    \r\n    nextPage() {\r\n      if (this.currentPage < this.totalPages) {\r\n        this.currentPage++;\r\n      }\r\n    },\r\n    \r\n    goToPage(page) {\r\n      if (page >= 1 && page <= this.totalPages) {\r\n        this.currentPage = page;\r\n      }\r\n    }\r\n  },\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.transaction-history-container {\r\n\r\n  \r\n  color: #fff;\r\n \r\n}\r\n\r\n.page-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 24px;\r\n  flex-wrap: wrap;\r\n  gap: 16px;\r\n}\r\n\r\n.page-header h2 {\r\n  margin: 0;\r\n  font-size: 1.75rem;\r\n  font-weight: 700;\r\n  color: #FFD700;\r\n}\r\n\r\n.header-actions {\r\n  display: flex;\r\n  align-items: center;\r\n}\r\n\r\n.items-per-page-selector {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  background: var(--background2);\r\n  padding: 8px 12px;\r\n  border-radius: 8px;\r\n}\r\n\r\n.items-per-page-selector select {\r\n  background: transparent;\r\n  border: 1px solid rgba(255, 255, 255, 0.1);\r\n  border-radius: 4px;\r\n  color: white;\r\n  padding: 4px 8px;\r\n  cursor: pointer;\r\n}\r\n\r\n.filter-section {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 20px;\r\n  flex-wrap: wrap;\r\n  gap: 16px;\r\n}\r\n\r\n.filter-buttons {\r\n  display: flex;\r\n  gap: 12px;\r\n}\r\n\r\n.filter-btn {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 10px 20px;\r\n  border: none;\r\n  border-radius: 8px;\r\n  cursor: pointer;\r\n  background: var(--background2);\r\n  color: #fff;\r\n  font-weight: 600;\r\n  transition: all 0.3s ease;\r\n}\r\n\r\n.filter-btn:hover {\r\n  background: rgba(0, 255, 194, 0.1);\r\n}\r\n\r\n.filter-btn.active {\r\n  background: var(--button1);\r\n  color: #000;\r\n\r\n}\r\n\r\n.btn-icon {\r\n  font-weight: bold;\r\n}\r\n\r\n.results-info {\r\n  display: flex;\r\n  align-items: center;\r\n}\r\n\r\n.results-count {\r\n  font-size: 0.9rem;\r\n  color: #aaa;\r\n}\r\n\r\n.loading-container {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n  justify-content: center;\r\n  padding: 60px 20px;\r\n  gap: 16px;\r\n}\r\n\r\n.spinner {\r\n  width: 40px;\r\n  height: 40px;\r\n  border: 4px solid rgba(255, 255, 255, 0.1);\r\n  border-left: 4px solid #01e0a3;\r\n  border-radius: 50%;\r\n  animation: spin 1s linear infinite;\r\n}\r\n\r\n@keyframes spin {\r\n  0% { transform: rotate(0deg); }\r\n  100% { transform: rotate(360deg); }\r\n}\r\n\r\n.empty-state {\r\n  text-align: center;\r\n  padding: 60px 20px;\r\n  color: #888;\r\n}\r\n\r\n.empty-icon {\r\n  font-size: 3rem;\r\n  margin-bottom: 16px;\r\n}\r\n\r\n.empty-state h3 {\r\n  margin: 0 0 8px 0;\r\n  font-size: 1.25rem;\r\n  color: #ddd;\r\n}\r\n\r\n.empty-state p {\r\n  margin: 0;\r\n  font-size: 0.95rem;\r\n}\r\n\r\n.table-container {\r\n  overflow-x: auto;\r\n  border-radius: 8px;\r\n  margin: 20px 0;\r\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);\r\n}\r\n\r\n.transaction-table {\r\n  width: 100%;\r\n  border-collapse: collapse;\r\n  background: var(--background2);\r\n  border-radius: 8px;\r\n  overflow: hidden;\r\n}\r\n\r\n.transaction-table th {\r\n  background-color: rgba(0, 0, 0, 0.2);\r\n  color: #fff;\r\n  font-weight: 600;\r\n  padding: 16px;\r\n  text-align: left;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.1);\r\n}\r\n\r\n.transaction-table td {\r\n  padding: 16px;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.transaction-table tbody tr:last-child td {\r\n  border-bottom: none;\r\n}\r\n\r\n.transaction-table tbody tr:hover {\r\n  background-color: rgba(0, 0, 0, 0.1);\r\n}\r\n\r\n.transaction-type {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n}\r\n\r\n.type-icon {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  width: 28px;\r\n  height: 28px;\r\n  border-radius: 50%;\r\n  font-weight: bold;\r\n}\r\n\r\n.type-icon.deposit {\r\n  background: rgba(0, 255, 194, 0.15);\r\n  color: #01e0a3;\r\n}\r\n\r\n.type-icon.withdraw, .type-icon.withdrawal {\r\n  background: rgba(255, 82, 82, 0.15);\r\n  color: #ff5252;\r\n}\r\n\r\n.amount {\r\n  font-weight: 600;\r\n  color: #fff;\r\n}\r\n\r\n.date {\r\n  color: #aaa;\r\n}\r\n\r\n.status-badge {\r\n  padding: 6px 12px;\r\n  border-radius: 20px;\r\n  font-size: 0.85rem;\r\n  font-weight: 600;\r\n  text-transform: capitalize;\r\n  display: inline-block;\r\n}\r\n\r\n.status-pending {\r\n  background: rgba(255, 204, 0, 0.15);\r\n  color: #ffcc00;\r\n}\r\n\r\n.status-completed {\r\n  background: rgba(0, 204, 102, 0.15);\r\n  color: #00cc66;\r\n}\r\n\r\n.status-rejected {\r\n  background: rgba(255, 51, 51, 0.15);\r\n  color: #ff3333;\r\n}\r\n\r\n.mobile-cards {\r\n  display: none;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n  margin: 20px 0;\r\n}\r\n\r\n.card {\r\n  background: var(--background2);\r\n  border-radius: 12px;\r\n  padding: 16px;\r\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);\r\n}\r\n\r\n.card-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  margin-bottom: 12px;\r\n  padding-bottom: 12px;\r\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\r\n}\r\n\r\n.card-content {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 8px;\r\n}\r\n\r\n.card-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n}\r\n\r\n.card-row .label {\r\n  font-weight: 600;\r\n  color: #FFD700;\r\n}\r\n\r\n.card-row .value {\r\n  font-weight: 500;\r\n  color: #fff;\r\n}\r\n\r\n.pagination-container {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  m