		"<template>\r\n  <div class=\"bonus-history-container\">\r\n    <div class=\"page-header\">\r\n      <h2>{{ $t('profile.bonushistory') }}</h2>\r\n      <div class=\"header-actions\">\r\n        \r\n      </div>\r\n    </div>\r\n\r\n    <!-- Loading -->\r\n    <div v-if=\"loading\" class=\"loading-container\">\r\n      <div class=\"spinner\"></div>\r\n      <p>{{ $t('profile.loadingBonuses') }}</p>\r\n    </div>\r\n\r\n    <!-- Empty -->\r\n    <div v-else-if=\"filteredBonuses.length === 0\" class=\"empty-state\">\r\n      <div class=\"empty-icon\">🎁</div>\r\n      <h3>{{ $t('profile.noBonuses') }}</h3>\r\n    </div>\r\n\r\n    <!-- Desktop Table -->\r\n    <div v-if=\"!loading && filteredBonuses.length > 0\" class=\"table-container desktop-table\">\r\n      <table class=\"bonus-table\">\r\n        <thead>\r\n          <tr>\r\n            <th>{{ $t('profile.bonusType') }}</th>\r\n            <th>{{ $t('profile.bonusAmount') }}</th>\r\n            \r\n            <th>{{ $t('profile.Date') }}</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr v-for=\"(bonus, index) in paginatedBonuses\" :key=\"index\">\r\n            <td>{{ $t(`profile.bonusTypes.${bonus.bonusType}`) }}</td>\r\n\r\n            <td class=\"amount\">\r\n  <span class=\"bonus-box\">+{{ formatAmount(bonus.bonusAmount) }}</span>\r\n</td>\r\n\r\n            \r\n            <td class=\"date\">{{ formatDate(bonus.createdAt) }}</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n\r\n    <!-- Mobile Cards -->\r\n    <div v-if=\"!loading && filteredBonuses.length > 0\" class=\"mobile-cards\">\r\n      <div v-for=\"(bonus, index) in paginatedBonuses\" :key=\"index\" class=\"card\">\r\n        <div class=\"card-header\">\r\n          <span class=\"bonus-type\">{{ $t(`profile.bonusTypes.${bonus.bonusType}`) }}</span>\r\n\r\n          <span class=\"value amount\">\r\n  <span class=\"bonus-box\">+{{ formatAmount(bonus.bonusAmount) }}</span>\r\n</span>\r\n\r\n        </div>\r\n        <div class=\"card-content\">\r\n         \r\n          <div class=\"card-row\">\r\n            <span class=\"label\">{{ $t('profile.Date') }}:</span>\r\n            <span class=\"value date\">{{ formatDate(bonus.createdAt) }}</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- Pagination -->\r\n    <div v-if=\"!loading && filteredBonuses.length > 0\" class=\"pagination-container\">\r\n      <div class=\"pagination-info\">\r\n        {{ $t('profile.shown') }} {{ (currentPage - 1) * itemsPerPage + 1 }}-{{ Math.min(currentPage * itemsPerPage, filteredBonuses.length) }}\r\n        {{ $t('profile.total') }} {{ filteredBonuses.length }} {{ $t('profile.from the record') }}\r\n      </div>\r\n      <div class=\"pagination\">\r\n        <button @click=\"prevPage\" :disabled=\"currentPage === 1\" class=\"pagination-btn\">&lt;</button>\r\n        <button v-for=\"page in visiblePages\" :key=\"page\" @click=\"goToPage(page)\" :class=\"{ active: currentPage === page }\" class=\"page-btn\">\r\n          {{ page }}\r\n        </button>\r\n        <button @click=\"nextPage\" :disabled=\"currentPage === totalPages\" class=\"pagination-btn\">&gt;</button>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport { mapGetters } from 'vuex';\r\nimport axios from 'axios';\r\n\r\nexport default {\r\n  data() {\r\n    return {\r\n      bonuses: [],\r\n      currentPage: 1,\r\n      itemsPerPage: 15,\r\n      loading: true,\r\n      maxVisiblePages: 5\r\n    };\r\n  },\r\n  computed: {\r\n    ...mapGetters(['authUser']),\r\n\r\n    filteredBonuses() {\r\n      return this.bonuses || [];\r\n    },\r\n\r\n    paginatedBonuses() {\r\n      const start = (this.currentPage - 1) * this.itemsPerPage;\r\n      return this.filteredBonuses.slice(start, start + this.itemsPerPage);\r\n    },\r\n\r\n    totalPages() {\r\n      return Math.ceil(this.filteredBonuses.length / this.itemsPerPage);\r\n    },\r\n\r\n    visiblePages() {\r\n      const half = Math.floor(this.maxVisiblePages / 2);\r\n      let start = Math.max(1, this.currentPage - half);\r\n      let end = Math.min(this.totalPages, start + this.maxVisiblePages - 1);\r\n      if (end - start < this.maxVisiblePages - 1) {\r\n        start = Math.max(1, end - this.maxVisiblePages + 1);\r\n      }\r\n      return Array.from({ length: end - start + 1 }, (_, i) => start + i);\r\n    }\r\n  },\r\n  mounted() {\r\n    this.fetchBonusHistory();\r\n  },\r\n  methods: {\r\n    async fetchBonusHistory() {\r\n      try {\r\n        this.loading = true;\r\n        const userId = this.authUser.user._id;\r\n        const response = await axios.get(`/bonus-history/${userId}`);\r\n        this.bonuses = response.data.bonuses || [];\r\n      } catch (err) {\r\n        console.error('Bonus history error:', err);\r\n      } finally {\r\n        this.loading = false;\r\n      }\r\n    },\r\n    formatAmount(amount) {\r\n      if (amount === null || amount === undefined) return '-';\r\n      return Number(amount).toFixed(2);\r\n    },\r\n    formatDate(dateStr) {\r\n      if (!dateStr) return '-';\r\n      const d = new Date(dateStr);\r\n      return d.toLocaleDateString('tr-TR', {\r\n        year: 'numeric',\r\n        month: '2-digit',\r\n        day: '2-digit',\r\n        hour: '2-digit',\r\n        minute: '2-digit'\r\n      });\r\n    },\r\n    prevPage() { if (this.currentPage > 1) this.currentPage--; },\r\n    nextPage() { if (this.currentPage < this.totalPages) this.currentPage++; },\r\n    goToPage(page) { this.currentPage = page; }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n\r\n.bonus-history-container {\r\n \r\n  color: #fff;\r\n  \r\n}\r\n\r\n.page-header {\r\n  display: flex;\r\n  justify-content: center;\r\n  align-items: center;\r\n  margin-bottom: 24px;\r\n  flex-wrap: wrap;\r\n  gap: 16px;\r\n}\r\n\r\n.page-header h2 {\r\n  margin: 0;\r\n  font-size: 1.75rem;\r\n  font-weight: 700;\r\n  color: #fff;\r\n}\r\n\r\n.head