		"<template>\r\n  <div v-if=\"remainingSeconds > 0\" class=\"inline-flip-clock\">\r\n    <div class=\"flip-clock-row\">\r\n      <div class=\"flip-unit\">\r\n        <div class=\"flip-card\">\r\n          \r\n          <div class=\"flip-bottom\">{{ formattedDays }}</div>\r\n          <div class=\"flip-animate\" v-if=\"daysChanged\">{{ previousDays }}</div>\r\n        </div>\r\n        <span class=\"flip-label\">GÜN</span>\r\n      </div>\r\n      \r\n      <span class=\"flip-separator\">:</span>\r\n      \r\n      <div class=\"flip-unit\">\r\n        <div class=\"flip-card\">\r\n         \r\n          <div class=\"flip-bottom\">{{ formattedHours }}</div>\r\n          <div class=\"flip-animate\" v-if=\"hoursChanged\">{{ previousHours }}</div>\r\n        </div>\r\n        <span class=\"flip-label\">SAAT</span>\r\n      </div>\r\n      \r\n      <span class=\"flip-separator\">:</span>\r\n      \r\n      <div class=\"flip-unit\">\r\n        <div class=\"flip-card\">\r\n          <div class=\"flip-bottom\">{{ formattedMinutes }}</div>\r\n          <div class=\"flip-animate\" v-if=\"minutesChanged\">{{ previousMinutes }}</div>\r\n        </div>\r\n        <span class=\"flip-label\">DAK</span>\r\n      </div>\r\n      \r\n      <span class=\"flip-separator\">:</span>\r\n      \r\n      <div class=\"flip-unit\">\r\n        <div class=\"flip-card\">\r\n          <div class=\"flip-bottom\">{{ formattedSeconds }}</div>\r\n          <div class=\"flip-animate\" v-if=\"secondsChanged\">{{ previousSeconds }}</div>\r\n        </div>\r\n        <span class=\"flip-label\">SAN</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nexport default {\r\n  props: {\r\n    targetTime: {\r\n      type: String,\r\n      required: true\r\n    }\r\n  },\r\n  data() {\r\n    return {\r\n      remainingSeconds: 0,\r\n      interval: null,\r\n      previousDays: '00',\r\n      previousHours: '00',\r\n      previousMinutes: '00',\r\n      previousSeconds: '00',\r\n      daysChanged: false,\r\n      hoursChanged: false,\r\n      minutesChanged: false,\r\n      secondsChanged: false\r\n    };\r\n  },\r\n  computed: {\r\n    formattedDays() {\r\n      const days = Math.floor(this.remainingSeconds / 86400);\r\n      return String(days).padStart(2, '0');\r\n    },\r\n    formattedHours() {\r\n      const hours = Math.floor((this.remainingSeconds % 86400) / 3600);\r\n      return String(hours).padStart(2, '0');\r\n    },\r\n    formattedMinutes() {\r\n      const minutes = Math.floor((this.remainingSeconds % 3600) / 60);\r\n      return String(minutes).padStart(2, '0');\r\n    },\r\n    formattedSeconds() {\r\n      const seconds = this.remainingSeconds % 60;\r\n      return String(seconds).padStart(2, '0');\r\n    }\r\n  },\r\n  watch: {\r\n    formattedDays(newVal, oldVal) {\r\n      if (newVal !== oldVal) {\r\n        this.previousDays = oldVal;\r\n        this.daysChanged = true;\r\n        setTimeout(() => this.daysChanged = false, 600);\r\n      }\r\n    },\r\n    formattedHours(newVal, oldVal) {\r\n      if (newVal !== oldVal) {\r\n        this.previousHours = oldVal;\r\n        this.hoursChanged = true;\r\n        setTimeout(() => this.hoursChanged = false, 600);\r\n      }\r\n    },\r\n    formattedMinutes(newVal, oldVal) {\r\n      if (newVal !== oldVal) {\r\n        this.previousMinutes = oldVal;\r\n        this.minutesChanged = true;\r\n        setTimeout(() => this.minutesChanged = false, 600);\r\n      }\r\n    },\r\n    formattedSeconds(newVal, oldVal) {\r\n      if (newVal !== oldVal) {\r\n        this.previousSeconds = oldVal;\r\n        this.secondsChanged = true;\r\n        setTimeout(() => this.secondsChanged = false, 600);\r\n      }\r\n    }\r\n  },\r\n  mounted() {\r\n    this.updateRemaining();\r\n    this.interval = setInterval(this.updateRemaining, 1000);\r\n  },\r\n  beforeDestroy() {\r\n    clearInterval(this.interval);\r\n  },\r\n  methods: {\r\n    updateRemaining() {\r\n      const now = new Date().getTime();\r\n      const target = new Date(this.targetTime).getTime();\r\n      const diff = Math.max(0, Math.floor((target - now) / 1000));\r\n      this.remainingSeconds = diff;\r\n    }\r\n  }\r\n};\r\n</script>\r\n\r\n<style scoped>\r\n.inline-flip-clock {\r\n \r\n}\r\n\r\n.flip-clock-row {\r\n  display: flex;\r\n  align-items: center;\r\n\r\n}\r\n\r\n.flip-unit {\r\n  display: flex;\r\n  flex-direction: column;\r\n  align-items: center;\r\n}\r\n\r\n.flip-card {\r\n  position: relative;\r\n  width: 28px;\r\n  height: 36px;\r\n  perspective: 500px;\r\n}\r\n\r\n.flip-top,\r\n.flip-bottom,\r\n.flip-animate {\r\n  position: absolute;\r\n  width: 100%;\r\n  height: 18px;\r\n  overflow: hidden;\r\n   \r\n  border-radius: 4px;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  font-size: 14px;\r\n  font-weight: 700;\r\n  color: #fff;\r\n \r\n   \r\n}\r\n\r\n.flip-top {\r\n  top: 0;\r\n  border-bottom: 1px solid rgba(0, 0, 0, 0.2);\r\n  background: linear-gradient(to bottom, #1a2a3a 0%, #0f172a 100%);\r\n  z-index: 2;\r\n  transform-origin: bottom;\r\n}\r\n\r\n.flip-bottom {\r\n  bottom: 0;\r\n  border-top: 1px solid rgba(255, 255, 255, 0.05);\r\n  background: var(--background4);\r\n  z-index: 1;\r\n}\r\n\r\n.flip-animate {\r\n  top: 0;\r\n  background: linear-gradient(to bottom, #1a2a3a 0%, #0f172a 100%);\r\n  z-index: 3;\r\n  transform-origin: bottom;\r\n  animation: flip 0.6s ease-in-out;\r\n  border-bottom: 1px solid rgba(0, 0, 0, 0.2);\r\n}\r\n\r\n.flip-label {\r\n  margin-top: 3px;\r\n  font-size: 10px;\r\n  font-weight: 600;\r\n  color: rgba(255, 255, 255, 0.7);\r\n  text-transform: uppercase;\r\n}\r\n\r\n.flip-separator {\r\n  font-size: 20px;\r\n  font-weight: 700;\r\n  color: #ffea2f;\r\n  \r\n  text-shadow: 0 0 5px rgba(0, 255, 194, 0.5);\r\n}\r\n\r\n@keyframes flip {\r\n  0% {\r\n    transform: rotateX(0deg);\r\n  }\r\n  50% {\r\n    transform: rotateX(-90deg);\r\n  }\r\n  100% {\r\n    transform: rotateX(-180deg);\r\n  }\r\n}\r\n\r\n/* Daha da kompakt versiyon */\r\n@media (max-width: 480px) {\r\n  .flip-card {\r\n    width: 20px;\r\n    height: 30px;\r\n  }\r\n  \r\n  .flip-top,\r\n  .flip-bottom,\r\n  .flip-animate {\r\n    height: 20px;\r\n    font-size: 16px;\r\n  }\r\n  \r\n  .flip-separator {\r\n    font-size: 16px;\r\n    margin-bottom: 8px;\r\n  }\r\n  \r\n  .flip-label {\r\n    font-size: 8px;\r\n  }\r\n}\r\n</style>",
		"import { render } from \"./VipCountdown.vue?vue&type=template&id=604215cb&scoped=true\"\nimport script from \"./VipCountdown.vue?vue&type=script&lang=js\"\nexport * from \"./VipCountdown.vue?vue&type=script&lang=js\"\n\nimport \"./VipCountdown.vue?vue&type=style&index=0&id=604215cb&scoped=true&lang=css\"\n\nimport exportComponent from \"../../node_modules/vue-loader/dist/exportHelper.js\"\nconst __exports__ = /*#__PURE__*/exportComponent(script, [['render',render],['__scopeId',\"data-v-604215cb\"]])\n\nexport default __exports__",
		"import { render } from \"./index.vue?vue&type=template&id=2c97d541&scoped=true\"\nimport script from \"./index.vue?vue&type=script&lang=js\"\nexport * from \"./index.vue?vue&type=script&lang=js\"\n\nimport \"./index.vue?vue&type=style&index=0&id=2c97d541&scoped=true&lang=css\"\n\nimport exportComponent from \"../../../node_modules/vue-loader/dist/exportHelper.js\"\nconst __exports__ = /*#__PURE__*/exportComponent(script, [['render',render],['__scopeId',\"data-v-2c97d541\"]])\n\nexport default __exports__",
		"<template>\r\n  <div class=\"battle-pass-container\">\r\n    <div class=\"pass-header\">\r\n      <div class=\"header-content\">\r\n        <h1 class=\"pass-title\">RivoBit BattlePass</h1>\r\n        <div class=\"season-info\">\r\n          <span class=\"season-badge\">SEASON 1</span>\r\n          <span class=\"time-remaining\">\r\n            <i class=\"fas fa-clock\"></i> Ends in: {{ daysRemaining }} days\r\n          </span>\r\n        </div>\r\n      </div>\r\n      <div class=\"premium-indicator\" :class=\"{ 'active': isPremium }\">\r\n        {{ isPremium ? 'PREMIUM ACTIVE' : 'FREE PASS' }}\r\n      </div>\r\n    </div>\r\n\r\n    <div class=\"pass-content\">\r\n      <div class=\"progress-section\">\r\n        <div class=\"level-display\">\r\n          <div class=\"current-level\">LEVEL {{ currentLevel }}</div>\r\n          <div class=\"level-progress\">\r\n            <div class=\"progress-bar\" :style=\"{ width: progress + '%' }\"></div>\r\n            <div class=\"progress-text\">{{ currentXP }} / {{ xpRequired }} XP ({{ progress }}%)</div>\r\n          </div>\r\n          <div class=\"max-level\">MAX: {{ totalLevels }}</div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"rewards-section\">\r\n        <div class=\"section-header\">\r\n          <h3>LEVEL REWARDS</h3>\r\n          <div class=\"view-toggle\">\r\n            <button :class=\"{ 'active': viewMode === 'free' }\" @click=\"viewMode = 'free'\">Free</button>\r\n            <button :class=\"{ 'active': viewMode === 'premium' }\" @click=\"viewMode = 'premium'\">Premium</button>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"rewards-grid\">\r\n          <div v-for=\"(reward, index) in filteredRewards\" :key=\"index\" class=\"reward-card\" :class=\"{ 'locked': reward.locked, 'premium': reward.isPremium }\">\r\n            <div class=\"reward-tier\">TIER {{ reward.level }}</div>\r\n            <div class=\"reward-icon\">\r\n              <img :src=\"reward.icon\" :alt=\"reward.name\" />\r\n              <div class=\"premium-badge\" v-if=\"reward.isPremium\">PREMIUM</div>\r\n            </div>\r\n            <div class=\"reward-details\">\r\n              <h4>{{ reward.name }}</h4>\r\n              <p class=\"reward-amount\">{{ reward.amount }}</p>\r\n              <p class=\"reward-desc\" v-if=\"reward.description\">{{ reward.description }}</p>\r\n            </div>\r\n            <div class=\"reward-status\">\r\n              <span v-if=\"reward.claimed\" class=\"claimed\">\r\n                <i class=\"fas fa-check-circle\"></i> Claimed\r\n              </span>\r\n              <span v-else-if=\"!reward.locked\" class=\"available\">\r\n                <i class=\"fas fa-gift\"></i> Available\r\n                <button class=\"claim-button\" @click=\"claimReward(reward)\">Claim</button>\r\n              </span>\r\n              <span v-else class=\"locked-status\">\r\n                <i class=\"fas fa-lock\"></i> Locked\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"missions-section\">\r\n        <div class=\"section-header\">\r\n          <h3>MISSIONS</h3>\r\n           <div class=\"missions-tabs\">\r\n    <div class=\"tabs\">\r\n      <button v-for=\"tab in tabs\" :key=\"tab.key\" :class=\"{ active: currentTab === tab.key }\" @click=\"selectTab(tab.key)\">\r\n        {{ tab.label }}\r\n      </button>\r\n    </div>\r\n\r\n    <VipCountdown v-if=\"activeResetTime\" :targetTime=\"activeResetTime\" />\r\n\r\n    <div class=\"missions-list\">\r\n      <div v-for=\"mission in filteredMissions\" :key=\"mission._id\" class=\"mission-item\">\r\n        <img :src=\"resolveImage(mission.img)\" alt=\"mission image\" class=\"mission-img\" />\r\n        <div class=\"mission-content\">\r\n          <h4>{{ mission.name }}</h4>\r\n          <p>{{ mission.description }}</p>\r\n          <div class=\"mission-progress\">\r\n            <div class=\"progress-bar\">\r\n              <div :style=\"{ width: (mission.currentProgress / mission.targetValue) * 100 + '%' }\"></div>\r\n            </div>\r\n            <span>{{ mission.currentProgress }}/{{ mission.targetValue }}</span>\r\n          </div>\r\n        </div>\r\n        <div class=\"mission-reward\">\r\n          <span class=\"xp-reward\">+{{ mission.xpReward }} XP</span>\r\n          <span v-if=\"mission.tokenReward\" class=\"token-reward\">+{{ mission.tokenReward }} <img src=\"/token.png\" alt=\"token\" /></span>\r\n          <button\r\n            class=\"claim-button\"\r\n            :disabled=\"mission.isCompleted || mission.currentProgress < mission.targetValue\"\r\n            @click=\"claimMissionReward(mission)\"\r\n          >\r\n            <span v-if=\"mission.isCompleted\">Claimed</span>\r\n            <span v-else>Claim</span>\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n        </div>\r\n\r\n        <div class=\"missions-list\">\r\n          <div v-for=\"(mission, index) in missions\" :key=\"index\" class=\"mission-item\">\r\n            <div class=\"mission-info\">\r\n              <div class=\"mission-icon\">\r\n                <i :class=\"mission.icon\"></i>\r\n              </div>\r\n              <div class=\"mission-details\">\r\n                <h4>{{ mission.name }}</h4>\r\n                <p>{{ mission.description }}</p>\r\n                <div class=\"mission-progress\">\r\n                  <div class=\"progress-bar\">\r\n                    <div :style=\"{ width: (mission.current / mission.target) * 100 + '%' }\"></div>\r\n                  </div>\r\n                  <span>{{ mission.current }}/{{ mission.target }}</span>\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div class=\"mission-reward\">\r\n              <span class=\"xp-reward\">+{{ mission.xp }} XP</span>\r\n              <span class=\"token-reward\" v-if=\"mission.tokens\">\r\n                +{{ mission.tokens }} <img src=\"https://cryptologos.cc/logos/ethereum-eth-logo.png\" alt=\"ETH\" />\r\n              </span>\r\n              <button class=\"claim-button\" :class=\"{ 'disabled': mission.current < mission.target || mission.lastClaimed }\" @click=\"claimMission(mission)\">Claim</button>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"upgrade-section\" v-if=\"!isPremium\">\r\n        <div class=\"upgrade-content\">\r\n          <div class=\"upgrade-info\">\r\n            <h3>UPGRADE TO PREMIUM PASS</h3>\r\n            <ul class=\"benefits-list\">\r\n              <li><i class=\"fas fa-check\"></i> Unlock all premium rewards</li>\r\n              <li><i class=\"fas fa-check\"></i> +20% XP boost</li>\r\n              <li><i class=\"fas fa-check\"></i> Exclusive tournaments</li>\r\n              <li><i class=\"fas fa-check\"></i> Priority support</li>\r\n            </ul>\r\n          </div>\r\n          <button class=\"upgrade-button\" @click=\"upgradePass\">\r\n            UPGRADE NOW - 200USDT\r\n          </button>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </div>\r\n</template>\r\n\r\n<script>\r\nimport axios from 'axios';\r\nimport { mapGetters } from 'vuex';\r\nimport VipCountdown from '@/components/VipCountdown.vue';\r\n\r\nconst backendUrl = process.env.VUE_APP_BACKEND_URL;\r\n\r\nexport default {\r\n  name: 'ProfessionalBattlePass',\r\n  components: { VipCountdown },\r\n \r\n  data() {\r\n    return {\r\n      currentLevel: 0,\r\n      currentXP: 0,\r\n      xpRequired: 100,\r\n      totalLevels: 20,\r\n      isPremium: false,\r\n      daysRemaining: 0,\r\n      viewMode: 'free',\r\n      resetTime: '8h 23m',\r\n      rewards: [],\r\n      currentTab: 'DAILY',\r\n      tabs: [\r\n        { label: 'Daily Missions', key: 'DAILY' },\r\n        { label: 'Weekly Missions', key: 'WEEKLY' },\r\n        { label: 'Seasonal Missions', key: 'SEASONAL' },\r\n      ],\r\n      missions: [],\r\n      claimedRewardIds: [],\r\n      resetTimestamp: null,\r\n      activeTab: 'daily'\r\n    };\r\n  },\r\n  computed: {\r\n\r\n     filteredMissions() {\r\n      return this.missions.filter(m => m.missionType === this.currentTab);\r\n    },\r\n    activeResetTime() {\r\n      const nextReset = this.filteredMissions[0]?.nextReset;\r\n      return nextReset ? new Date(nextReset) : null;\r\n    },\r\n\r\n\r\n    ...mapGetters(['authUser']),\r\n    progress() {\r\n      return Math.min(Math.round((this.currentXP / this.xpRequired) * 100), 100);\r\n    },\r\n    filteredRewards() {\r\n      let filtered = this.viewMode === 'free'\r\n        ? this.rewards.filter(r => !r.isPremium)\r\n        : this.rewards.filter(r => r.isPremium);\r\n\r\n      return filtered.map(r => {\r\n        const claimed = this.claimedRewardIds.includes(r._id);\r\n        const locked = r.level > this.currentLevel;\r\n        return {\r\n          ...r,\r\n          claimed,\r\n          locked,\r\n          name: (this.viewMode === 'premium' && !this.isPremium) ? 'Premium Reward' : r.name,\r\n          description: (this.viewMode === 'premium' && !this.isPremium) ? 'Upgrade to unlock' : r.description,\r\n          amount: (this.viewMode === 'premium' && !this.isPremium) ? '???' : r.amount\r\n        };\r\n      });\r\n    }\r\n  },\r\n  methods: {\r\n    async fetchBattlePassData() {\r\n      try {\r\n        const res = await axios.get('/battlepass/status', {\r\n          headers: { 'x-auth-token': localStorage.getItem('token') }\r\n        });\r\n        const { season, progress, missions, claimedRewardIds, rewards } = res.data;\r\n\r\n        this.totalLevels = season.totalLevels;\r\n        this.daysRemaining = this.calculateDaysRemaining(season.endDate);\r\n        this.currentLevel = progress.currentLevel;\r\n        this.isPremium = progress.premium;\r\n        this.claimedRewardIds = claimedRewardIds;\r\n        this.currentXP = progress.currentXP;\r\n        this.xpRequired = season.xpPerLevel[progress.currentLevel - 1] || 100;\r\n        this.resetTimestamp = season.endDate;\r\n\r\n        this.rewards = rewards.map(r => ({\r\n          _id: r._id,\r\n          name: r.rewardType,\r\n          amount: r.amount,\r\n          icon: r.img ? `${backendUrl}${r.img}` : 'https://cdn-icons-png.flaticon.com/512/2489/2489737.png',\r\n          isPremium: r.isPremium,\r\n          description: r.description,\r\n          level: r.level\r\n        }));\r\n\r\n        this.missions = missions.map(m => ({\r\n          name: m.name,\r\n          description: m.description,\r\n          icon: 'fas fa-tasks',\r\n          current: m.currentProgress || 0,\r\n          target: m.targetValue,\r\n          xp: m.xpReward,\r\n          tokens: m.tokenReward,\r\n          missionId: m._id,\r\n          isCompleted: m.isCompleted,\r\n          lastClaimed: m.lastClaimed || false\r\n        }));\r\n      } catch (error) {\r\n        console.error('Battle Pass verisi alınamadı:', error);\r\n      }\r\n    },\r\n\r\n    async claimReward(reward) {\r\n      try {\r\n        const res = await axios.post('/battlepass/claim-battlepass-reward', {\r\n          rewardId: reward._id\r\n        }, {\r\n          headers: { 'x-auth-token': localStorage.getItem('token') }\r\n        });\r\n\r\n        this.$toast?.success?.(res.data.message || 'Reward claimed!');\r\n        this.claimedRewardIds.push(reward._id);\r\n\r\n        if (res.data.newBalance !== undefined) {\r\n          this.$store.commit('auth_update_user', {\r\n            ...this.authUser.user,\r\n            balance: res.data.newBalance\r\n          });\r\n        }\r\n\r\n        this.fetchBattlePassData();\r\n      } catch (err) {\r\n        this.$toast?.error?.(err.response?.data?.message || 'Error claiming reward');\r\n      }\r\n    },\r\n\r\n     async claimMissionReward(mission) {\r\n      try {\r\n        const res = await axios.post('/battlepass/claim-mission-reward', {\r\n          missionId: mission._id\r\n        }, {\r\n          headers: { 'x-auth-token': localStorage.getItem('token') }\r\n        });\r\n\r\n        this.$toast?.success?.(res.data.message || 'Mission reward claimed!');\r\n        this.$emit('refresh'); // refresh missions in parent\r\n      } catch (err) {\r\n        this.$toast?.error?.(err.response?.data?.message || 'Claim failed.');\r\n      }\r\n    },\r\n\r\n    async upgradePass() {\r\n      try {\r\n        const res = await axios.post('/battlepass/buy-premium', {}, {\r\n          headers: { 'x-auth-token': localStorage.getItem('token') }\r\n        });\r\n\r\n        this.isPremium = true;\r\n        this.$emit('pass-upgraded');\r\n        this.$toast?.success?.(res.data.message || 'Premium pass activated');\r\n\r\n        if (res.data.user) {\r\n          this.$store.commit('auth_update_user', res.data.user);\r\n        }\r\n\r\n        this.fetchBattlePassData();\r\n      } catch (err) {\r\n        this.$toast?.error?.(err.response?.data?.message || 'Insufficient balance');\r\n      }\r\n    },\r\n\r\n     selectTab(tab) {\r\n      this.currentTab = tab;\r\n    },\r\n    resolveImage(path) {\r\n      return process.env.VUE_APP_BACKEND_URL + path;\r\n    },\r\n\r\n    calculateDaysRemaining(endDate) {\r\n      const now = new Date();\r\n      const end = new Date(endDate);\r\n      const diffTime = end - now;\r\n      return Math.max(Math.ceil(diffTime / (1000 * 60 * 60 * 24)), 0);\r\n    }\r\n  },\r\n  mounted() {\r\n    this.fetchBattlePassData();\r\n  }\r\n};\r\n</script>\r\n\r\n\r\n\r\n\r\n<style scoped>\r\n@import url('https://fonts.googleapis.com/css2?family=Rajdhani:wght@400;500;600;700&display=swap');\r\n@import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/5.15.4/css/all.min.css');\r\n\r\n.battle-pass-container {\r\n  font-family: 'Rajdhani', sans-serif;\r\n  color: #fff;\r\n      background: linear-gradient(135deg, #1a2a3a 0%, #0f172a 100%);\r\n    border-radius: 8px;\r\n    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);\r\n  bord